// ── BACKFILL: add new columns if upgrading from older schema ──
// PERFORMANCE: every request runs these checks. They used to ask
// information_schema once PER column (~100 round-trips per API call, plus
// two unconditional ALTER TABLE … MODIFY statements). On shared MySQL
// hosts information_schema is slow, and together with PHP's session lock
// (which queues a browser's parallel requests one behind the other) that
// made every screen wait. The whole schema is now read in two queries per
// request and answered from memory; any ALTER clears the cache.
function bc_schema_cache(PDO $pdo, bool $reset = false): array {
    static $cache = null;
    if ($reset) { $cache = null; return []; }
    if ($cache !== null) return $cache;
    $cache = ['cols' => [], 'idx' => []];
    try {
        foreach ($pdo->query("SELECT TABLE_NAME, COLUMN_NAME, DATA_TYPE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE()")->fetchAll(PDO::FETCH_NUM) as $r) {
            $cache['cols'][strtolower($r[0])][strtolower($r[1])] = strtolower((string)$r[2]);
        }
        foreach ($pdo->query("SELECT DISTINCT TABLE_NAME, INDEX_NAME FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE()")->fetchAll(PDO::FETCH_NUM) as $r) {
            $cache['idx'][strtolower($r[0])][strtolower($r[1])] = true;
        }
    } catch (Throwable $e) { $cache = null; return ['cols' => null, 'idx' => null]; }
    return $cache;
}
function col_exists(PDO $pdo, $table, $col) {
    $c = bc_schema_cache($pdo);
    if ($c['cols'] === null) {   // cache unavailable: old per-column query
        $s = $pdo->prepare("SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? AND COLUMN_NAME=?");
        $s->execute([$table,$col]);
        return (int)$s->fetchColumn() > 0;
    }
    return isset($c['cols'][strtolower($table)][strtolower($col)]);
}
function col_type(PDO $pdo, $table, $col): string {
    $c = bc_schema_cache($pdo);
    return (string)($c['cols'][strtolower($table)][strtolower($col)] ?? '');
}
function idx_exists(PDO $pdo, $table, $idx) {
    $c = bc_schema_cache($pdo);
    if ($c['idx'] === null) {
        $s = $pdo->prepare("SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? AND INDEX_NAME=?");
        $s->execute([$table,$idx]);
        return (int)$s->fetchColumn() > 0;
    }
    return isset($c['idx'][strtolower($table)][strtolower($idx)]);
}
// Helper: try to alter; swallow failures so a single missing privilege
// doesn't take down the whole API. We log the failure to a side file so
// it's still debuggable. Critical: must NOT throw — earlier versions of
// this script let a single failed ALTER bubble up and the script returned
// an empty body, which the JS layer then logged as "Unexpected end of
// JSON input" with no clue what was wrong.
function try_alter(PDO $pdo, string $sql): void {
    bc_schema_cache($pdo, true);   // the schema is about to change
    try { $pdo->exec($sql); }
    catch (Throwable $e) {
        // Suppress harmless duplicates (column or index already exists).
        // Two concurrent requests can both pass the col_exists() check before
        // either ALTER lands; one wins, the other gets 1060/1061. Silently
        // ignoring keeps migrate.log readable for real failures only.
        $msg = $e->getMessage();
        if (strpos($msg, '1060') !== false || strpos($msg, '1061') !== false ||
            stripos($msg, 'Duplicate column') !== false ||
            stripos($msg, 'Duplicate key name') !== false) {
            return;
        }
        @file_put_contents(__DIR__.'/migrate.log',
            date('c')." ALTER failed: $sql -- ".$msg."\n",
            FILE_APPEND);
    }
}
if (!col_exists($pdo,'bc_conversations','avatar'))      try_alter($pdo, "ALTER TABLE bc_conversations ADD COLUMN avatar TEXT AFTER handle");
if (!col_exists($pdo,'bc_conversations','chat_type'))   try_alter($pdo, "ALTER TABLE bc_conversations ADD COLUMN chat_type VARCHAR(20) DEFAULT 'private' AFTER avatar");
