if (!col_exists($pdo,'bc_conversations','mem_summary')) try_alter($pdo, "ALTER TABLE bc_conversations ADD COLUMN mem_summary VARCHAR(255) DEFAULT '' AFTER auto_reply");
if (!col_exists($pdo,'bc_conversations','account_id'))  try_alter($pdo, "ALTER TABLE bc_conversations ADD COLUMN account_id INT DEFAULT NULL");
if (!idx_exists($pdo,'bc_conversations','idx_agent'))   try_alter($pdo, "ALTER TABLE bc_conversations ADD INDEX idx_agent (agent_id)");
if (!idx_exists($pdo,'bc_conversations','idx_account')) try_alter($pdo, "ALTER TABLE bc_conversations ADD INDEX idx_account (account_id)");
if (!col_exists($pdo,'bc_messages','media_type'))       try_alter($pdo, "ALTER TABLE bc_messages ADD COLUMN media_type VARCHAR(20) DEFAULT '' AFTER content");
if (!col_exists($pdo,'bc_messages','media_url'))        try_alter($pdo, "ALTER TABLE bc_messages ADD COLUMN media_url MEDIUMTEXT AFTER media_type");
