  animation-duration: calc(170s * var(--fx-speed));
}
@keyframes fx-mist-a { from { transform: translate3d(-9%, 1%, 0); } to { transform: translate3d(9%, -1%, 0); } }
@keyframes fx-mist-b { from { transform: translate3d(8%, -1%, 0) scaleX(1.1); } to { transform: translate3d(-8%, 1.5%, 0) scaleX(1); } }
.fxl[data-bg="silk"]::before {
  background: linear-gradient(115deg,
    transparent 32%, var(--s2) 43%, var(--a1) 48.5%, var(--s2) 54%, transparent 65%);
  animation-name: fx-silk-a;
  animation-duration: calc(96s * var(--fx-speed));
}
.fxl[data-bg="silk"]::after {
