}
@keyframes fx-silk-a { from { transform: translate3d(-16%, 3%, 0) rotate(-2deg); } to { transform: translate3d(16%, -3%, 0) rotate(2deg); } }
@keyframes fx-silk-b { from { transform: translate3d(14%, -2%, 0) rotate(2deg); } to { transform: translate3d(-14%, 3%, 0) rotate(-3deg); } }
.fxl[data-bg="waves"]::before {
