}
@keyframes fx-wave-a { from { transform: translate3d(0, -6%, 0) rotate(-2deg) scaleY(1); } to { transform: translate3d(0, 6%, 0) rotate(3deg) scaleY(1.15); } }
@keyframes fx-wave-b { from { transform: translate3d(-3%, 5%, 0) rotate(3deg) scaleY(1.1); } to { transform: translate3d(3%, -5%, 0) rotate(-2deg) scaleY(1); } }
.fxl[data-bg="nebula"]::before {
