}
@keyframes fx-spin     { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
@keyframes fx-spin-rev { from { transform: rotate(0deg); } to { transform: rotate(-360deg); } }
@keyframes fx-breathe  { from { transform: scale(0.94) rotate(-3deg); } to { transform: scale(1.1) rotate(4deg); } }
@keyframes fx-ripple   { from { transform: scale(1); } to { transform: scale(1.15); } }
.fxl[data-bg="gradient"] {
