// The owner's Appearance (Preferences → Appearance), so their contact page
// looks like their app. The app keeps it in the browser; bcSyncPageTheme
// (bot-app.jsx) sends a copy here (dm_page_theme) whenever it changes. Until
// one arrives, the shipped look: Graphite accent, Mist over the Ocean palette.
function dm_page_theme_default(): array {
    return ['accent' => '#8b8fa3', 'bg' => 'mist',
            'c' => ['#14b8a6', '#06b6d4', '#3b82f6', '#2dd4bf'], 'base' => ['#020b10', '#042029', '#061831'],
            'int' => 48, 'solid' => '#0b0d17', 'vig' => true, 'grain' => true, 'glass' => 'balanced', 'speed' => 'medium'];
}
// Everything is checked against what the page's CSS knows, so a stored
// value can never inject anything or leave the page in an unknown state.
function dm_page_theme_clean($in): array {
    $d = dm_page_theme_default();
    if (!is_array($in)) return $d;
    $hex = fn($v) => (is_string($v) && preg_match('/^#[0-9a-fA-F]{6}$/', $v)) ? strtolower($v) : null;
    $list = function ($v, int $n) use ($hex) {
        if (!is_array($v) || count($v) !== $n) return null;
        $o = [];
        foreach (array_values($v) as $x) { $x = $hex($x); if ($x === null) return null; $o[] = $x; }
        return $o;
    };
    $styles = ['aurora','mist','silk','waves','nebula','orbit','bloom','horizon','stardust','eclipse','rings','kaleido','gradient','mesh','spotlight','solid'];
    $out = $d;
    if ($x = $hex($in['accent'] ?? null)) $out['accent'] = $x;
    if (in_array($in['bg'] ?? null, $styles, true)) $out['bg'] = $in['bg'];
    if ($x = $list($in['c'] ?? null, 4)) $out['c'] = $x;
    if ($x = $list($in['base'] ?? null, 3)) $out['base'] = $x;
    if (isset($in['int']) && is_numeric($in['int'])) $out['int'] = (int)max(20, min(100, round((float)$in['int'])));
    if ($x = $hex($in['solid'] ?? null)) $out['solid'] = $x;
    if (isset($in['vig']))   $out['vig'] = (bool)$in['vig'];
    if (isset($in['grain'])) $out['grain'] = (bool)$in['grain'];
    if (in_array($in['glass'] ?? null, ['clear', 'balanced', 'solid'], true)) $out['glass'] = $in['glass'];
    if (in_array($in['speed'] ?? null, ['still', 'slow', 'medium', 'fast'], true)) $out['speed'] = $in['speed'];
    return $out;
}
function dm_page_theme(PDO $pdo, int $acc): array {
    try {
        $q = $pdo->prepare("SELECT page_theme FROM bc_dm_profile WHERE account_id=?");
        $q->execute([$acc]);
        $raw = $q->fetchColumn();
        if ($raw) return dm_page_theme_clean(json_decode((string)$raw, true));
    } catch (Throwable $e) {}
    return dm_page_theme_default();
}

function dm_contact_page(PDO $pdo, string $username): void {
    header('Content-Type: text/html; charset=utf-8');
    header('X-Content-Type-Options: nosniff');
