    if ($ini === '') $ini = '?';
    $palette = ['#7c6ef5','#5ba3e8','#43c98a','#e8a844','#e87070','#9b7ff0','#3ec9d6','#e060c0','#8dc94a','#e8883a'];
    // Same hash as dmColFor() in the app, so the avatar colour matches.
