    $col = $palette[$hc % count($palette)];
    $appDir  = bc_self_app_dir();
    $appUrl  = $appDir . 'BotCommand.html?chat=' . rawurlencode($uname);
    $selfUrl = $live ? dm_share_url($uname) : '';
    $title   = $live ? ($display . ' (@' . $uname . ')') : 'Link not active';
    $desc    = $live ? ('Send @' . $uname . ' an end-to-end encrypted message on BotCommand.') : 'This contact link isn’t active.';
    $ready   = $live && !empty($u['key_id']);
    $prefs    = $live ? dm_contact_prefs($pdo, (int)$u['id']) : ['seen' => false, 'links' => false];
    $presence = $prefs['seen'] ? dm_public_presence($pdo, (int)$u['id']) : null;
    $channels = $prefs['links'] ? dm_public_channels($pdo, (int)$u['id']) : [];
    $th = $live ? dm_page_theme($pdo, (int)$u['id']) : dm_page_theme_default();

    // The theme goes on <html> exactly as the app's bcApplyTheme puts it.
    $an = hexdec(substr($th['accent'], 1));
    $vars = ['--acc' => $th['accent'], '--acc-rgb' => (($an >> 16) & 255) . ',' . (($an >> 8) & 255) . ',' . ($an & 255),
             '--fx-int' => (string)($th['int'] / 100), '--fx-solid' => $th['solid'],
             '--glass-a' => ['clear' => '0.42', 'balanced' => '0.66', 'solid' => '0.9'][$th['glass']]];
    foreach ($th['c'] as $i => $c) $vars['--fx' . ($i + 1)] = $c;
    foreach ($th['base'] as $i => $c) $vars['--fxb' . ($i + 1)] = $c;
    $style = '';
    foreach ($vars as $k => $v) $style .= $k . ':' . $v . ';';
    $pageBg = $th['bg'] === 'solid' ? $th['solid'] : $th['base'][0];

    echo '<!DOCTYPE html><html lang="en" data-bg="' . $h($th['bg']) . '" data-fx-speed="' . $h($th['speed']) . '" data-vignette="' . ($th['vig'] ? '1' : '0') . '" data-grain="' . ($th['grain'] ? '1' : '0') . '" style="' . $h($style) . '"><head><meta charset="utf-8">';
    echo '<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">';
    echo '<title>' . $h($title) . ' · BotCommand</title>';
    echo '<meta name="description" content="' . $h($desc) . '">';
    echo '<meta name="robots" content="noindex">';
    echo '<meta property="og:type" content="profile"><meta property="og:site_name" content="BotCommand">';
    echo '<meta property="og:title" content="' . $h($title) . '"><meta property="og:description" content="' . $h($desc) . '">';
    if ($live) echo '<meta property="og:url" content="' . $h($selfUrl) . '">';
    echo '<meta name="twitter:card" content="summary">';
    echo '<meta name="theme-color" content="' . $h($pageBg) . '">';
    echo '<meta name="color-scheme" content="dark">';
    echo '<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap">';
    // The app's own background (BotCommand.html, "THEME — APP BACKGROUND"),
    // then the page itself, built from the app's sign-in card.
    echo "<style>\n" . DM_PAGE_FX_CSS . "\n";
    echo <<<'CSS'
*,*::before,*::after{box-sizing:border-box}
:root{--t1:#eeeef5;--t2:#9898b4;--t3:#8a8aa8;--t4:#5c5c7a;--ok:#30d158;--glass-a:.66;--acc:#8b8fa3}
html,body{margin:0;min-height:100%}
body{background:var(--fxb1,#0b0d17);color:var(--t1);
  font:400 13px/1.5 'Inter',system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;
  -webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale;text-rendering:optimizeLegibility}
html[data-bg="solid"] body{background:var(--fx-solid)}
::selection{background:rgba(var(--acc-rgb),.38)}
.pg{position:relative;z-index:1;min-height:100vh;min-height:100dvh;display:flex;flex-direction:column;align-items:center;justify-content:center;
  padding:max(28px,env(safe-area-inset-top)) 16px max(28px,env(safe-area-inset-bottom))}

/* Card — the sign-in card's glass. */
.card{position:relative;width:100%;max-width:380px;margin:auto 0;padding:24px 24px 22px;border-radius:20px;text-align:left;
  background:rgba(12,13,24,var(--glass-a));
