@keyframes card-in{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:none}}

/* Copy link — quiet, in the corner. */
.share{position:absolute;top:12px;right:12px;width:32px;height:32px;display:grid;place-items:center;padding:0;
  border:0;border-radius:9px;background:transparent;color:var(--t4);cursor:pointer;transition:background .14s,color .14s}
.share:hover{background:rgba(255,255,255,.06);color:var(--t1)}
.share .ok{display:none;color:var(--t2)}
.share[data-done]{color:var(--t2)}
.share[data-done] .ok{display:block}.share[data-done] .lk{display:none}
.share::after{content:attr(data-tip);position:absolute;top:calc(100% + 6px);right:0;padding:5px 9px;border-radius:8px;white-space:nowrap;
  font-size:11px;font-weight:500;line-height:1.2;color:var(--t1);background:rgba(20,21,34,.96);border:1px solid rgba(255,255,255,.09);
  box-shadow:0 8px 24px -8px rgba(0,0,0,.6);opacity:0;transform:translateY(-2px);pointer-events:none;transition:opacity .14s,transform .14s}
.share:hover::after,.share:focus-visible::after,.share[data-done]::after{opacity:1;transform:none}

/* Identity — avatar left, who they are on the right. */
.who{display:flex;align-items:center;gap:16px;padding-right:34px}
.ava{flex:0 0 auto;width:68px;height:68px;border-radius:50%;overflow:hidden;display:grid;place-items:center;
  font-size:24px;font-weight:600;letter-spacing:-.02em;color:#fff;
  box-shadow:inset 0 0 0 1px rgba(255,255,255,.08)}
.ava img{width:100%;height:100%;object-fit:cover;display:block}
.who-t{flex:1;min-width:0}
