.cta:hover{background:color-mix(in srgb,var(--acc) 60%,#1a1b26)}
.cta svg{opacity:.75}
/* Secondary: chat as a guest, no account. */
.cta2{display:flex;align-items:center;justify-content:center;gap:8px;width:100%;height:40px;margin-top:8px;border-radius:11px;
  font-size:13px;font-weight:500;letter-spacing:-.01em;color:var(--t2);text-decoration:none;
  background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.07);transition:background .14s,color .14s,border-color .14s}
.cta2:hover{background:rgba(255,255,255,.06);color:var(--t1);border-color:rgba(255,255,255,.11)}
.cta2 svg{opacity:.7}
.hint{display:flex;align-items:center;justify-content:center;gap:6px;margin:12px 0 0;font-size:11.5px;color:var(--t3)}
.hint svg{flex-shrink:0;opacity:.8}
/* The card and its footnote, centred together. */
.stack{width:100%;max-width:380px;margin:auto 0;display:flex;flex-direction:column;align-items:center}
