.foot{display:flex;align-items:center;justify-content:center;gap:6px;margin:14px 0 0;font-size:11px;line-height:1.3;
  letter-spacing:.005em;color:rgba(200,202,222,.4);animation:foot-in 700ms 220ms cubic-bezier(.16,1,.3,1) both}
.foot svg{flex-shrink:0;width:11px;height:11px;opacity:.8}
@keyframes foot-in{from{opacity:0}to{opacity:1}}

/* Other ways to contact — secondary, small. */
.alt{margin-top:22px;padding-top:18px;border-top:1px solid rgba(255,255,255,.06);text-align:left}
.alt h2{margin:0 0 8px 2px;font-size:10px;font-weight:600;line-height:1;letter-spacing:.08em;text-transform:uppercase;color:rgba(200,202,222,.42)}
.alt-l{border-radius:12px;background:rgba(0,0,0,.16);border:1px solid rgba(255,255,255,.06);overflow:hidden}
.alt-r{display:flex;align-items:center;gap:10px;width:100%;min-height:40px;margin:0;padding:8px 12px 8px 8px;border:0;background:none;
  font:inherit;font-size:12.5px;text-align:left;color:var(--t2);text-decoration:none;cursor:pointer;transition:background .12s,color .12s}
.alt-r+.alt-r{box-shadow:inset 0 1px 0 rgba(255,255,255,.05)}
.alt-r:hover{background:rgba(255,255,255,.035);color:var(--t1)}
.alt-ic{width:24px;height:24px;flex-shrink:0;display:grid;place-items:center;border-radius:7px}
.alt-ic{color:var(--t2);background:rgba(255,255,255,.05)}
.alt-n{font-weight:500}
.alt-h{flex:1;min-width:0;text-align:right;color:var(--t3);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.alt-go{flex-shrink:0;color:var(--t4);transition:color .12s,transform .12s}
.alt-r:hover .alt-go{color:var(--t2);transform:translate(1px,-1px)}

.share:focus-visible,.cta:focus-visible,.cta2:focus-visible,.alt-r:focus-visible{outline:2px solid rgba(255,255,255,.35);outline-offset:2px}
.alt-r:focus-visible{outline-offset:-2px}
.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}

.card.gone{text-align:center}
.card.gone .ava{margin:6px auto 16px;color:var(--t4);background:rgba(255,255,255,.04);box-shadow:0 0 0 1px rgba(255,255,255,.08)}
.card.gone h1{font-size:18px}
.card.gone .lead{margin:8px auto 0;max-width:30ch;font-size:12.5px;line-height:1.55;color:var(--t3)}
.card.gone .cta{margin-top:22px;background:rgba(255,255,255,.06);box-shadow:inset 0 .5px 0 rgba(255,255,255,.08)}
.card.gone .cta:hover{background:rgba(255,255,255,.09)}

@media (max-width:420px){.card{padding:20px 18px 18px;border-radius:18px}.who{gap:14px}.ava{width:60px;height:60px;font-size:21px}}
@media (prefers-reduced-motion:reduce){.card,.foot{animation:none}}
@supports not ((backdrop-filter:blur(1px)) or (-webkit-backdrop-filter:blur(1px))){.card{background:rgba(14,15,26,.96)}}
</style>
