// ── ROUTER ────────────────────────────────────────────────────
$action = $_GET['action'] ?? $_POST['action'] ?? '';
$body   = json_decode(file_get_contents('php://input'), true) ?? [];
if (!$action && isset($body['action'])) $action = $body['action'];
// Public contact link: api.php?u=<username> renders the landing page.
if (!$action && isset($_GET['u'])) $action = 'contact_page';

// ── OVERSIZE POST DETECTION ────────────────────────────────────
// When an upload (e.g. a base64 file in product.media or product.img)
// exceeds PHP's post_max_size, PHP silently discards the body — so
// $_POST is empty AND php://input is empty. Without this guard the
// request looks like an empty action and the client sees a confusing
// "action required" / 400 error. Surface the real cause so the
// operator gets actionable feedback ("file too big") instead of a
// silent broken Save button.
if (
    ($_SERVER['REQUEST_METHOD'] ?? '') === 'POST'
    && empty($body)
    && empty($_POST)
    && (int)($_SERVER['CONTENT_LENGTH'] ?? 0) > 0
) {
    $limit = ini_get('post_max_size');
    http_response_code(413);
    echo json_encode([
        'error' => "Request body too large for this server (limit: {$limit}). If you uploaded a big image or file to a product, try a smaller one or host it elsewhere and add it as a Link instead.",
    ]);
    exit;
}

// Column set of bc_messages, read once per request. The lifecycle columns
// are added by an ALTER that can fail on a locked-down host, so every path
// that touches them asks first instead of assuming.
function bc_msg_cols(PDO $pdo): array {
    static $cols = null;
    if ($cols !== null) return $cols;
    $cols = [];
    try {
        foreach ($pdo->query("SHOW COLUMNS FROM bc_messages")->fetchAll() as $c) {
            $cols[strtolower((string)$c['Field'])] = true;
        }
    } catch (Throwable $e) { /* leave empty — callers degrade */ }
    return $cols;
}
// Reply snapshot → compact JSON (or '' when there is nothing usable).
// Bounded so a pasted novel can't bloat every row that quotes it.
function bc_reply_meta_json($raw): string {
    if (is_string($raw)) {
        $raw = trim($raw);
        if ($raw === '') return '';
        $dec = json_decode($raw, true);
        if (!is_array($dec)) return '';
        $raw = $dec;
    }
    if (!is_array($raw)) return '';
    $out = [];
    foreach (['r','c','mt','who','pid','uid'] as $k) {
        if (!isset($raw[$k])) continue;
        $v = is_scalar($raw[$k]) ? (string)$raw[$k] : '';
        $out[$k] = mb_substr($v, 0, $k === 'c' ? 280 : 120);
    }
    if (!$out) return '';
    return (string)json_encode($out, JSON_UNESCAPED_UNICODE);
}
// Neutralise control-plane sentinels in customer-authored text. Shared by
// save_message and update_message so an EDIT can't smuggle in what a new
// message may not.
function bc_scrub_inbound(string $text): string {
    return (string)preg_replace('/\[\[\s*(?:ACTION|INVOICE|LICENSE_RESULT|LICENSE)\s*:[^\]]*\]\]/i', '[user-typed-tag]', $text);
}
// Keep bc_conversations.last_msg in step when the newest row changes.
function bc_refresh_conv_preview(PDO $pdo, int $accountId, string $convId): void {
    try {
        $cols = bc_msg_cols($pdo);
        $delFilter = isset($cols['deleted_at']) ? ' AND deleted_at IS NULL' : '';
        $q = $pdo->prepare("SELECT role, content, media_type, ts FROM bc_messages WHERE conv_id=? AND account_id=?$delFilter ORDER BY id DESC LIMIT 1");
        $q->execute([$convId, $accountId]);
        $r = $q->fetch();
        $preview = '';
        $t = '';
        if ($r) {
            $preview = (string)$r['content'] !== '' ? (string)$r['content'] : ('[' . ((string)$r['media_type'] ?: 'media') . ']');
            $t = (string)$r['ts'];
        }
        $pdo->prepare("UPDATE bc_conversations SET last_msg=?" . ($t !== '' ? ", last_t=?" : "") . " WHERE id=? AND account_id=?")
            ->execute($t !== '' ? [$preview, $t, $convId, $accountId] : [$preview, $convId, $accountId]);
    } catch (Throwable $e) { /* preview is cosmetic */ }
}

// Large answers (a long thread's history, the inbox) are gzipped when the
// client accepts it: chat history is mostly text and shrinks 70-85%, which
// is most of the wait when a chat opens for the first time. Skipped when
// the server already compresses, when output has started, or for small
// payloads where it isn't worth the CPU.
function bc_send_json(string $json): void {
    if (strlen($json) >= 12288 && !headers_sent() && function_exists('gzencode')
        && !ini_get('zlib.output_compression')
        && stripos((string)($_SERVER['HTTP_ACCEPT_ENCODING'] ?? ''), 'gzip') !== false) {
        $level = 0;
        while (ob_get_level() > $level && ob_get_length() === 0) { @ob_end_clean(); }
        if (ob_get_level() === 0 || ob_get_length() === 0) {
            $gz = gzencode($json, 5);
            if ($gz !== false) {
                header('Content-Encoding: gzip');
                header('Vary: Accept-Encoding');
                header('Content-Length: ' . strlen($gz));
                echo $gz;
                return;
            }
        }
    }
    echo $json;
}
// Constants the router needs. A top-level const only exists once execution
// reaches it, and these used to sit below the router, so the code paths that
// read them (post-sale setup, scheduling) failed with "Undefined constant".
const SCHED_CUSTOMER_VERBS = ['customer_followup'];
const SCHED_NEVER = [
    'clarify', 'noop', 'confirm', 'dashboard_reset', 'web_search',
    'message_search', 'contact_search', 'customer_profile',
    'schedule_create', 'schedule_cancel', 'schedule_list', 'schedule_update',
    'schedule_view',
];
const BC_ONB_TTL_S = 86400;

// While bc_internal() is running an action on the server's own behalf,
// ok()/err() hand the result back to it instead of answering the request.
class BcActionReturn extends Exception {
    public $payload;
    public function __construct(array $payload) { parent::__construct('bc-action-return'); $this->payload = $payload; }
}
function bc_internal(callable $fn): array {
    $GLOBALS['BC_INTERNAL'] = (int)($GLOBALS['BC_INTERNAL'] ?? 0) + 1;
    try { $fn(); return ['error' => 'No response']; }
    catch (BcActionReturn $r) { return $r->payload; }
    finally { $GLOBALS['BC_INTERNAL']--; }
}
function ok($data = [])  { if (!empty($GLOBALS['BC_INTERNAL'])) throw new BcActionReturn(['ok' => true] + (array)$data); $j = json_encode(['ok' => true] + $data); if ($j === false) { echo $j; exit; } bc_send_json($j); exit; }
// $extra lets a caller attach machine-readable context to a refusal (e.g.
// ['post_sale_stop' => true]) so the client can tell "the agent is meant to
// be quiet here" apart from "something broke", and show the right state
// instead of a red error dot. Callers that pass nothing behave exactly as
// before.
function err($msg, array $extra = []) { if (!empty($GLOBALS['BC_INTERNAL'])) throw new BcActionReturn(array_merge(['error' => $msg], $extra)); http_response_code(400); echo json_encode(array_merge(['error' => $msg], $extra)); exit; }

/* =====================================================================
   PATCH 1 — HANDLE / USERNAME NORMALISATION HELPERS
   ---------------------------------------------------------------------
   WHERE:  api.php, paste this block anywhere in the top-level helper
           region — a good spot is immediately AFTER the
           `function err($msg)` definition (~line 2383).

   WHY:    Handles arrive from three different sources in three different
           shapes and nothing ever reconciled them:

             Telegram bridge  ->  "@alice"   (leading @ ALWAYS added)
             Telegram, no username -> "8412339901"  (the numeric chat id
                                      is used as the handle — this is the
                                      "that's not their username" bug)
             Discord bridge   ->  "riley_c" or "riley_c#4821"  (no @)
             Operator typed   ->  "alice", "@alice", " Alice "

           Downstream the UI does `'@' + handle`, which turns "@alice"
           into "@@alice", and verify_license does an exact
           `eu.handle = ?` compare, which means "alice" never matches
           "@alice" and a numeric id matches nothing a human would type.

   These helpers give one canonical form for storage/display and one
   lowercase key for comparison. Nothing else in the file needs to know
   which platform a handle came from.
   ===================================================================== */

/**
 * Canonical display/storage form of a handle or licence username.
 *
 * - trims whitespace (including the zero-width junk that gets pasted out
 *   of Telegram and Discord clients)
 * - strips EVERY leading '@' (so "@@alice" and "@alice" both -> "alice")
 * - collapses internal whitespace
 * - preserves case, because "RileyC" should still read as "RileyC"
 *
 * Never returns a leading '@'. Prefix it at render time, once.
 */
function bc_handle_norm($raw): string {
    $s = (string)($raw ?? '');
    // Zero-width space, ZWNJ, ZWJ, BOM, and the non-breaking space that
    // Telegram desktop likes to smuggle into copied handles.
    $s = preg_replace('/[\x{200B}-\x{200D}\x{FEFF}\x{00A0}]/u', '', $s);
    $s = trim($s);
    $s = preg_replace('/^@+/', '', $s);          // "@@alice" -> "alice"
    $s = preg_replace('/\s+/u', ' ', $s);
    return trim($s);
}

/**
 * Lowercase comparison key. Use this on BOTH sides of any handle or
 * username equality test. Telegram and Discord both treat handles as
 * case-insensitive, so "Alice" and "alice" are the same person.
 */
function bc_handle_key($raw): string {
    return mb_strtolower(bc_handle_norm($raw), 'UTF-8');
}

/**
 * Is this actually a human-facing handle, or is it a platform id that
 * got parked in the handle column because the user had no username?
 *
 * The Telegram bridge falls back to `fromId.ToString()` when
 * `msg.From.Username` is empty, so a large share of handles in the wild
 * are really numeric chat ids. Rendering those as "@8412339901" is what
 * made the licence popup show usernames that were not the customer's
 * username at all.
 *
 * Returns false for: empty, all-digits (any length), and the obvious
 * placeholder strings.
 */
function bc_handle_is_real($raw): bool {
    $s = bc_handle_norm($raw);
    if ($s === '') return false;
    if (preg_match('/^\d+$/', $s)) return false;            // numeric chat id
    // Handles never contain whitespace on Telegram or Discord. A value
    // with a space in it is a display name that landed in the handle
    // column, not a username — showing "@Tom Eriksen" is the same lie
    // as showing "@8412339901".
    if (preg_match('/\s/u', $s)) return false;
    if (preg_match('/^(unknown|null|none|n\/a|user|deleted account)$/i', $s)) return false;
    return true;
}

/**
 * Discord legacy handles carry a discriminator: "riley_c#4821". Since
 * Discord's 2023 migration to unique usernames the discriminator is
 * "0" for every migrated account and should not be shown or stored.
 *
 * Returns the bare username for matching purposes. Keep the full form
 * for display when the discriminator is genuinely meaningful (an old
 * un-migrated account), but ALWAYS also try the bare form when looking
 * a licence up, because that is what the customer will type.
 */
function bc_handle_base($raw): string {
    $s = bc_handle_norm($raw);
    $hash = strpos($s, '#');
    if ($hash === false) return $s;
    $disc = substr($s, $hash + 1);
    // "#0" / "#0000" are the migrated-account sentinels — drop them.
    if ($disc === '' || $disc === '0' || $disc === '0000') return substr($s, 0, $hash);
    return $s;
}

/**
 * Every form of a handle worth trying in a lookup, de-duplicated and
 * lowercased. Feed this into an `IN (...)` clause.
 *
 *   bc_handle_variants('@Riley_C#0')  ->  ['riley_c#0', 'riley_c']
 *   bc_handle_variants('alice')       ->  ['alice']
 */
function bc_handle_variants($raw): array {
    $out = [];
    $norm = bc_handle_key($raw);
    if ($norm !== '') $out[] = $norm;
    $base = mb_strtolower(bc_handle_base($raw), 'UTF-8');
    if ($base !== '' && $base !== $norm) $out[] = $base;
    return array_values(array_unique($out));
}

/**
 * Render a handle the way the UI should show it: "@alice", or the plain
 * display name when the stored value is really a platform id.
 *
 * $fallback is what to show instead of a fake "@12345678" — normally the
 * customer's display name. Returns '' when there is nothing honest to
 * show, so callers can hide the row entirely.
 */
function bc_handle_display($raw, string $fallback = ''): string {
    // bc_handle_base drops the "#0" / "#0000" Discord leaves on migrated
    // accounts — a sentinel, not part of the name.
    if (bc_handle_is_real($raw)) return '@' . bc_handle_base($raw);
    return trim($fallback);
}

/* =====================================================================
   SELF-LOCATION HELPERS
   ---------------------------------------------------------------------
   Both the licence check page (patch 2) and the ghost (patch 3) need to
   tell people the real URL of THIS deployment. Nothing may be hardcoded:
   the app gets dropped in /myresponder/, /clients/acme/panel/, at a
   domain root, behind Cloudflare, behind a reverse proxy on a non-
   standard port — and the answer has to stay correct in all of them.

   Everything below is derived from the live request, so it is right
   wherever the files happen to be sitting.
   ===================================================================== */

/** Scheme + host (+ port when non-standard). No trailing slash. */
function bc_self_origin(): string {
    $proto = strtolower(trim((string)($_SERVER['HTTP_X_FORWARDED_PROTO'] ?? '')));
    if ($proto !== '') $proto = explode(',', $proto)[0];   // proxies chain these
    $https = $proto === 'https'
          || (!empty($_SERVER['HTTPS']) && strtolower((string)$_SERVER['HTTPS']) !== 'off')
          || (int)($_SERVER['SERVER_PORT'] ?? 0) === 443
          || strtolower((string)($_SERVER['HTTP_X_FORWARDED_SSL'] ?? '')) === 'on';
    $scheme = $https ? 'https' : 'http';

    $host = (string)($_SERVER['HTTP_X_FORWARDED_HOST'] ?? $_SERVER['HTTP_HOST'] ?? $_SERVER['SERVER_NAME'] ?? 'localhost');
    $host = explode(',', $host)[0];
    $host = trim($host);
    // Host header is attacker-controlled; allow only what a host can contain.
    if (!preg_match('/^[A-Za-z0-9\.\-\[\]:]{1,255}$/', $host)) $host = 'localhost';

    return $scheme . '://' . $host;
}

/** Absolute URL of api.php itself, wherever it is installed. */
function bc_self_api_url(): string {
    $script = (string)($_SERVER['SCRIPT_NAME'] ?? '/api.php');
    if ($script === '' || $script[0] !== '/') $script = '/' . $script;
    return bc_self_origin() . $script;
}

/** Absolute URL of the directory the app lives in, WITH trailing slash. */
function bc_self_app_dir(): string {
    $script = (string)($_SERVER['SCRIPT_NAME'] ?? '/api.php');
    $dir = rtrim(str_replace('\\', '/', dirname($script)), '/');
    return bc_self_origin() . $dir . '/';
}

/** Ready-made URLs the operator or the ghost may need to hand out. */
function bc_self_urls(): array {
    $api = bc_self_api_url();
    return [
        'origin'          => bc_self_origin(),
        'app_dir'         => bc_self_app_dir(),
        'api'             => $api,
        'verify_endpoint' => $api . '?action=verify_license',
        'verify_page'     => $api . '?action=verify_license&format=html',
    ];
}


// Public actions — no session required. Everything else is gated below the
// switch; an unauthenticated request to a private action returns 401 and the
// frontend kicks the user to the login screen.
$PUBLIC_ACTIONS = ['auth_register', 'auth_login', 'auth_whoami', 'auth_logout', 'auth_prelogin', 'auth_guest', 'auth_guest_challenge', 'auth_guest_resume', 'auth_name_check', 'verify_license', 'contact_page', 'dm_ai_cron', 'dm_ai_worker', 'dm_file', 'avatar', 'admin_op'];
$BC_ME = null;
if (!in_array($action, $PUBLIC_ACTIONS, true)) {
    $BC_ME = require_account($pdo);
    // A guest reaches its own conversation and nothing else (403, not 401,
    // so the app doesn't treat it as signed out).
    if (!empty($BC_ME['is_guest']) && !in_array($action, bc_guest_actions(), true)) {
        http_response_code(403);
        echo json_encode(['error' => 'Create an account to use this.', 'code' => 'guest_restricted']);
        exit;
    }
}
$ACCOUNT_ID = current_account_id();  // set after gate; null only for public actions
// Release the session lock as soon as we know who is asking. PHP holds an
// exclusive lock on the session file for the whole request, so every other
// request from the same browser (the app fires a dozen at start-up, and
// polls while an AI reply can take a minute) used to queue behind it. Only
// the auth actions and the lookup rate-limiter write to the session.
if (strpos((string)$action, 'auth_') !== 0 && $action !== 'dm_lookup') {
    session_write_close();
}

switch ($action) {

    // ── AUTH ─────────────────────────────────────────────────
    case 'auth_register':
        $email    = trim((string)($body['email']    ?? ''));
        $username = trim((string)($body['username'] ?? ''));
        $password = (string)($body['password'] ?? '');
        $regAuth  = (string)($body['auth'] ?? '');
        $regSalt  = (string)($body['kdf_salt'] ?? '');
        $display  = trim((string)($body['display_name'] ?? $username));
        if (!is_email($email))     err('Valid email required');
        if (strlen($username) < 3) err('Username must be at least 3 characters');
        if (!preg_match('/^[a-zA-Z0-9_.\-]+$/', $username)) err('Username can only contain letters, numbers, _ . -');
        if (bc_guest_username_reserved($username)) err('That username is reserved. Choose another.');
        // Current clients send a derived login key (the password itself never
        // arrives, so its length is checked in the browser). A plain password
        // is still accepted from an older client and upgraded at next sign-in.
        $isV2 = $regAuth !== '';
        if ($isV2) {
            if (!bc_auth_key_ok($regAuth) || !preg_match('/^[A-Za-z0-9_-]{16,64}$/', $regSalt)) err('Invalid sign-up data. Reload the page and try again.');
        } elseif (strlen($password) < 8) err('Password must be at least 8 characters');
        // Paced like guest chats (see GUEST ABUSE LIMITS): a solved puzzle,
        // then per-browser and per-address caps.
        $regIp = null;
        if (bc_guest_ready($pdo)) {
            $pow = is_array($body['pow'] ?? null) ? $body['pow'] : [];
            $bad = bc_guest_pow_check($pdo, (string)($pow['c'] ?? ''), (string)($pow['n'] ?? ''));
            if ($bad) err($bad, ['code' => 'pow']);
            $slowReg = function () { http_response_code(429); echo json_encode(['error' => 'Too many accounts have been created from here. Please try again later.']); exit; };
            if (!dm_rate('signup', 5, 3600)) $slowReg();
            $regIp = bc_guest_ip_key();
            $rc = $pdo->prepare("SELECT SUM(created_at > NOW() - INTERVAL 1 HOUR), COUNT(*) FROM bc_accounts WHERE guest_ip=? AND is_guest=0 AND created_at > NOW() - INTERVAL 1 DAY");
            $rc->execute([$regIp]);
            [$rh, $rd] = array_map('intval', $rc->fetch(PDO::FETCH_NUM) ?: [0, 0]);
            if ($rh >= BC_SIGNUP_PER_IP_HOUR || $rd >= BC_SIGNUP_PER_IP_DAY) $slowReg();
        }
        // Uniqueness — race-free via INSERT and trapping the duplicate error.
        try {
            $stmt = $pdo->prepare("INSERT INTO bc_accounts (email, username, pass_hash, display_name, kdf_salt, pw_v) VALUES (?,?,?,?,?,?)");
            $stmt->execute([
                strtolower($email), $username,
                password_hash($isV2 ? $regAuth : $password, PASSWORD_BCRYPT),
                $display,
                $isV2 ? $regSalt : null,
                $isV2 ? 2 : 1,
            ]);
        } catch (PDOException $e) {
            if ($e->getCode() === '23000') err('Email or username already in use');
            throw $e;
        }
        $newId = (int)$pdo->lastInsertId();
        // Where it was made from (hashed), for the per-address caps above.
        if ($regIp !== null) { try { $pdo->prepare("UPDATE bc_accounts SET guest_ip=? WHERE id=?")->execute([$regIp, $newId]); } catch (Throwable $e) {} }
        // Issue session immediately — same as a successful login.
        session_regenerate_id(true);
        $_SESSION['account_id'] = $newId;
        $pdo->prepare("UPDATE bc_accounts SET last_login=NOW() WHERE id=?")->execute([$newId]);
        // Adopt any orphan rows left by a pre-auth install (one-shot, safe-no-op
        // when there's nothing to claim or when more than one account exists).
        claim_legacy_orphans($pdo, $newId);
        ok(['account' => [
            'id'=>$newId, 'email'=>strtolower($email), 'username'=>$username, 'display_name'=>$display, 'guest'=>false, 'guest_of'=>0,
        ]]);

    case 'auth_prelogin': {
        // Step 1 of signing in: which salt to stretch the password with.
        $login = trim((string)($body['login'] ?? ''));
        if ($login === '') err('Email or username required');
        $gq = bc_guest_ready($pdo) ? ", is_guest" : ", 0 AS is_guest";
        $stmt = $pdo->prepare("SELECT id, kdf_salt, pw_v{$gq} FROM bc_accounts WHERE email=? OR username=? LIMIT 1");
        $stmt->execute([strtolower($login), $login]);
        $row = $stmt->fetch();
        if (!$row || !empty($row['is_guest'])) ok(['salt' => bc_fake_salt($login), 'it' => BC_KDF_ITER, 'v' => 2]);
        $salt = (string)($row['kdf_salt'] ?? '');
        if ($salt === '') {
            // Legacy account: give it a salt now, for the upgrade at sign-in.
            $salt = bc_new_salt();
            $pdo->prepare("UPDATE bc_accounts SET kdf_salt=? WHERE id=? AND (kdf_salt IS NULL OR kdf_salt='')")->execute([$salt, (int)$row['id']]);
            $re = $pdo->prepare("SELECT kdf_salt FROM bc_accounts WHERE id=?");
            $re->execute([(int)$row['id']]);
            $salt = (string)$re->fetchColumn();
        }
        ok(['salt' => $salt, 'it' => BC_KDF_ITER, 'v' => (int)$row['pw_v'] >= 2 ? 2 : 1]);
    }

    case 'auth_check': {
        // Re-confirm the signed-in person's password (a session that started
        // before messages were tied to the password needs it once).
        $me = require_account($pdo);
        if (!dm_rate('pwcheck', 10, 300)) err('Too many attempts — wait a few minutes and try again.');
        $q = $pdo->prepare("SELECT id, pass_hash, kdf_salt, pw_v FROM bc_accounts WHERE id=?");
        $q->execute([(int)$me['id']]);
        $row = $q->fetch();
        if (!$row || !bc_check_login($pdo, $row, $body)) { http_response_code(401); echo json_encode(['error' => 'That password isn’t right.']); exit; }
        ok();
    }

    case 'auth_login':
        $login    = trim((string)($body['login']    ?? '')); // email OR username
        $password = (string)($body['password'] ?? '');
        $authKey  = (string)($body['auth'] ?? '');
        if ($login === '' || ($password === '' && $authKey === '')) err('Email/username and password required');
        if (!dm_rate('login', 20, 300)) { http_response_code(429); echo json_encode(['error' => 'Too many sign-in attempts. Wait a few minutes and try again.']); exit; }
        $gq = bc_guest_ready($pdo) ? ", is_guest, guest_of" : ", 0 AS is_guest, NULL AS guest_of";
        $stmt = $pdo->prepare("SELECT id, email, username, pass_hash, display_name, kdf_salt, pw_v{$gq} FROM bc_accounts WHERE email=? OR username=? LIMIT 1");
        $stmt->execute([strtolower($login), $login]);
        $row = $stmt->fetch();
        if (!$row || !empty($row['is_guest']) || !bc_check_login($pdo, $row, $body)) {
            // Generic message — never tell the attacker which half was wrong.
            http_response_code(401);
            echo json_encode(['error' => 'Invalid email/username or password']);
            exit;
        }
        if ($sus = bc_account_suspension($pdo, (int)$row['id'])) {
            http_response_code(403);
            $why = trim((string)($sus['suspend_reason'] ?? ''));
            echo json_encode(['error' => 'This account has been suspended.' . ($why !== '' ? ' Reason: ' . $why : ''), 'code' => 'suspended']);
            exit;
        }
        session_regenerate_id(true);
        $_SESSION['account_id'] = (int)$row['id'];
        $pdo->prepare("UPDATE bc_accounts SET last_login=NOW() WHERE id=?")->execute([(int)$row['id']]);
        // Adopt any orphan rows left by a pre-auth install (one-shot, safe-no-op
        // when there's nothing to claim or when more than one account exists).
        claim_legacy_orphans($pdo, (int)$row['id']);
        ok(['account' => bc_account_out($row)]);

    case 'auth_logout':
        $_SESSION = [];
        if (ini_get('session.use_cookies')) {
            $p = session_get_cookie_params();
            setcookie(session_name(), '', time()-42000, $p['path'], $p['domain'], $p['secure'], $p['httponly']);
        }
        session_destroy();
        ok();

    case 'auth_whoami':
        $a = current_account($pdo);
        if (!$a) ok(['account' => null]);
        ok(['account' => bc_account_out($a)]);

    // ── GUEST CHAT ───────────────────────────────────────────────
    // Start a guest session from someone's contact link. body: to (their
    // username), name (optional, what they'll see you as). Returns the
    // account and a resume token the browser keeps, so a lost session can
    // be picked up again on the same device (auth_guest_resume).
    case 'auth_guest': {
        if (!bc_guest_ready($pdo)) err('Guest chat isn’t available right now. Please try again in a moment.');
        $to   = ltrim(trim((string)($body['to'] ?? '')), '@');
        $name = preg_replace('/[\x00-\x1F\x7F]+/u', '', (string)($body['name'] ?? ''));
        $name = trim(preg_replace('/\s+/u', ' ', (string)$name));
        if (mb_strlen($name) > 60) err('Keep your name to 60 characters or fewer.');
        if ($name !== '' && bc_guest_username_reserved($name)) err('That name is reserved. Try another.', ['code' => 'name_taken']);
        if ($name !== '' && bc_name_taken($pdo, $name)) err('That name is already taken. Try another, or leave it blank.', ['code' => 'name_taken']);
        $host = dm_user_public($pdo, $to);
        $hostGuest = false;
        if ($host) {
            $hg = $pdo->prepare("SELECT is_guest FROM bc_accounts WHERE id=?");
            $hg->execute([(int)$host['id']]);
            $hostGuest = (int)$hg->fetchColumn() === 1;
        }
        if (!$host || $hostGuest || (int)$host['discoverable'] !== 1) err('This contact link isn’t active.');
        if (empty($host['key_id'])) err('@' . $host['username'] . ' can’t receive messages yet. Please try again later.');
        if (!bc_guest_host_prefs($pdo, (int)$host['id'])['allow']) err('@' . $host['username'] . ' isn’t accepting guest chats. Create an account to message them.', ['code' => 'guest_off']);
        // Already signed in — as a person or an earlier guest: nothing to make.
        $cur = current_account($pdo);
        if ($cur) ok(['account' => bc_account_out($cur)]);

        // The solved puzzle first, so junk requests never touch the counts.
        $pow = is_array($body['pow'] ?? null) ? $body['pow'] : [];
        $bad = bc_guest_pow_check($pdo, (string)($pow['c'] ?? ''), (string)($pow['n'] ?? ''));
        if ($bad) err($bad, ['code' => 'pow']);

        $slow = function () { http_response_code(429); echo json_encode(['error' => 'Too many guest chats have been started from here. Please try again later.']); exit; };
        if (!dm_rate('guest', 6, 3600)) $slow();
        $ipk = bc_guest_ip_key();
        $n = $pdo->prepare("SELECT SUM(created_at > NOW() - INTERVAL 1 HOUR), COUNT(*) FROM bc_accounts WHERE guest_ip=? AND created_at > NOW() - INTERVAL 1 DAY");
        $n->execute([$ipk]);
        [$ipHour, $ipDay] = array_map('intval', $n->fetch(PDO::FETCH_NUM) ?: [0, 0]);
        if ($ipHour >= BC_GUEST_PER_IP_HOUR || $ipDay >= BC_GUEST_PER_IP_DAY) $slow();
        $hq = $pdo->prepare("SELECT COUNT(*) FROM bc_accounts WHERE guest_of=? AND created_at > NOW() - INTERVAL 1 HOUR");
        $hq->execute([(int)$host['id']]);
        if ((int)$hq->fetchColumn() >= BC_GUEST_PER_HOST_HOUR) {
            http_response_code(429);
            echo json_encode(['error' => '@' . $host['username'] . ' is receiving a lot of guest chats right now. Please try again later, or create an account.']);
            exit;
        }
        $all = (int)$pdo->query("SELECT COUNT(*) FROM bc_accounts WHERE is_guest=1 AND created_at > NOW() - INTERVAL 1 HOUR")->fetchColumn();
        if ($all >= BC_GUEST_SITE_HOUR) $slow();
        if (random_int(1, 12) === 1) bc_guest_sweep($pdo);

        $newId = 0; $uname = ''; $display = ''; $token = '';
        for ($try = 0; $try < 5 && !$newId; $try++) {
            $uname   = 'guest-' . bin2hex(random_bytes(5));
            $display = $name;
            // No name given: "Guest 4821", one nobody else has.
            for ($d = 0; $display === '' && $d < 8; $d++) {
                $cand = 'Guest ' . random_int(1000, 9999);
                if (!bc_name_taken($pdo, $cand)) $display = $cand;
            }
            if ($display === '') $display = 'Guest ' . strtoupper(bin2hex(random_bytes(3)));
            $token   = bc_new_salt() . bc_new_salt();
            try {
                $pdo->prepare("INSERT INTO bc_accounts (email, username, pass_hash, display_name, kdf_salt, pw_v, is_guest, guest_of, guest_token, guest_ip)
                               VALUES (?,?,?,?,?,2,1,?,?,?)")
                    ->execute([$uname . '@guest.invalid', $uname, password_hash(bin2hex(random_bytes(32)), PASSWORD_BCRYPT),
                               $display, bc_new_salt(), (int)$host['id'], hash('sha256', $token), $ipk]);
                $newId = (int)$pdo->lastInsertId();
            } catch (PDOException $e) {
                if ($e->getCode() !== '23000') throw $e;
            }
        }
        if (!$newId) err('Couldn’t start the chat. Please try again.');
        // Hidden: a guest can't be found, and has no public contact page.
        dm_profile($pdo, $newId);
        try { $pdo->prepare("UPDATE bc_dm_profile SET discoverable=0 WHERE account_id=?")->execute([$newId]); } catch (Throwable $e) {}
        try { $pdo->prepare("UPDATE bc_dm_profile SET show_seen=0, show_links=0 WHERE account_id=?")->execute([$newId]); } catch (Throwable $e) {}
        session_regenerate_id(true);
        $_SESSION['account_id'] = $newId;
        $pdo->prepare("UPDATE bc_accounts SET last_login=NOW() WHERE id=?")->execute([$newId]);
        ok(['account' => bc_account_out(['id' => $newId, 'email' => '', 'username' => $uname, 'display_name' => $display,
                                         'is_guest' => 1, 'guest_of' => (int)$host['id']]),
            'resume' => $token]);
    }

    // The puzzle a browser solves before auth_guest (see GUEST ABUSE
    // LIMITS). c: the signed challenge, s: the salt, bits: the difficulty —
    // find n where sha256(s . n) starts with that many zero bits.
    case 'auth_guest_challenge': {
        if (!bc_guest_ready($pdo)) err('Guest chat isn’t available right now. Please try again in a moment.');
        if (!dm_rate('guest_ch', 30, 600)) { http_response_code(429); echo json_encode(['error' => 'Too many attempts. Please wait a few minutes and try again.']); exit; }
        $bits = bc_guest_pow_bits($pdo);
        $s    = bin2hex(random_bytes(16));
        $core = $s . '.' . time() . '.' . $bits . '.' . substr(bc_guest_ip_key(), 0, 16);
        ok(['c' => $core . '.' . hash_hmac('sha256', $core, bc_guest_pow_secret()), 's' => $s, 'bits' => $bits]);
    }

    // Live checks for the guest forms. kind 'guest_name': is this name free
    // for a guest? kind 'username': is it free (with a free alternative if
    // not)? With 'from' instead of 'value', suggests a username for a name.
    case 'auth_name_check': {
        if (!dm_rate('namecheck', 90, 300)) { http_response_code(429); echo json_encode(['error' => 'Too many checks. Wait a moment.']); exit; }
        $kind = (string)($body['kind'] ?? '');
        $val  = bc_name_norm((string)($body['value'] ?? ''));
        $selfId = (int)(current_account_id() ?? 0);
        if ($kind === 'guest_name') {
            if ($val === '') ok(['available' => true]);
            if (mb_strlen($val) > 60) ok(['available' => false, 'reason' => 'Keep it to 60 characters or fewer.']);
            if (bc_guest_username_reserved($val) || bc_name_taken($pdo, $val, $selfId)) ok(['available' => false, 'reason' => 'That name is already taken.']);
            ok(['available' => true]);
        }
        if ($kind === 'username') {
            $from = (string)($body['from'] ?? '');
            if ($val === '' && $from !== '') ok(['suggestion' => bc_username_suggest($pdo, $from)]);
            $u = ltrim($val, '@');
            if (strlen($u) < 3) ok(['available' => false, 'reason' => 'At least 3 characters.']);
            if (strlen($u) > 60 || !preg_match('/^[a-zA-Z0-9_.\-]+$/', $u)) ok(['available' => false, 'reason' => 'Letters, numbers, _ . and - only.']);
            if (bc_guest_username_reserved($u)) ok(['available' => false, 'reason' => 'That username is reserved.', 'suggestion' => '']);
            $q = $pdo->prepare("SELECT 1 FROM bc_accounts WHERE username = ? LIMIT 1");
            $q->execute([$u]);
            if ($q->fetchColumn()) ok(['available' => false, 'reason' => 'That username is taken.', 'suggestion' => bc_username_suggest($pdo, $u)]);
            ok(['available' => true]);
        }
        err('Unknown check');
    }

    // A guest's session is gone (expired, server restarted) but this
    // browser still holds its resume token: sign it back in.
    case 'auth_guest_resume': {
        if (!bc_guest_ready($pdo)) ok(['account' => null]);
        $tok = (string)($body['token'] ?? '');
        if (!preg_match('/^[A-Za-z0-9_-]{32,96}$/', $tok)) ok(['account' => null, 'gone' => true]);
        if (!dm_rate('guest_resume', 20, 300)) { http_response_code(429); echo json_encode(['error' => 'Too many attempts. Wait a few minutes and try again.']); exit; }
        $q = $pdo->prepare("SELECT id, email, username, display_name, is_guest, guest_of FROM bc_accounts WHERE guest_token=? AND is_guest=1 LIMIT 1");
        $q->execute([hash('sha256', $tok)]);
        $row = $q->fetch();
        if (!$row) ok(['account' => null, 'gone' => true]);
        session_regenerate_id(true);
        $_SESSION['account_id'] = (int)$row['id'];
        $pdo->prepare("UPDATE bc_accounts SET last_login=NOW() WHERE id=?")->execute([(int)$row['id']]);
        ok(['account' => bc_account_out($row)]);
    }

    // Turn this guest account into a full one: email, username, password
    // (sent as the derived login key, exactly like auth_register). Same
    // account id, so the conversation and everything in it stays.
    case 'auth_claim': {
        $meA = require_account($pdo);
        if (empty($meA['is_guest'])) err('This account is already registered.');
        if (!dm_rate('claim', 12, 600)) { http_response_code(429); echo json_encode(['error' => 'Too many attempts. Wait a few minutes and try again.']); exit; }
        $email    = trim((string)($body['email'] ?? ''));
        $username = trim((string)($body['username'] ?? ''));
        $password = (string)($body['password'] ?? '');
        $regAuth  = (string)($body['auth'] ?? '');
        $regSalt  = (string)($body['kdf_salt'] ?? '');
        $display  = preg_replace('/[\x00-\x1F\x7F]+/u', '', (string)($body['display_name'] ?? ''));
        $display  = trim(preg_replace('/\s+/u', ' ', (string)$display));
        if ($display === '') $display = (string)($meA['display_name'] ?: $username);
        if (mb_strlen($display) > 60) err('Keep your name to 60 characters or fewer.');
        if (!is_email($email)) err('Enter a valid email address.');
        if (strlen($username) < 3) err('Username must be at least 3 characters.');
        if (strlen($username) > 60) err('Username must be 60 characters or fewer.');
        if (!preg_match('/^[a-zA-Z0-9_.\-]+$/', $username)) err('Username can only contain letters, numbers, _ . -');
        if (bc_guest_username_reserved($username)) err('That username is reserved. Choose another.');
        $isV2 = $regAuth !== '';
        if ($isV2) {
            if (!bc_auth_key_ok($regAuth) || !preg_match('/^[A-Za-z0-9_-]{16,64}$/', $regSalt)) err('Invalid sign-up data. Reload the page and try again.');
        } elseif (strlen($password) < 8) err('Password must be at least 8 characters.');
        try {
            $u = $pdo->prepare("UPDATE bc_accounts SET email=?, username=?, pass_hash=?, display_name=?, kdf_salt=?, pw_v=?,
                                       is_guest=0, guest_token=NULL, claimed_at=NOW(), last_login=NOW()
                                 WHERE id=? AND is_guest=1");
            $u->execute([strtolower($email), $username, password_hash($isV2 ? $regAuth : $password, PASSWORD_BCRYPT),
                         $display, $isV2 ? $regSalt : null, $isV2 ? 2 : 1, (int)$meA['id']]);
        } catch (PDOException $e) {
            if ($e->getCode() === '23000') err('That email or username is already in use.');
            throw $e;
        }
        if ($u->rowCount() !== 1) err('This account is already registered.');
        // A full account: findable and shareable like any other.
        try { $pdo->prepare("UPDATE bc_dm_profile SET discoverable=1 WHERE account_id=?")->execute([(int)$meA['id']]); } catch (Throwable $e) {}
        try { $pdo->prepare("UPDATE bc_dm_profile SET show_seen=1, show_links=1 WHERE account_id=?")->execute([(int)$meA['id']]); } catch (Throwable $e) {}
        // Their chats show the new name straight away (the list reloads when
        // a thread's updated_at moves).
        try { $pdo->prepare("UPDATE bc_dm_threads SET updated_at=NOW() WHERE a_id=? OR b_id=?")->execute([(int)$meA['id'], (int)$meA['id']]); } catch (Throwable $e) {}
        session_regenerate_id(true);
        $_SESSION['account_id'] = (int)$meA['id'];
        $fresh = current_account($pdo);
        ok(['account' => bc_account_out($fresh ?: $meA)]);
    }

    // Your profile photo (Profile window). The browser sends a small square
    // picture it has already cropped and resized; it is checked here, kept
    // in bc_dm_avatars and served by 'avatar'. remove=1 deletes it.
    case 'account_set_avatar': {
        $me = (int)$ACCOUNT_ID;
        dm_profile($pdo, $me);
        if (!empty($body['remove'])) {
            $pdo->prepare("DELETE FROM bc_dm_avatars WHERE account_id=?")->execute([$me]);
            $pdo->prepare("UPDATE bc_dm_profile SET avatar_v=NULL WHERE account_id=?")->execute([$me]);
            ok(['avatar' => null]);
        }
        $img = (string)($body['image'] ?? '');
        if (!preg_match('#^data:(image/(?:jpeg|png|webp));base64,([A-Za-z0-9+/=\r\n]+)$#', $img, $m)) err('Choose a JPG, PNG or WebP picture.');
        $bin = base64_decode($m[2], true);
        if ($bin === false || $bin === '') err('That picture couldn’t be read.');
        if (strlen($bin) > 600 * 1024) err('That picture is too large. Try a smaller one.');
        $info = @getimagesizefromstring($bin);
        if (!$info || empty($info[0]) || empty($info[1])) err('That file isn’t a picture.');
        $mime = (string)($info['mime'] ?? $m[1]);
        if (!in_array($mime, ['image/jpeg', 'image/png', 'image/webp'], true)) err('Choose a JPG, PNG or WebP picture.');
        if ($info[0] > 2048 || $info[1] > 2048) err('That picture is too large. Try a smaller one.');
        $v = bin2hex(random_bytes(8));
        $pdo->prepare("INSERT INTO bc_dm_avatars (account_id, v, mime, data) VALUES (?,?,?,?)
                       ON DUPLICATE KEY UPDATE v=VALUES(v), mime=VALUES(mime), data=VALUES(data)")->execute([$me, $v, $mime, $bin]);
        $pdo->prepare("UPDATE bc_dm_profile SET avatar_v=? WHERE account_id=?")->execute([$v, $me]);
        ok(['avatar' => dm_avatar_url($me, $v)]);
    }

    // A profile photo. Public (a picture beside a name, like the contact
    // page shows), but only for the current version: the URL carries it,
    // so ids can't be walked and a replaced photo stops loading.
    case 'avatar': {
        $id = (int)($_GET['id'] ?? 0);
        $v  = (string)($_GET['v'] ?? '');
        $none = function () { http_response_code(404); header('Content-Type: text/plain; charset=utf-8'); header('Cache-Control: no-store'); echo 'Not found'; exit; };
        if ($id <= 0 || !preg_match('/^[a-f0-9]{8,24}$/', $v)) $none();
        $q = $pdo->prepare("SELECT v, mime, data FROM bc_dm_avatars WHERE account_id=?");
        $q->execute([$id]);
        $r = $q->fetch();
        if (!$r || !hash_equals((string)$r['v'], $v)) $none();
        $mime = in_array($r['mime'], ['image/jpeg', 'image/png', 'image/webp'], true) ? $r['mime'] : 'application/octet-stream';
        header('Content-Type: ' . $mime);
        header('Content-Length: ' . strlen((string)$r['data']));
        header('X-Content-Type-Options: nosniff');
        header("Content-Security-Policy: default-src 'none'; sandbox");
        header('Cache-Control: public, max-age=31536000, immutable');
        echo $r['data'];
        exit;
    }

    // The name people see in their chats with you (Profile window). The
    // username stays fixed: it is your link and what people search for.
    case 'account_set_name': {
        $me   = (int)$ACCOUNT_ID;
        $name = (string)($body['display_name'] ?? '');
        $name = preg_replace('/[\x00-\x1F\x7F]+/u', '', $name);
        $name = trim(preg_replace('/\s+/u', ' ', (string)$name));
        if ($name === '') err('Enter a name');
        if (mb_strlen($name) > 60) err('Keep your name to 60 characters or fewer');
        if (!empty($BC_ME['is_guest']) && bc_name_taken($pdo, $name, $me)) err('That name is already taken. Try another.');
        $pdo->prepare("UPDATE bc_accounts SET display_name=? WHERE id=?")->execute([$name, $me]);
        ok(['display_name' => $name]);
    }

    // ── CONVERSATIONS ─────────────────────────────────────────
    case 'get_conversations':
        // LEFT JOIN bc_end_users so blocked/muted/escalation flags are included
        // without requiring a second round-trip. Rows without an end_user entry
        // get is_blocked=0 / is_muted=0 / escalated=0 via COALESCE on the JSON
        // status field. We surface a derived `escalated` boolean so the inbox
        // filter can read it directly without parsing JSON client-side.
        //
        // Optional ?search=<q> parameter: filters by name/handle/chat_id so
        // ghostResolveConvAsync can look up contacts not in MSGS_STORE.list.
        $convSearch = trim((string)($_GET['search'] ?? $body['search'] ?? ''));
        $convLimit  = max(1, min(500, (int)($_GET['limit'] ?? $body['limit'] ?? 500)));
        // Direct chats have their own list (DM_STORE); their conversation
        // rows only exist so the agent can sell there.
        $convWhere  = "c.account_id = ? AND c.platform <> 'direct'";
        $convParams = [$ACCOUNT_ID];
        if ($convSearch !== '') {
            $convWhere  .= ' AND (c.name LIKE ? OR c.handle LIKE ? OR c.chat_id LIKE ?)';
            $like = '%' . $convSearch . '%';
            $convParams = array_merge($convParams, [$like, $like, $like]);
        }
        // unassigned_at is migration-added; never let its absence take the
        // whole inbox down.
        $unassignedTsSel = col_exists($pdo, 'bc_conversations', 'unassigned_at')
            ? 'UNIX_TIMESTAMP(c.unassigned_at) AS unassigned_ts,' : '';
        $rows = $pdo->prepare("
            SELECT c.*,
                   UNIX_TIMESTAMP(c.updated_at) AS updated_ts,
                   {$unassignedTsSel}
                   COALESCE(eu.is_blocked, 0) AS is_blocked,
                   COALESCE(eu.is_muted,   0) AS is_muted,
                   eu.escalation              AS escalation_raw,
                   CASE
                     WHEN eu.escalation IS NOT NULL
                          AND eu.escalation LIKE '%\"status\":\"pending\"%'
                       THEN 1 ELSE 0
                   END AS escalated
            FROM bc_conversations c
            LEFT JOIN bc_end_users eu
                   ON eu.conv_id = c.id AND eu.account_id = c.account_id
            WHERE {$convWhere}
            ORDER BY c.updated_at DESC
            LIMIT {$convLimit}
        ");
        $rows->execute($convParams);
        $convsRows = $rows->fetchAll();
        foreach ($convsRows as &$cr) {
            $raw = $cr['escalation_raw'] ?? null;
            unset($cr['escalation_raw']);
            $cr['escalation'] = ($raw && is_string($raw))
                ? (json_decode($raw, true) ?: null)
                : null;
            $cr['escalated'] = !empty($cr['escalated']);
        }
        unset($cr);
        ok(['conversations' => $convsRows]);

    case 'save_conversation':
        $d = $body;
        if (empty($d['id'])) err('id required');
        // Identity is (account_id, id) — every probe & write is scoped to the
        // current account. A different operator's row with the same id sits
        // in its own slot; we never see it and never touch it.
        // operator_override is a migration-added column. If the ALTER never
        // ran (no privilege on a locked-down host) selecting it would throw
        // and take save_conversation — and therefore every inbound — down
        // with it, so fall back to the columns that have always existed.
        try {
            $existing = $pdo->prepare("SELECT agent_id, auto_reply, operator_override FROM bc_conversations WHERE id=? AND account_id=?");
            $existing->execute([$d['id'], $ACCOUNT_ID]);
            $existRow = $existing->fetch();
        } catch (\Throwable $e) {
            $existing = $pdo->prepare("SELECT agent_id, auto_reply FROM bc_conversations WHERE id=? AND account_id=?");
            $existing->execute([$d['id'], $ACCOUNT_ID]);
            $existRow = $existing->fetch();
        }

        $agentId    = $existRow['agent_id'] ?? null;
        $autoReply  = $existRow ? (int)$existRow['auto_reply'] : 0;
        if (!$existRow) {
            // First time we see this conversation — pick the default active agent
            // (lowest-id active row) and inherit its auto_reply_default. Scoped
            // to THIS account so we never inherit someone else's defaults.
            $a = $pdo->prepare("SELECT id, auto_reply_default FROM bc_agents WHERE active=1 AND account_id=? ORDER BY id ASC LIMIT 1");
            $a->execute([$ACCOUNT_ID]);
            $a = $a->fetch();
            if ($a) {
                $agentId   = (int)$a['id'];
                $autoReply = (int)$a['auto_reply_default'];
            } else {
                // No active agent yet — but the client (JS) optimistically wants
                // auto_reply ON so the FIRST message after agent creation triggers
                // a reply. Honour the client hint when present. Without this, a
                // conversation persisted before any agent existed gets stuck at
                // auto_reply=0 forever (the previous bug — UPDATE branch below
                // never overwrote it, so even after the JS backfill set the agent,
                // ai_reply rejected with "auto_reply disabled").
                if (isset($d['auto_reply'])) {
                    $autoReply = (int)(!empty($d['auto_reply']) ? 1 : 0);
                }
            }
        } else if (isset($d['auto_reply'])) {
            // Existing row — let the client raise auto_reply when it's
            // optimistically backfilling after an agent appears. We only allow
            // the client to TURN IT ON (1); turning it off must go through the
            // dedicated set_auto_reply endpoint so a stale save_conversation
            // can't accidentally silence a live agent.
            //
            // One exception: a conversation nobody is assigned to, where a
            // human (or a post-sale stop / escalation they are meant to see)
            // took the agent off. Restarting the app drops the in-memory
            // `_operatorOverride` flag, and the next inbound's backfill then
            // arrives here asking for auto_reply=1 on a conversation that was
            // deliberately left uncovered. Refuse it — the operator assigns
            // an agent when they want it talking again.
            $lockedOff = !empty($existRow['operator_override']) && empty($existRow['agent_id']);
            if (!empty($d['auto_reply']) && !$autoReply && !$lockedOff) {
                $autoReply = 1;
            }
        }
        $stmt = $pdo->prepare("
            INSERT INTO bc_conversations (id,chat_id,platform,name,handle,avatar,chat_type,col,stage,last_msg,last_t,ai_status,agent,agent_id,auto_reply,unread,account_id)
            VALUES (:id,:chat_id,:platform,:name,:handle,:avatar,:chat_type,:col,:stage,:last_msg,:last_t,:ai_status,:agent,:agent_id,:auto_reply,:unread,:account_id)
            ON DUPLICATE KEY UPDATE
                name=VALUES(name), handle=VALUES(handle), avatar=VALUES(avatar), chat_type=VALUES(chat_type),
                col=VALUES(col), stage=VALUES(stage), last_msg=VALUES(last_msg), last_t=VALUES(last_t),
                ai_status=VALUES(ai_status), agent=VALUES(agent), unread=VALUES(unread),
                auto_reply=VALUES(auto_reply)
        ");
        $stmt->execute([
            ':id'         => $d['id'],
            ':chat_id'    => $d['chatId']   ?? $d['chat_id'] ?? '',
            ':platform'   => $d['p']         ?? $d['platform'] ?? '',
            ':name'       => $d['name']      ?? '',
            ':handle'     => $d['handle']    ?? '',
            ':avatar'     => $d['avatar']    ?? '',
            ':chat_type'  => $d['chatType']  ?? $d['chat_type'] ?? 'private',
            ':col'        => $d['col']       ?? '#7c6ef5',
            ':stage'      => $d['stage']     ?? 'new',
            ':last_msg'   => $d['last']      ?? $d['last_msg'] ?? '',
            ':last_t'     => $d['t']         ?? $d['last_t']   ?? '',
            ':ai_status'  => $d['ai']        ?? $d['ai_status'] ?? 'waiting',
            ':agent'      => $d['agent']     ?? 'Sales Bot',
            ':agent_id'   => $agentId,
            ':auto_reply' => $autoReply,
            ':unread'     => intval($d['unread'] ?? 0),
            ':account_id' => $ACCOUNT_ID,
        ]);
        ok(['agent_id'=>$agentId, 'auto_reply'=>(int)$autoReply]);

    // ── CONTACT SYNC — keeps bc_contacts in step with bc_conversations ──
    // Called by the JS on startup and after any conversation update so the
    // ghost contact_search always has live data. Also called by the peer
    // warm-up path to piggyback on the existing API round-trip.
    case 'sync_contacts':
        try {
            // Upsert all conversations for this account into bc_contacts.
            $convs = $pdo->prepare("
                SELECT id, name, handle, platform, chat_id, updated_at, last_t
                FROM bc_conversations
                WHERE account_id = ? AND platform <> 'direct'
                ORDER BY updated_at DESC, last_t DESC
                LIMIT 500
            ");
            $convs->execute([$ACCOUNT_ID]);
            $upsert = $pdo->prepare("
                INSERT INTO bc_contacts (account_id, conv_id, name, handle, channel, chat_id, last_message_at)
                VALUES (?, ?, ?, ?, ?, ?, NOW())
                ON DUPLICATE KEY UPDATE
                    name=VALUES(name), handle=VALUES(handle),
                    channel=VALUES(channel), chat_id=VALUES(chat_id),
                    last_message_at=NOW()
            ");
            $count = 0;
            while ($r = $convs->fetch(PDO::FETCH_ASSOC)) {
                $upsert->execute([$ACCOUNT_ID, $r['id'], $r['name']??'', $r['handle']??'', $r['platform']??'telegram', $r['chat_id']??'']);
                $count++;
            }
            ok(['synced' => $count]);
        } catch (Throwable $e) {
            err('sync_contacts failed: ' . $e->getMessage());
        }

    // ── PEER CACHE — persist resolved Telegram InputPeer data server-side ──
    // Survives process restarts so the ghost can send proactively without
    // requiring the contact to message first every session.
    case 'save_peer_cache':
        if (empty($body['platform']) || empty($body['chat_id'])) err('platform and chat_id required');
        try {
            $pdo->prepare("
                INSERT INTO bc_tg_peer_cache (account_id, platform, chat_id, handle, peer_data, resolved_at)
                VALUES (?, ?, ?, ?, ?, NOW())
                ON DUPLICATE KEY UPDATE
                    handle=VALUES(handle), peer_data=VALUES(peer_data), resolved_at=NOW()
            ")->execute([
                $ACCOUNT_ID,
                $body['platform'],
                $body['chat_id'],
                $body['handle'] ?? '',
                isset($body['peer_data']) ? json_encode($body['peer_data']) : null,
            ]);
            ok();
        } catch (Throwable $e) {
            err('save_peer_cache failed: ' . $e->getMessage());
        }

    case 'get_peer_cache':
        try {
            $platform = $body['platform'] ?? 'telegram';
            $st = $pdo->prepare("
                SELECT platform, chat_id, handle, peer_data, resolved_at
                FROM bc_tg_peer_cache
                WHERE account_id = ? AND platform = ?
                ORDER BY resolved_at DESC
                LIMIT 1000
            ");
            $st->execute([$ACCOUNT_ID, $platform]);
            $peers = [];
            while ($r = $st->fetch(PDO::FETCH_ASSOC)) {
                $peers[] = [
                    'platform'    => $r['platform'],
                    'chat_id'     => $r['chat_id'],
                    'handle'      => $r['handle'],
                    'peer_data'   => $r['peer_data'] ? json_decode($r['peer_data'], true) : null,
                    'resolved_at' => $r['resolved_at'],
                ];
            }
            ok(['peers' => $peers]);
        } catch (Throwable $e) {
            ok(['peers' => []]); // non-fatal
        }

    case 'mark_read':
        if (empty($body['id'])) err('id required');
        own_conv($pdo, $ACCOUNT_ID, $body['id']);
        $pdo->prepare("UPDATE bc_conversations SET unread=0 WHERE id=? AND account_id=?")
            ->execute([$body['id'], $ACCOUNT_ID]);
        ok();

    case 'update_stage':
        if (empty($body['id']) || empty($body['stage'])) err('id and stage required');
        own_conv($pdo, $ACCOUNT_ID, $body['id']);
        $pdo->prepare("UPDATE bc_conversations SET stage=? WHERE id=? AND account_id=?")
            ->execute([$body['stage'], $body['id'], $ACCOUNT_ID]);
        ok();

    case 'assign_agent':
        // Move a conversation to a different agent. Pass agent_id=null to clear.
        if (empty($body['id'])) err('id required');
        own_conv($pdo, $ACCOUNT_ID, $body['id']);
        $aid = isset($body['agent_id']) && $body['agent_id'] !== '' ? (int)$body['agent_id'] : null;
        // Who asked for this?
        //   operator=1 → a human clicked the agent picker. Their decision is
        //                recorded so the inbound backfill can't quietly undo
        //                it after a restart.
        //   resume=1   → the same human is putting an agent BACK on, which
        //                lifts a post-sale stop (see post_sale_resume_at).
        // The automatic first-contact backfill sends neither, so it can
        // never resurrect an agent the operator (or a post-sale stop) took
        // off, and can never cancel a stop-after-sale.
        $isOperator = !empty($body['operator']);
        $isResume   = ($aid !== null) && !empty($body['resume']);
        $wantAuto   = ($aid !== null) && !empty($body['auto_reply']);
        // Unassigning records WHY when the caller knows (post-sale stop,
        // escalation). Assigning always clears it — putting an agent back on
        // is the answer to whatever the reason was, so leaving the notice up
        // would be stale the instant it stopped being true.
        $ureason = $aid ? '' : mb_substr(trim((string)($body['reason'] ?? '')), 0, 160);

        // Resolve the target agent BEFORE writing anything. own_agent() exits
        // on a bad id, and half-applying a resume (auto_reply raised, agent
        // never changed) would leave the PREVIOUS agent talking — the sort of
        // partial state this whole fix exists to eliminate.
        $aname = '';
        if ($aid) {
            // Verify the agent also belongs to this account.
            own_agent($pdo, $ACCOUNT_ID, $aid);
            $a = $pdo->prepare("SELECT name FROM bc_agents WHERE id=? AND account_id=?");
            $a->execute([$aid, $ACCOUNT_ID]);
            $aname = (string)$a->fetchColumn();
        }

        // The assignment itself, and the auto_reply that has to travel with
        // it, go in ONE statement against columns that have existed since the
        // first release. An agent that is assigned but muted is the state this
        // bug lived in — the header named someone and nothing ever replied —
        // so the two values must never be written separately and never be
        // able to disagree because a follow-up call was lost or raced.
        $pdo->prepare("UPDATE bc_conversations SET agent_id=?, agent=?"
                      . ($wantAuto ? ", auto_reply=1" : "")
                      . " WHERE id=? AND account_id=?")
            ->execute([$aid, $aname ?: 'Sales Bot', $body['id'], $ACCOUNT_ID]);

        // The newer bookkeeping columns go in a second, optional statement so
        // an install that has not run the migration still assigns correctly.
        try {
            if ($aid) {
                // post_sale_resume_at is stamped ONLY for a deliberate
                // re-assignment. From this instant the post-sale gate in
                // ai_reply counts only purchases made AFTER now, so the agent
                // is free to talk again about the sale that already happened —
                // and still stops if the customer buys again.
                $sql = "UPDATE bc_conversations SET unassign_reason='', unassigned_at=NULL"
                     . ($isOperator ? ", operator_override=1" : "")
                     . ($isResume   ? ", post_sale_resume_at=NOW()" : "")
                     . " WHERE id=? AND account_id=?";
                $pdo->prepare($sql)->execute([$body['id'], $ACCOUNT_ID]);
            } else {
                // Coming off clears the resume marker, so the NEXT sale stops
                // the agent again exactly as it did the first time.
                $pdo->prepare("UPDATE bc_conversations SET unassign_reason=?, unassigned_at=NOW(), post_sale_resume_at=NULL, operator_override=1 WHERE id=? AND account_id=?")
                    ->execute([$ureason, $body['id'], $ACCOUNT_ID]);
            }
        } catch (\Throwable $e) {
            // Older schema without the columns — assignment still works.
            error_log('[assign_agent] reason write skipped: ' . $e->getMessage());
        }

        // Echo the resulting state back so the client can confirm the resume
        // actually landed before it asks for a reply.
        $ar = 0;
        try {
            $arq = $pdo->prepare("SELECT auto_reply FROM bc_conversations WHERE id=? AND account_id=?");
            $arq->execute([$body['id'], $ACCOUNT_ID]);
            $ar = (int)$arq->fetchColumn();
        } catch (\Throwable $e) { /* non-fatal */ }
        if ($ar) bot_relay_nudge($pdo, (int)$ACCOUNT_ID, (string)$body['id']);
        ok(['agent_id'=>$aid,'agent'=>$aname,'auto_reply'=>$ar,'resumed'=>$isResume ? 1 : 0]);

    case 'set_auto_reply':
        // Toggle auto-reply for a single conversation.
        if (empty($body['id'])) err('id required');
        own_conv($pdo, $ACCOUNT_ID, $body['id']);
        $on = !empty($body['on']) ? 1 : 0;
        $pdo->prepare("UPDATE bc_conversations SET auto_reply=? WHERE id=? AND account_id=?")
            ->execute([$on, $body['id'], $ACCOUNT_ID]);
        if ($on) bot_relay_nudge($pdo, (int)$ACCOUNT_ID, (string)$body['id']);
        ok(['on'=>$on]);

    case 'delete_conversation':
        if (empty($body['id'])) err('id required');
        own_conv($pdo, $ACCOUNT_ID, $body['id']);
        $convId = $body['id'];
        // ── FULL END-USER WIPE ─────────────────────────────────────────
        // Deleting a contact must leave NOTHING behind that a later inbound
        // (or the AI pipeline) could resurface — no orphaned serial keys,
        // invoices/transactions, or licence-audit rows. Previously this case
        // only deleted bc_messages + bc_conversations + bc_end_users (the link
        // row), which ORPHANED every bc_end_user_products / _transactions /
        // ai_license_log row keyed by end_user_id: the data stayed in the DB
        // forever, and because the link row was gone, reset_end_user could
        // never find it to clean up either. The agent could then still surface
        // a "returning customer" with prior purchases the operator thought
        // they'd deleted. We now resolve the end_user_id FIRST and delete its
        // dependent rows before removing anything, so a deleted contact always
        // comes back as genuinely fresh.
        $euIds = [];
        try {
            $euq = $pdo->prepare("SELECT id FROM bc_end_users WHERE account_id=? AND conv_id=?");
            $euq->execute([$ACCOUNT_ID, $convId]);
            $euIds = array_map('intval', array_column($euq->fetchAll(), 'id'));
        } catch (Throwable $e) { /* table shape — ignore */ }
        foreach ($euIds as $euId) {
            if ($euId <= 0) continue;
            $pdo->prepare("DELETE FROM bc_end_user_products     WHERE account_id=? AND end_user_id=?")
                ->execute([$ACCOUNT_ID, $euId]);
            $pdo->prepare("DELETE FROM bc_end_user_transactions WHERE account_id=? AND end_user_id=?")
                ->execute([$ACCOUNT_ID, $euId]);
            // bc_ai_license_log only exists where the licensing migration ran.
            try {
                $pdo->prepare("DELETE FROM bc_ai_license_log WHERE account_id=? AND end_user_id=?")
                    ->execute([$ACCOUNT_ID, $euId]);
            } catch (Throwable $e) { /* table absent — ignore */ }
        }
        // Belt-and-brace: also clear rows keyed by conv_id directly, covering
        // any stragglers whose end_user_id link was severed by an earlier
        // partial delete (so we never leave a serial/invoice tied to this conv).
        try {
            $pdo->prepare("DELETE FROM bc_ai_license_log WHERE account_id=? AND conv_id=?")
                ->execute([$ACCOUNT_ID, $convId]);
        } catch (Throwable $e) { /* ignore */ }

        $pdo->prepare("DELETE FROM bc_messages WHERE conv_id=? AND account_id=?")
            ->execute([$convId, $ACCOUNT_ID]);
        $pdo->prepare("DELETE FROM bc_conversations WHERE id=? AND account_id=?")
            ->execute([$convId, $ACCOUNT_ID]);
        // Wipe bc_end_users row too. Without this, a stale is_blocked / is_muted /
        // escalation flag survives the delete and silently blocks ai_reply the next
        // time this contact messages (conv row re-created by save_conversation, but
        // the old bc_end_users row is never cleared). Safe to delete — a fresh row
        // is re-created by upsert_end_user_meta / INSERT IGNORE on the next inbound.
        $pdo->prepare("DELETE FROM bc_end_users WHERE conv_id=? AND account_id=?")
            ->execute([$convId, $ACCOUNT_ID]);
        // Also wipe the memory file
        $mp = mem_path($convId);
        if (is_file($mp)) @unlink($mp);
        ok();

    // ── MESSAGES ─────────────────────────────────────────────
    case 'get_messages':
        if (empty($_GET['conv_id'])) err('conv_id required');
        own_conv($pdo, $ACCOUNT_ID, $_GET['conv_id']);
        // created_epoch — UNIX_TIMESTAMP() reads created_at in the same
        // session timezone MySQL wrote it in, so it is a true epoch no matter
        // what PHP's default timezone is. strtotime() on the raw DATETIME
        // string assumed PHP's zone, and on hosts where the two differ every
        // bubble was offset by hours from the escalation / chapter / invoice
        // stamps the chat's separators are placed against.
        $rows = $pdo->prepare("SELECT *, UNIX_TIMESTAMP(created_at) AS created_epoch FROM bc_messages WHERE conv_id=? AND account_id=? ORDER BY created_at ASC, id ASC");
        $rows->execute([$_GET['conv_id'], $ACCOUNT_ID]);
        $msgs = array_map(fn($r)=>[
            // Row id — lets the chat place notes, chapters and escalations
            // against the exact message the server anchored them to, instead
            // of guessing from timestamps.
            'id'=>(int)($r['id'] ?? 0),
            'r'=>$r['role'], 'c'=>$r['content'], 't'=>$r['ts'],
            // ts_epoch (seconds since epoch). The realism state-block uses
            // this to compute "time since last inbound" / "time since last
            // outbound" so the LLM can decide whether the latest message
            // is part of a fresh burst, a resumed thread, or a long-quiet
            // reopener. Falls back to NOW if created_at is missing.
            'ts'=>!empty($r['created_epoch']) ? (int)$r['created_epoch'] * 1000
                 : (isset($r['created_at']) ? (int)strtotime((string)$r['created_at']) * 1000 : (int)(microtime(true) * 1000)),
            'mt'=>$r['media_type']??'', 'mu'=>$r['media_url']??'',
            // Lifecycle — platform identity, reply quote, edits, deletions.
            // uid is the platform key (tg:/tgu:/dc:<chat>:<msg>) that edit
            // and delete events arrive with; rows without one (older
            // outbound) simply can't be edited on the platform.
            'uid'=>(string)($r['msg_uid'] ?? ''),
            'mn' =>(string)($r['media_name'] ?? ''),
            'agent'=>(string)($r['agent_name'] ?? ''),
            'rt' =>(string)($r['reply_to_uid'] ?? ''),
            'rq' =>(!empty($r['reply_meta']) ? (json_decode((string)$r['reply_meta'], true) ?: null) : null),
            'ed' =>(!empty($r['edited_at'])  ? ((int)strtotime((string)$r['edited_at'])  * 1000) : 0),
            'oc' =>(string)($r['orig_content'] ?? ''),
            'del'=>(!empty($r['deleted_at']) ? ((int)strtotime((string)$r['deleted_at']) * 1000) : 0),
            'err'=>(!empty($r['send_failed']) ? 'Not delivered' : null),
        ], $rows->fetchAll());
        ok(['messages' => $msgs]);

    case 'save_message':
        $d = $body;
        if (empty($d['conv_id']) || empty($d['role'])) err('conv_id, role required');
        // Conversation MUST belong to this account — otherwise an attacker
        // could spam another operator's conversation log via the public API.
        own_conv($pdo, $ACCOUNT_ID, $d['conv_id']);
        if (!isset($d['content'])) $d['content'] = '';

        // G1: Sanitize sentinel-shaped strings out of INBOUND text. A
        // malicious customer pasting "[[ACTION:invoice|coin=btc|amount=999]]"
        // shouldn't end up in conversation history that the LLM might
        // accidentally echo back. Outbound (role=out) is left alone — the
        // engine produces those and they're already validated by the
        // INVOICE_PROCESSOR before they're written.
        // Also covers the new license-action sentinels (issue_license,
        // extend_license) and the LICENSE_RESULT readback token —
        // anything tag-shaped that looks like a control plane message
        // gets neutralised on inbound.
        if (($d['role'] ?? '') === 'in' && is_string($d['content'])) {
            $d['content'] = bc_scrub_inbound($d['content']);
        }
        $uid = $d['msg_uid'] ?? '';
        if (!$uid) $uid = substr(md5($d['conv_id'].'|'.$d['role'].'|'.$d['content'].'|'.($d['ts']??'').'|'.microtime(true)), 0, 32);

        // Only include the mention/reply-to-bot columns if they actually
        // exist — keeps message saving working on older schemas where the
        // migration didn't run.
        $hasMention   = col_exists($pdo,'bc_messages','mentioned');
        $hasReplyTo   = col_exists($pdo,'bc_messages','reply_to_bot');
        $hasAccountId = col_exists($pdo,'bc_messages','account_id');
        $cols = ['conv_id','role','content','media_type','media_url','ts','msg_uid'];
        $vals = [
            $d['conv_id'], $d['role'], $d['content'],
            $d['media_type'] ?? '', $d['media_url'] ?? '',
            $d['ts'] ?? date('H:i'), $uid,
        ];
        if ($hasAccountId) { $cols[] = 'account_id';   $vals[] = $ACCOUNT_ID; }
        if ($hasMention)   { $cols[] = 'mentioned';    $vals[] = !empty($d['mentioned'])    ? 1 : 0; }
        if ($hasReplyTo)   { $cols[] = 'reply_to_bot'; $vals[] = !empty($d['reply_to_bot']) ? 1 : 0; }
        // Reply / attachment metadata (lifecycle columns — see migration).
        $mcols = bc_msg_cols($pdo);
        if (isset($mcols['reply_to_uid']) && !empty($d['reply_to_uid'])) {
            $cols[] = 'reply_to_uid'; $vals[] = mb_substr((string)$d['reply_to_uid'], 0, 100);
        }
        // The quoted message is often older than what the page has loaded,
        // so the page may only know its id. Fill the snapshot in from the
        // stored row when it exists; the resolved quote goes back to the page.
        $rqOut = null;
        if (isset($mcols['reply_meta']) && (!empty($d['reply_meta']) || !empty($d['reply_to_uid']))) {
            $rqArr = [];
            if (!empty($d['reply_meta'])) {
                $tmp = json_decode(bc_reply_meta_json($d['reply_meta']), true);
                if (is_array($tmp)) $rqArr = $tmp;
            }
            if (!empty($d['reply_to_uid']) && (($rqArr['c'] ?? '') === '' && ($rqArr['mt'] ?? '') === '')) {
                try {
                    $rs = $pdo->prepare("SELECT role, content, media_type FROM bc_messages WHERE account_id=? AND conv_id=? AND msg_uid=? LIMIT 1");
                    $rs->execute([$ACCOUNT_ID, $d['conv_id'], (string)$d['reply_to_uid']]);
                    if ($tr = $rs->fetch()) {
                        $rqArr['r']  = (string)$tr['role'];
                        $rqArr['c']  = mb_substr((string)$tr['content'], 0, 280);
                        $rqArr['mt'] = (string)$tr['media_type'];
                    }
                } catch (Throwable $e) { /* best effort */ }
            }
            if (!empty($d['reply_to_uid'])) $rqArr['uid'] = (string)$d['reply_to_uid'];
            $rm = bc_reply_meta_json($rqArr);
            if ($rm !== '') { $cols[] = 'reply_meta'; $vals[] = $rm; $rqOut = json_decode($rm, true); }
        }
        if (isset($mcols['media_name']) && !empty($d['media_name'])) {
            $cols[] = 'media_name'; $vals[] = mb_substr((string)$d['media_name'], 0, 255);
        }
        // The agent that wrote an AI message, frozen on the row. The page
        // sends it; if it didn't, the conversation's agent at this moment is
        // the one that wrote it.
        if (isset($mcols['agent_name']) && ($d['role'] ?? '') === 'bot') {
            $agName = trim((string)($d['agent_name'] ?? ($d['agent'] ?? '')));
            if ($agName === '') {
                try {
                    $as = $pdo->prepare("SELECT agent FROM bc_conversations WHERE id=? AND account_id=? LIMIT 1");
                    $as->execute([$d['conv_id'], $ACCOUNT_ID]);
                    $agName = trim((string)($as->fetchColumn() ?: ''));
                } catch (Throwable $e) { $agName = ''; }
            }
            if ($agName !== '') { $cols[] = 'agent_name'; $vals[] = mb_substr($agName, 0, 100); }
        }
        $ph = implode(',', array_fill(0, count($cols), '?'));
        $sql = "INSERT INTO bc_messages (".implode(',', $cols).") VALUES ($ph)";
        try {
            $pdo->prepare($sql)->execute($vals);
            $newId = $pdo->lastInsertId();
        } catch (PDOException $e) {
            if ($e->getCode() == '23000') { ok(['id'=>0,'duplicate'=>true]); }
            throw $e;
        }
        $preview = $d['content'] !== '' ? $d['content'] : (!empty($d['media_name']) ? ('📎 ' . $d['media_name']) : ('['.($d['media_type']??'media').']'));
        $pdo->prepare("UPDATE bc_conversations SET last_msg=?, last_t=?, updated_at=NOW() WHERE id=? AND account_id=?")
            ->execute([$preview, $d['ts'] ?? date('H:i'), $d['conv_id'], $ACCOUNT_ID]);
        ok(['id' => $newId, 'rq' => $rqOut]);

    // ── MESSAGE LIFECYCLE ────────────────────────────────────
    // update_message — patch one row, found by server id or by msg_uid.
    //   content      new text (edit). Records edited_at + the original.
    //   new_uid      the platform identity learned after sending
    //   deleted      1 = tombstone (deleted on the platform), 0 = restore
    //   media_url / media_type / media_name   late-arriving attachment
    case 'update_message': {
        $d = $body;
        $convId = (string)($d['conv_id'] ?? '');
        if ($convId === '') err('conv_id required');
        own_conv($pdo, $ACCOUNT_ID, $convId);
        $mcols = bc_msg_cols($pdo);
        $mid = (int)($d['id'] ?? 0);
        $uid = trim((string)($d['uid'] ?? ''));
        if ($mid <= 0 && $uid === '') err('id or uid required');
        if ($mid > 0) {
            $cur = $pdo->prepare("SELECT id, role, content FROM bc_messages WHERE id=? AND conv_id=? AND account_id=? LIMIT 1");
            $cur->execute([$mid, $convId, $ACCOUNT_ID]);
        } else {
            $cur = $pdo->prepare("SELECT id, role, content FROM bc_messages WHERE msg_uid=? AND conv_id=? AND account_id=? ORDER BY id ASC LIMIT 1");
            $cur->execute([$uid, $convId, $ACCOUNT_ID]);
        }
        $row = $cur->fetch();
        if (!$row) ok(['updated' => 0, 'missing' => true]);

        $sets = []; $vals = [];
        if (array_key_exists('content', $d) && is_string($d['content'])) {
            $newText = $d['content'];
            if ($row['role'] === 'in') $newText = bc_scrub_inbound($newText);
            if ($newText !== (string)$row['content']) {
                $sets[] = 'content=?'; $vals[] = $newText;
                if (isset($mcols['edited_at']))    { $sets[] = 'edited_at=NOW()'; }
                if (isset($mcols['orig_content'])) { $sets[] = 'orig_content=COALESCE(orig_content, ?)'; $vals[] = (string)$row['content']; }
            }
        }
        if (array_key_exists('deleted', $d) && isset($mcols['deleted_at'])) {
            $sets[] = !empty($d['deleted']) ? 'deleted_at=COALESCE(deleted_at, NOW())' : 'deleted_at=NULL';
        }
        // Delivery failure reported by the platform (outbound rows only).
        if (array_key_exists('send_failed', $d) && isset($mcols['send_failed']) && ($row['role'] ?? '') !== 'in') {
            $sets[] = 'send_failed=?'; $vals[] = !empty($d['send_failed']) ? 1 : 0;
        }
        if (array_key_exists('media_url', $d) && is_string($d['media_url'])) {
            $sets[] = 'media_url=?'; $vals[] = $d['media_url'];
        }
        if (!empty($d['media_type']) && is_string($d['media_type'])) {
            $sets[] = 'media_type=?'; $vals[] = mb_substr($d['media_type'], 0, 20);
        }
        if (!empty($d['media_name']) && isset($mcols['media_name'])) {
            $sets[] = 'media_name=?'; $vals[] = mb_substr((string)$d['media_name'], 0, 255);
        }
        if (!empty($d['reply_to_uid']) && isset($mcols['reply_to_uid'])) {
            $sets[] = 'reply_to_uid=?'; $vals[] = mb_substr((string)$d['reply_to_uid'], 0, 100);
        }
        if (!empty($d['reply_meta']) && isset($mcols['reply_meta'])) {
            $rm = bc_reply_meta_json($d['reply_meta']);
            if ($rm !== '') { $sets[] = 'reply_meta=?'; $vals[] = $rm; }
        }
        $newUid = trim((string)($d['new_uid'] ?? ''));
        if (!$sets && $newUid === '') ok(['updated' => 0, 'id' => (int)$row['id']]);
        if ($sets) {
            $vals[] = (int)$row['id'];
            $pdo->prepare("UPDATE bc_messages SET " . implode(', ', $sets) . " WHERE id=?")->execute($vals);
        }
        // The platform identity goes on separately: it is unique per
        // (account, conv), and a duplicate (the same ack delivered twice)
        // must not undo the edit above.
        if ($newUid !== '') {
            try {
                $pdo->prepare("UPDATE bc_messages SET msg_uid=? WHERE id=?")
                    ->execute([mb_substr($newUid, 0, 100), (int)$row['id']]);
            } catch (PDOException $e) {
                if ($e->getCode() != '23000') throw $e;
            }
        }
        bc_refresh_conv_preview($pdo, $ACCOUNT_ID, $convId);
        ok(['updated' => 1, 'id' => (int)$row['id']]);
    }

    // mark_messages_deleted — the platform reported messages deleted.
    //   platform  telegram | discord
    //   prefix    tg | tgu | dc   (which API numbered the ids)
    //   chat_id   optional. Telegram's User API does not say which private
    //             chat a deletion belongs to (ids are unique per account
    //             there), so without it the match is by id across this
    //             account's private and basic-group Telegram chats.
    //   ids       platform message ids
    case 'mark_messages_deleted': {
        $d = $body;
        $platform = strtolower((string)($d['platform'] ?? ''));
        if (!in_array($platform, ['telegram', 'discord'], true)) err('bad platform');
        $prefix = strtolower((string)($d['prefix'] ?? ($platform === 'discord' ? 'dc' : 'tgu')));
        if (!in_array($prefix, ['tg', 'tgu', 'dc'], true)) err('bad prefix');
        $ids = array_values(array_unique(array_filter(array_map(
            fn($x) => preg_replace('/\D/', '', (string)$x), (array)($d['ids'] ?? [])
        ), fn($x) => $x !== '')));
        if (!$ids) ok(['updated' => 0, 'convs' => []]);
        $ids = array_slice($ids, 0, 500);
        $mcols = bc_msg_cols($pdo);
        if (!isset($mcols['deleted_at'])) ok(['updated' => 0, 'convs' => []]);
        $chatId = preg_replace('/[^0-9\-]/', '', (string)($d['chat_id'] ?? ''));
        $n = 0; $convs = [];
        if ($chatId !== '') {
            $convId = $platform . '_' . $chatId;
            $uids = array_map(fn($i) => $prefix . ':' . $chatId . ':' . $i, $ids);
            $ph = implode(',', array_fill(0, count($uids), '?'));
            $st = $pdo->prepare("UPDATE bc_messages SET deleted_at=NOW() WHERE account_id=? AND conv_id=? AND deleted_at IS NULL AND msg_uid IN ($ph)");
            $st->execute(array_merge([$ACCOUNT_ID, $convId], $uids));
            $n = $st->rowCount();
            if ($n > 0) $convs[] = $convId;
        } else {
            // Private + basic-group chats only: supergroup/channel ids are
            // numbered per channel and arrive with their channel id.
            $find = $pdo->prepare("SELECT m.id, m.conv_id FROM bc_messages m
                JOIN bc_conversations c ON c.id = m.conv_id AND c.account_id = m.account_id
                WHERE m.account_id=? AND m.deleted_at IS NULL AND m.conv_id LIKE 'telegram\_%'
                  AND COALESCE(c.chat_type,'private') NOT IN ('supergroup','channel')
                  AND m.msg_uid LIKE ?");
            foreach ($ids as $i) {
                $find->execute([$ACCOUNT_ID, $prefix . ':%:' . $i]);
                foreach ($find->fetchAll() as $hit) {
                    $pdo->prepare("UPDATE bc_messages SET deleted_at=NOW() WHERE id=?")->execute([(int)$hit['id']]);
                    $n++;
                    $convs[(string)$hit['conv_id']] = true;
                }
            }
            $convs = array_keys($convs);
        }
        foreach ($convs as $cv) bc_refresh_conv_preview($pdo, $ACCOUNT_ID, $cv);
        ok(['updated' => $n, 'convs' => $convs]);
    }

    // delete_message — remove a row from this app's history entirely (the
    // operator's "Remove from this chat"). Platform-side deletion is done by
    // the desktop host; this only affects what the app and the AI remember.
    case 'delete_message': {
        $d = $body;
        $convId = (string)($d['conv_id'] ?? '');
        if ($convId === '') err('conv_id required');
        own_conv($pdo, $ACCOUNT_ID, $convId);
        $mid = (int)($d['id'] ?? 0);
        $uid = trim((string)($d['uid'] ?? ''));
        if ($mid > 0) {
            $st = $pdo->prepare("DELETE FROM bc_messages WHERE id=? AND conv_id=? AND account_id=?");
            $st->execute([$mid, $convId, $ACCOUNT_ID]);
        } elseif ($uid !== '') {
            $st = $pdo->prepare("DELETE FROM bc_messages WHERE msg_uid=? AND conv_id=? AND account_id=?");
            $st->execute([$uid, $convId, $ACCOUNT_ID]);
        } else {
            err('id or uid required');
        }
        bc_refresh_conv_preview($pdo, $ACCOUNT_ID, $convId);
        ok(['deleted' => $st->rowCount()]);
    }

    // ── PRODUCTS ─────────────────────────────────────────────
    case 'get_products':
        $rows = $pdo->prepare("SELECT * FROM bc_products WHERE account_id=? ORDER BY id ASC");
        $rows->execute([$ACCOUNT_ID]);
        // Live stock-list counts, one query for the whole catalogue.
        $stockCounts = stock_counts($pdo, (int)$ACCOUNT_ID);
        $out  = array_map(fn($r) => [
            'id'           => (int)$r['id'],
            'type'         => $r['type'],
            'name'         => $r['name'],
            'sku'          => $r['sku'],
            'price'        => $r['price'],
            // Falls back to USD for rows written before the column existed.
            'priceCurrency'=> strtoupper((string)($r['price_currency'] ?? '') ?: 'USD'),
            'billing'      => $r['billing'],
            'stock'        => $r['stock'],
            'expiry'       => $r['expiry'],
            'img'          => $r['img'],
            'desc'         => $r['description'],
            'feats'        => $r['feats']    ? json_decode($r['feats'],    true) : [],
            'products'     => $r['products'] ? json_decode($r['products'], true) : [],
            // Per-product media library: array of {id,kind,url,label,desc,showcase,...}.
            // Returned to the editor and merged into the AI catalogue dump.
            'media'        => isset($r['media']) && $r['media'] ? (json_decode($r['media'], true) ?: []) : [],
            // Operator-authored text the bot sends verbatim after a confirmed
            // purchase of this product (delivered by the invoiceConfirmed
            // handler, deterministic — no LLM rewrite). Used for download
            // instructions, credentials, "thanks!" messages etc.
            'postPaymentText' => isset($r['post_payment_text']) ? (string)$r['post_payment_text'] : '',
            'manualTasks'  => (isset($r['manual_tasks']) && $r['manual_tasks']) ? (json_decode($r['manual_tasks'], true) ?: []) : [],
            'enabledForAi' => isset($r['enabled_for_ai']) ? (bool)$r['enabled_for_ai'] : true,
            // Per-product provisioning toggles consumed by the editor and by
            // the add-purchase flow (so the form only shows username/serial
            // fields when the product actually issues them).
            'allowUsername'        => !empty($r['allow_username']),
            'allowSerial'          => !empty($r['allow_serial']),
            'allowAccountCreation' => !empty($r['allow_account_creation']),
            // Refunds default ON for existing rows (column default = 1) so a
            // missing value is treated as "yes, refunds OK" — flipping to
            // false is an explicit operator decision that escalates refund
            // requests to a human instead.
            // Matches the agent-side rule exactly (see the catalogue builder):
            // present-and-truthy means refundable, anything else does not.
            // These two MUST agree — the toggle showing one thing while the
            // agent believes another is the bug that started all this.
            'allowRefund'          => array_key_exists('allow_refund', $r) && !empty($r['allow_refund']),
            // Mailing-site integration: push serial to lefty.pro/mailing on issue.
            'allowMailingSite'     => !empty($r['allow_mailing_site']),
            // Stock list: hand out one pasted item (key, code, login…) per sale.
            // The items themselves are loaded on demand (stock_list), never
            // with the catalogue.
            'stockMode'            => !empty($r['stock_mode']),
            'stockLabel'           => (string)($r['stock_label'] ?? ''),
            'stockWhenEmpty'       => (($r['stock_empty'] ?? '') === 'hold') ? 'hold' : 'hide',
            'stockCount'           => $stockCounts[(int)$r['id']] ?? stock_zero(),
        ], $rows->fetchAll());
        ok(['products' => $out]);

    case 'save_product':
        // INSERT (id=0/null/missing) or UPDATE (id present and owned).
        $d = $body;
        $hasId = isset($d['id']) && (int)$d['id'] > 0;

        // A nameless product renders as a blank row that the operator can
        // barely identify, let alone fix. Reject it here rather than trust
        // every caller to validate: INSERT always needs a name, and an
        // UPDATE that explicitly sends an empty name is refused too (absent
        // is fine — that means "leave the existing name alone").
        if (!$hasId) {
            if (trim((string)($d['name'] ?? '')) === '') {
                err('A product needs a name.');
            }
        } elseif (array_key_exists('name', $d) && trim((string)$d['name']) === '') {
            err('A product name cannot be blank.');
        }

        // Pricing currency. Whitelisted against the same ISO-4217 set the
        // picker offers so a typo (or a model hallucinating "DOLLARS") can't
        // write junk that the symbol lookup would then fail to resolve.
        // NULL when the key is absent so an UPDATE leaves it alone; the
        // INSERT path coerces NULL to USD.
        $FIAT_CODES = ['USD','EUR','GBP','AUD','CAD','NZD','JPY','CHF','SEK','NOK',
                       'DKK','INR','BRL','ZAR','MXN','SGD','HKD','PLN','CZK','HUF',
                       'TRY','AED','SAR','ILS','KRW','CNY','THB','MYR','PHP','IDR',
                       'VND','NGN','KES','RUB','UAH','RON','BGN','HRK','ISK','CLP',
                       'COP','ARS','PEN','TWD'];
        $priceCurrency = null;
        if (array_key_exists('priceCurrency', $d) || array_key_exists('price_currency', $d)) {
            $raw = strtoupper(trim((string)($d['priceCurrency'] ?? $d['price_currency'] ?? '')));
            if ($raw !== '') {
                if (!in_array($raw, $FIAT_CODES, true)) {
                    err('Unsupported currency: ' . htmlspecialchars($raw) . '. Use a 3-letter ISO code such as USD, AUD or EUR.');
                }
                $priceCurrency = $raw;
            }
        }
        if ($hasId) {
            // Verify ownership before allowing update — silently rejects an
            // attempt to overwrite another operator's product row.
            own_product($pdo, $ACCOUNT_ID, (int)$d['id']);
        }
        // NULL when the key is absent so an UPDATE leaves the existing value
        // alone; the INSERT path below coerces NULL to 1 (new products start
        // enabled). Previously this defaulted to 1 unconditionally, which
        // meant any partial update silently re-enabled a product the operator
        // had deliberately switched off.
        $enabledForAiRaw = array_key_exists('enabledForAi', $d)
            ? (int)!!$d['enabledForAi']
            : null;
        $enabledForAi = $enabledForAiRaw === null ? 1 : $enabledForAiRaw;

        // Same rule for the two JSON list columns. json_encode(null ?? [])
        // yields '[]', so the old unconditional encode wiped an operator's
        // feature list and bundle contents on every partial update.
        $featsJson    = array_key_exists('feats',    $d) ? json_encode($d['feats']    ?? []) : null;
        $productsJson = array_key_exists('products', $d) ? json_encode($d['products'] ?? []) : null;
        // Provisioning flags. Default OFF for new products and unchanged
        // semantics — only writes when the key is present in the payload
        // so an old client that doesn't send them won't clobber existing
        // values on update.
        $allowUsername  = array_key_exists('allowUsername',        $d) ? (int)!!$d['allowUsername']        : null;
        $allowSerial    = array_key_exists('allowSerial',          $d) ? (int)!!$d['allowSerial']          : null;
        $allowAcctCreate= array_key_exists('allowAccountCreation', $d) ? (int)!!$d['allowAccountCreation'] : null;
        // allowRefund — null when key absent (don't clobber on update); on
        // INSERT we coerce the absent case to 1 (refunds permitted by
        // default — matches the column default).
        $allowRefund    = array_key_exists('allowRefund',          $d) ? (int)!!$d['allowRefund']          : null;
        $allowMailingSite = array_key_exists('allowMailingSite',   $d) ? (int)!!$d['allowMailingSite']     : null;

        // ── Media library sanitiser ───────────────────────────────────
        // Keep only well-formed entries. Each entry is normalised into a
        // stable shape so the AI catalogue dump and editor reads stay
        // predictable. `kind` is restricted to image/file/link; bad URLs
        // are tolerated (the editor surfaces them) but anything missing
        // both `url` AND `label` is dropped as junk.
        $sanitiseMedia = function($raw) {
            if (!is_array($raw)) return [];
            $out = [];
            foreach ($raw as $m) {
                if (!is_array($m)) continue;
                $url   = trim((string)($m['url']   ?? ''));
                $label = trim((string)($m['label'] ?? ''));
                if ($url === '' && $label === '') continue;
                $kind = strtolower(trim((string)($m['kind'] ?? 'file')));
                if (!in_array($kind, ['image','file','link'], true)) $kind = 'file';
                $entry = [
                    'id'       => preg_match('/^[a-z0-9_-]{1,40}$/i', (string)($m['id'] ?? '')) ? (string)$m['id'] : 'med_' . substr(bin2hex(random_bytes(6)), 0, 10),
                    'kind'     => $kind,
                    'url'      => mb_substr($url, 0, 5_000_000),       // 5MB cap on a single field
                    'label'    => mb_substr($label, 0, 120),
                    'desc'     => mb_substr(trim((string)($m['desc'] ?? '')), 0, 400),
                    'showcase' => !empty($m['showcase']),
                    'filename' => mb_substr(trim((string)($m['filename'] ?? '')), 0, 200),
                    'mime'     => mb_substr(trim((string)($m['mime']     ?? '')), 0, 100),
                ];
                $out[] = $entry;
                if (count($out) >= 30) break;   // sanity cap per product
            }
            return $out;
        };
        // Only write media when the key is present — old clients that don't
        // send it should not wipe an operator's media library on update.
        $mediaJson = array_key_exists('media', $d) ? json_encode($sanitiseMedia($d['media']), JSON_UNESCAPED_SLASHES) : null;
        // Post-payment delivery text. NULL when key absent so an old client
        // doesn't blank an operator's existing message on update. Capped at
        // 4000 chars (long enough for a paragraph + credentials block).
        $postPaymentText = array_key_exists('postPaymentText', $d)
            ? mb_substr((string)$d['postPaymentText'], 0, 4000)
            : null;
        $manualTasksJson = null;
        if (array_key_exists('manualTasks', $d)) {
            $mt = is_array($d['manualTasks']) ? $d['manualTasks'] : [];
            $mtClean = [];
            foreach ($mt as $t) {
                $t = trim((string)$t);
                if ($t !== '') { $mtClean[] = mb_substr($t, 0, 200); }
                if (count($mtClean) >= 20) break;
            }
            $manualTasksJson = json_encode($mtClean, JSON_UNESCAPED_SLASHES);
        }
        // Stock-list settings (the items have their own actions). Written only
        // when the key is sent, like every other column here.
        $applyStock = function (int $productId) use ($pdo, $ACCOUNT_ID, $d) {
            if ($productId <= 0 || !bc_has_col($pdo, 'bc_products', 'stock_mode')) return;
            $set = []; $args = [];
            if (array_key_exists('stockMode', $d))      { $set[] = 'stock_mode=?';  $args[] = (int)!!$d['stockMode']; }
            if (array_key_exists('stockLabel', $d))     { $set[] = 'stock_label=?'; $args[] = mb_substr(trim(preg_replace('/\s+/u', ' ', (string)$d['stockLabel'])), 0, 40); }
            if (array_key_exists('stockWhenEmpty', $d)) { $set[] = 'stock_empty=?'; $args[] = ((string)$d['stockWhenEmpty'] === 'hold') ? 'hold' : 'hide'; }
            if (!$set) return;
            $args[] = $productId; $args[] = $ACCOUNT_ID;
            $pdo->prepare("UPDATE bc_products SET " . implode(', ', $set) . " WHERE id=? AND account_id=?")->execute($args);
        };
        if ($hasId) {
            $stmt = $pdo->prepare("
                UPDATE bc_products SET
                    -- ROOT CAUSE OF THE BLANK-NAME BUG.
                    -- These eleven columns were previously assigned
                    -- unconditionally, binding an empty string whenever the
                    -- key was absent, so ANY caller sending a partial payload wiped
                    -- every field it didn't mention. The product editor always
                    -- posts the complete form, which is why this never showed
                    -- up in normal use — but the ghost's product_update
                    -- deliberately sends only changed keys, so a lone
                    -- description edit blanked the name, sku, price, billing,
                    -- stock, expiry, image, features and bundle contents, and
                    -- reset the type to 'prod' (silently demoting a package).
                    --
                    -- COALESCE makes absent (NULL) mean leave-it-alone, while
                    -- an explicitly-sent empty string still clears the field,
                    -- so deliberate clearing from the editor keeps working.
                    -- The allow_* / media / post_payment_text columns below
                    -- already did this; the older columns had been missed.
                    type=COALESCE(:type, type),
                    name=COALESCE(:name, name),
                    sku=COALESCE(:sku, sku),
                    price=COALESCE(:price, price),
                    price_currency=COALESCE(:pcur, price_currency),
                    billing=COALESCE(:billing, billing),
                    stock=COALESCE(:stock, stock),
                    expiry=COALESCE(:expiry, expiry),
                    img=COALESCE(:img, img),
                    description=COALESCE(:desc, description),
                    feats=COALESCE(:feats, feats),
                    products=COALESCE(:products, products),
                    enabled_for_ai=COALESCE(:eai, enabled_for_ai),
                    allow_username         = COALESCE(:au, allow_username),
                    allow_serial           = COALESCE(:as, allow_serial),
                    allow_account_creation = COALESCE(:ac, allow_account_creation),
                    allow_refund           = COALESCE(:ar, allow_refund),
                    allow_mailing_site     = COALESCE(:ams, allow_mailing_site),
                    media                  = COALESCE(:media, media),
                    post_payment_text      = COALESCE(:ppt, post_payment_text),
                    manual_tasks           = COALESCE(:mt, manual_tasks)
                WHERE id=:id AND account_id=:aid
            ");
            $stmt->execute([
                ':id'       => (int)$d['id'],
                ':aid'      => $ACCOUNT_ID,
                // array_key_exists (not ??) so an explicit '' still writes —
                // only a genuinely absent key becomes NULL / "leave alone".
                ':type'     => array_key_exists('type',    $d) ? $d['type']    : null,
                ':name'     => array_key_exists('name',    $d) ? $d['name']    : null,
                ':sku'      => array_key_exists('sku',     $d) ? $d['sku']     : null,
                ':price'    => array_key_exists('price',   $d) ? $d['price']   : null,
                ':pcur'     => $priceCurrency,
                ':billing'  => array_key_exists('billing', $d) ? $d['billing'] : null,
                ':stock'    => array_key_exists('stock',   $d) ? $d['stock']   : null,
                ':expiry'   => array_key_exists('expiry',  $d) ? $d['expiry']  : null,
                ':img'      => array_key_exists('img',     $d) ? $d['img']     : null,
                ':desc'     => array_key_exists('desc',    $d) ? $d['desc']    : null,
                ':feats'    => $featsJson,
                ':products' => $productsJson,
                ':eai'      => $enabledForAiRaw,
                ':au'       => $allowUsername,
                ':as'       => $allowSerial,
                ':ac'       => $allowAcctCreate,
                ':ar'       => $allowRefund,
                ':ams'      => $allowMailingSite,
                ':media'    => $mediaJson,
                ':ppt'      => $postPaymentText,
                ':mt'       => $manualTasksJson,
            ]);
            $applyStock((int)$d['id']);
            ok(['id' => (int)$d['id']]);
        } else {
            $stmt = $pdo->prepare("
                INSERT INTO bc_products (account_id,type,name,sku,price,price_currency,billing,stock,expiry,img,description,feats,products,enabled_for_ai,allow_username,allow_serial,allow_account_creation,allow_refund,allow_mailing_site,media,post_payment_text,manual_tasks)
                VALUES (:aid,:type,:name,:sku,:price,:pcur,:billing,:stock,:expiry,:img,:desc,:feats,:products,:eai,:au,:as,:ac,:ar,:ams,:media,:ppt,:mt)
            ");
            $stmt->execute([
                ':aid'      => $ACCOUNT_ID,
                ':type'     => $d['type']     ?? 'prod',
                ':name'     => $d['name']     ?? '',
                ':sku'      => $d['sku']      ?? '',
                ':price'    => $d['price']    ?? '',
                ':pcur'     => $priceCurrency ?? 'USD',
                ':billing'  => $d['billing']  ?? '',
                ':stock'    => $d['stock']    ?? '∞',
                ':expiry'   => $d['expiry']   ?? '',
                ':img'      => $d['img']      ?? '',
                ':desc'     => $d['desc']     ?? '',
                ':feats'    => $featsJson    ?? '[]',
                ':products' => $productsJson ?? '[]',
                ':eai'      => $enabledForAi,
                ':au'       => (int)!!$allowUsername,
                ':as'       => (int)!!$allowSerial,
                ':ac'       => (int)!!$allowAcctCreate,
                // New items are non-refundable unless the operator turns refunds on.
                ':ar'       => $allowRefund === null ? 0 : (int)$allowRefund,
                ':ams'      => $allowMailingSite === null ? 0 : (int)$allowMailingSite,
                ':media'    => $mediaJson ?? json_encode([]),
                ':ppt'      => $postPaymentText ?? '',
                ':mt'       => $manualTasksJson ?? json_encode([]),
            ]);
            $newId = (int)$pdo->lastInsertId();
            $applyStock($newId);
            ok(['id' => $newId]);
        }

    case 'set_product_enabled':
        // Quick toggle for the AI-availability flag from the products UI.
        if (empty($body['id'])) err('id required');
        $pid = (int)$body['id'];
        own_product($pdo, $ACCOUNT_ID, $pid);
        $on = !empty($body['on']) ? 1 : 0;
        $pdo->prepare("UPDATE bc_products SET enabled_for_ai=? WHERE id=? AND account_id=?")
            ->execute([$on, $pid, $ACCOUNT_ID]);
        ok(['on' => $on]);

    case 'delete_product':
        if (!isset($body['id'])) err('id required');
        $pid = (int)$body['id'];
        own_product($pdo, $ACCOUNT_ID, $pid);
        $pdo->prepare("DELETE FROM bc_products WHERE id=? AND account_id=?")->execute([$pid, $ACCOUNT_ID]);
        // Unsold items go with the product; given-out ones stay as the record
        // of who received what.
        if (stock_ready($pdo)) {
            try { $pdo->prepare("DELETE FROM bc_product_stock WHERE account_id=? AND product_id=? AND status='available'")->execute([$ACCOUNT_ID, $pid]); }
            catch (\Throwable $e) { error_log('[stock] cleanup on delete failed: ' . $e->getMessage()); }
        }
        ok();

    // ── STOCK LISTS ──────────────────────────────────────────
    // The catalogue's "Keys and codes" list. Items never travel with
    // get_products / save_product: they are added, listed and removed here,
    // and handed out only by stock_claim_for_tx.
    case 'stock_list': {
        $pid = (int)($body['product_id'] ?? 0);
        if ($pid <= 0) err('product_id required');
        own_product($pdo, $ACCOUNT_ID, $pid);
        if (!stock_ready($pdo)) ok(['items' => [], 'counts' => stock_zero(), 'unavailable' => true]);
        $q = $pdo->prepare("SELECT s.id, s.item, s.status, s.notify, s.tx_id, s.created_at, s.assigned_at,
                                   eu.name AS cname, eu.handle AS chandle, eu.conv_id AS conv_id
                              FROM bc_product_stock s
                              LEFT JOIN bc_end_users eu ON eu.id = s.end_user_id AND eu.account_id = s.account_id
                             WHERE s.account_id=? AND s.product_id=?
                             ORDER BY s.id ASC LIMIT 20000");
        $q->execute([$ACCOUNT_ID, $pid]);
        $items = [];
        foreach ($q->fetchAll() as $r) {
            $name = trim((string)($r['cname'] ?? ''));
            $items[] = [
                'id'       => (int)$r['id'],
                'item'     => (string)$r['item'],
                'status'   => (string)$r['status'],
                'unsent'   => (int)$r['notify'] === 1,
                'tx_id'    => $r['tx_id'] !== null ? (int)$r['tx_id'] : null,
                'added'    => $r['created_at'],
                'at'       => $r['assigned_at'],
                'customer' => $name,
                'handle'   => bc_handle_display($r['chandle'] ?? '', ''),
                'conv_id'  => (string)($r['conv_id'] ?? ''),
            ];
        }
        ok(['items' => $items, 'counts' => stock_counts($pdo, (int)$ACCOUNT_ID, $pid)[$pid] ?? stock_zero()]);
    }

    case 'stock_add': {
        $pid = (int)($body['product_id'] ?? 0);
        if ($pid <= 0) err('product_id required');
        own_product($pdo, $ACCOUNT_ID, $pid);
        if (!stock_ready($pdo)) err('Stock lists are not available yet: the database table could not be created. Check migrate.log on the server.');
        $raw = $body['items'] ?? [];
        if (!is_array($raw)) err('items must be a list');
        if (count($raw) > 5000) err('Add up to 5,000 items at a time.');
        $clean = []; $seen = []; $repeated = 0; $tooLong = 0;
        foreach ($raw as $it) {
            if (!is_scalar($it)) continue;
            $s = stock_clean_item((string)$it);
            if ($s === '') continue;
            if (mb_strlen($s) > 2000) { $tooLong++; continue; }
            $h = stock_hash_item($s);
            if (isset($seen[$h])) { $repeated++; continue; }
            $seen[$h] = true;
            $clean[$h] = $s;
        }
        // Which of these the list already has, and which were already given
        // out (those can never be added back: that would sell them twice).
        $inList = 0; $wasGiven = 0;
        foreach (array_chunk(array_keys($clean), 400) as $hs) {
            $ph = implode(',', array_fill(0, count($hs), '?'));
            $ex = $pdo->prepare("SELECT item_hash, status FROM bc_product_stock WHERE account_id=? AND product_id=? AND item_hash IN ($ph)");
            $ex->execute(array_merge([$ACCOUNT_ID, $pid], $hs));
            foreach ($ex->fetchAll() as $x) {
                if (($x['status'] ?? '') === 'given') $wasGiven++; else $inList++;
                unset($clean[(string)$x['item_hash']]);
            }
        }
        $cur = $pdo->prepare("SELECT COUNT(*) FROM bc_product_stock WHERE account_id=? AND product_id=?");
        $cur->execute([$ACCOUNT_ID, $pid]);
        if ((int)$cur->fetchColumn() + count($clean) > 20000) err('A list holds up to 20,000 items. Remove some, or split them across products.');
        $added = 0;
        foreach (array_chunk($clean, 200, true) as $chunk) {
            $vals = []; $args = [];
            foreach ($chunk as $h => $s) { $vals[] = "(?,?,?,?,'available')"; array_push($args, $ACCOUNT_ID, $pid, $s, $h); }
            $st = $pdo->prepare("INSERT IGNORE INTO bc_product_stock (account_id, product_id, item, item_hash, status) VALUES " . implode(',', $vals));
            $st->execute($args);
            $added += $st->rowCount();
        }
        $counts = stock_counts($pdo, (int)$ACCOUNT_ID, $pid)[$pid] ?? stock_zero();
        ok(['added' => $added, 'in_list' => $inList, 'given' => $wasGiven, 'repeated' => $repeated, 'too_long' => $tooLong, 'counts' => $counts]);
    }

    case 'stock_remove': {
        $pid = (int)($body['product_id'] ?? 0);
        if ($pid <= 0) err('product_id required');
        own_product($pdo, $ACCOUNT_ID, $pid);
        if (!stock_ready($pdo)) ok(['removed' => 0, 'counts' => stock_zero()]);
        // Only items nobody has received can be removed.
        if (!empty($body['all'])) {
            $st = $pdo->prepare("DELETE FROM bc_product_stock WHERE account_id=? AND product_id=? AND status='available'");
            $st->execute([$ACCOUNT_ID, $pid]);
        } else {
            $ids = array_values(array_filter(array_map('intval', (array)($body['ids'] ?? [])), fn($v) => $v > 0));
            if (!$ids) err('ids required');
            $ids = array_slice($ids, 0, 5000);
            $ph = implode(',', array_fill(0, count($ids), '?'));
            $st = $pdo->prepare("DELETE FROM bc_product_stock WHERE account_id=? AND product_id=? AND status='available' AND id IN ($ph)");
            $st->execute(array_merge([$ACCOUNT_ID, $pid], $ids));
        }
        ok(['removed' => $st->rowCount(), 'counts' => stock_counts($pdo, (int)$ACCOUNT_ID, $pid)[$pid] ?? stock_zero()]);
    }

    // Customers who paid while the list was empty: fill their items from the
    // list (oldest payment first) and return every item that still has to be
    // sent, so the app can message them. stock_mark_sent closes each one.
    case 'stock_fulfil_owed': {
        $pid = (int)($body['product_id'] ?? 0);
        if ($pid <= 0) err('product_id required');
        own_product($pdo, $ACCOUNT_ID, $pid);
        if (!stock_ready($pdo)) ok(['send' => [], 'filled' => 0, 'counts' => stock_zero()]);
        $oq = $pdo->prepare("SELECT * FROM bc_product_stock WHERE account_id=? AND product_id=? AND status='owed' ORDER BY id ASC LIMIT 500");
        $oq->execute([$ACCOUNT_ID, $pid]);
        $filled = 0;
        foreach ($oq->fetchAll() as $row) {
            if (stock_fill_owed($pdo, (int)$ACCOUNT_ID, $row, 1) === null) break;
            $filled++;
        }
        $sq = $pdo->prepare("SELECT s.id, s.item, s.tx_id, s.product_id, s.license_id, p.name AS pname, p.stock_label, p.allow_serial,
                                    eu.name AS cname, eu.conv_id AS conv_id
                               FROM bc_product_stock s
                               JOIN bc_products p ON p.id = s.product_id AND p.account_id = s.account_id
                               LEFT JOIN bc_end_users eu ON eu.id = s.end_user_id AND eu.account_id = s.account_id
                              WHERE s.account_id=? AND s.product_id=? AND s.status='given' AND s.notify=1
                              ORDER BY s.id ASC LIMIT 500");
        $sq->execute([$ACCOUNT_ID, $pid]);
        $send = [];
        foreach ($sq->fetchAll() as $r) {
            $send[] = ['id' => (int)$r['id'], 'item' => (string)$r['item'], 'tx_id' => (int)$r['tx_id'],
                       'product' => (string)$r['pname'], 'label' => stock_label_of($r),
                       'customer' => trim((string)($r['cname'] ?? '')), 'conv_id' => (string)($r['conv_id'] ?? ''),
                       'text' => stock_backorder_text($pdo, (int)$ACCOUNT_ID, $r)];
        }
        ok(['send' => $send, 'filled' => $filled, 'counts' => stock_counts($pdo, (int)$ACCOUNT_ID, $pid)[$pid] ?? stock_zero()]);
    }

    case 'stock_mark_sent': {
        $ids = array_values(array_filter(array_map('intval', (array)($body['ids'] ?? [])), fn($v) => $v > 0));
        if (!$ids || !stock_ready($pdo)) ok(['updated' => 0]);
        $ids = array_slice($ids, 0, 500);
        $ph = implode(',', array_fill(0, count($ids), '?'));
        $st = $pdo->prepare("UPDATE bc_product_stock SET notify=0 WHERE account_id=? AND status='given' AND id IN ($ph)");
        $st->execute(array_merge([$ACCOUNT_ID], $ids));
        ok(['updated' => $st->rowCount()]);
    }

    // Keys and codes are not licences: what a sale took from a product's
    // "Keys and codes" list is recorded on the sale's INVOICE, so the
    // operator can see (and search) which customer received which item.
    // A payment's reference is the invoice id, or the invoice id plus
    // "#line.unit" for one unit of a multi-item invoice; both roll up to the
    // invoice. Optional invoice_ids narrows the answer to those invoices.
    // Returns {invoices: {<invoice id>: [{id, product_id, product, label,
    //   item, status: given|owed, pending_send, at, unit}]}}
    case 'get_invoice_keys': {
        if (!stock_ready($pdo)) ok(['invoices' => (object)[]]);
        $want = [];
        foreach ((array)($body['invoice_ids'] ?? []) as $v) {
            $v = trim((string)$v);
            if ($v !== '' && mb_strlen($v) <= 120) $want[$v] = true;
        }
        $want = array_slice(array_keys($want), 0, 500);
        $sql = "SELECT s.id, s.product_id, s.item, s.status, s.notify, s.assigned_at,
                       t.reference, p.name AS pname, p.stock_label, p.allow_serial
                  FROM bc_product_stock s
                  JOIN bc_end_user_transactions t ON t.id = s.tx_id AND t.account_id = s.account_id
                  LEFT JOIN bc_products p ON p.id = s.product_id AND p.account_id = s.account_id
                 WHERE s.account_id=? AND s.tx_id IS NOT NULL AND s.status IN ('given','owed')";
        $args = [$ACCOUNT_ID];
        if ($want) {
            $sql .= " AND SUBSTRING_INDEX(t.reference, '#', 1) IN (" . implode(',', array_fill(0, count($want), '?')) . ")";
            $args = array_merge($args, $want);
        }
        $sql .= " ORDER BY s.id DESC LIMIT 5000";
        $out = [];
        try {
            $q = $pdo->prepare($sql);
            $q->execute($args);
            foreach (array_reverse($q->fetchAll()) as $r) {
                $ref = (string)($r['reference'] ?? '');
                if ($ref === '') continue;
                $hash = strpos($ref, '#');
                $inv  = $hash === false ? $ref : substr($ref, 0, $hash);
                $unit = $hash === false ? '' : substr($ref, $hash);
                $given = ($r['status'] ?? '') === 'given' && (string)$r['item'] !== '';
                $out[$inv][] = [
                    'id'           => (int)$r['id'],
                    'product_id'   => (int)$r['product_id'],
                    'product'      => (string)($r['pname'] ?? ''),
                    'label'        => stock_label_of(['stock_label' => $r['stock_label'] ?? '', 'allow_serial' => $r['allow_serial'] ?? 0]),
                    'item'         => $given ? (string)$r['item'] : '',
                    'status'       => $given ? 'given' : 'owed',
                    // Filled after the list was topped up, but the customer
                    // hasn't been sent it yet (Send to waiting customers).
                    'pending_send' => $given && (int)$r['notify'] === 1,
                    'at'           => $r['assigned_at'],
                    'unit'         => $unit,
                ];
            }
        } catch (\Throwable $e) {
            error_log('[stock] invoice keys lookup failed: ' . $e->getMessage());
        }
        foreach ($out as &$list) {
            usort($list, fn($a, $b) => strnatcmp($a['unit'], $b['unit']) ?: ($a['id'] <=> $b['id']));
        }
        unset($list);
        ok(['invoices' => $out ? $out : (object)[]]);
    }

    // ── AGENTS ───────────────────────────────────────────────
    case 'get_agents':
        $rows = $pdo->prepare("SELECT * FROM bc_agents WHERE account_id=? ORDER BY id ASC");
        $rows->execute([$ACCOUNT_ID]);
        $rows = $rows->fetchAll();
        $out  = array_map(fn($r) => [
            'id'             => (int)$r['id'],
            'name'           => $r['name'],
            'model'          => $r['model'],
            'persona'        => $r['persona'],
            'tasks'          => $r['tasks']     ? json_decode($r['tasks'],     true) : [],
            'plat'           => $r['platforms'] ? json_decode($r['platforms'], true) : [],
            'active'         => (bool)$r['active'],
            'wpm'            => (int)$r['wpm'],
            'delay'          => $r['delay_mode'],
            'style'          => $r['style'],
            'tone'           => $r['tone'],
            'escalate'       => $r['escalate'],
            'emoji'          => (bool)$r['use_emoji'],
            'proactive'      => (bool)$r['proactive'],
            'autoReply'      => (bool)($r['auto_reply_default'] ?? 1),
            'typingIndicator'=> (bool)($r['typing_indicator']   ?? 1),
            'readReceipts'   => (bool)($r['read_receipts']      ?? 0),
            'readDelayMin'   => (int) ($r['read_delay_min']     ?? 2),
            'readDelayMax'   => (int) ($r['read_delay_max']     ?? 9),
            'msgGapMin'      => (int) ($r['msg_gap_min']        ?? 1),
            'msgGapMax'      => (int) ($r['msg_gap_max']        ?? 4),
            'replyPrivate'        => (bool)($r['reply_private']           ?? 1),
            'replyGroups'         => (bool)($r['reply_groups']            ?? 0),
            'replyChannels'       => (bool)($r['reply_channels']          ?? 0),
            'replyOnlyIfMentioned'=> (bool)($r['reply_only_if_mentioned'] ?? 1),
            'silenceMode'         => true,   // always on — switch retired
            'spamThrottle'        => (bool)($r['spam_throttle']           ?? 1),
            'spamCooldownSec'     => (int) ($r['spam_cooldown_sec']       ?? 60),
            // Realism v2 — schedule, imperfections, repetition guard.
            // schedule_json is decoded server-side so the FE doesn't need to
            // parse a string field. A null/missing column yields the safe
            // "always-on" default below (enabled:false).
            // Always returned in the v2 multi-block shape (windows[]), with
            // v1 rows converted on the way out.
            'schedule'            => (function($r){
                $raw = isset($r['schedule_json']) ? $r['schedule_json'] : null;
                $j = $raw ? json_decode($raw, true) : null;
                return agent_schedule_normalize(is_array($j) ? $j : null);
            })($r),
            'hesitationPct'       => (int) ($r['hesitation_pct']          ?? 0),
            'selfCorrectPct'      => (int) ($r['self_correct_pct']        ?? 0),
            'typoRate'            => (int) ($r['typo_rate']               ?? 0),
            'lowercaseDrift'      => (bool)($r['lowercase_drift']         ?? 0),
            'repetitionGuard'     => (bool)($r['repetition_guard']        ?? 1),
            'repetitionWindow'    => (int) ($r['repetition_window']       ?? 6),
            'waitForUserTyping'   => (bool)($r['wait_for_user_typing']    ?? 1),
            'identityMode'        => (function($m){ $m=(string)($m??'agent'); if($m==='name')$m='agent'; if($m==='handle')$m='self'; return in_array($m,['agent','self'],true)?$m:'agent'; })($r['identity_mode'] ?? 'agent'),
            'selfName'            => (string)($r['self_name'] ?? ''),
            'revealAi'            => (bool)($r['reveal_ai']               ?? 0),
            'sellCatalog'         => (bool)($r['sell_catalog']            ?? 1),
            'stopAfterSale'       => (bool)($r['stop_after_sale']         ?? 0),
            'stopAfterSaleMin'    => (int) ($r['stop_after_sale_min']     ?? 10),
            // Retired switches (see "RETIRED" near the migrations). Still
            // returned so older clients read a sensible value: licence
            // changes are always the operator's, invoice changes come with
            // selling.
            'allowAiLicenses'     => false,
            'allowAiInvoices'     => (bool)($r['sell_catalog']            ?? 1),
            // Missing column (very old install) reads as ON — the default.
            'allowAiRenewals'     => (bool)($r['allow_ai_renewals']       ?? 1),
            'allowScheduling'         => (bool)($r['allow_scheduling']          ?? 0),
            // Subset flag: never report it on without its parent, or the
            // editor shows a switch that does nothing.
            'allowCustomerScheduling' => (bool)($r['allow_scheduling'] ?? 0) && (bool)($r['allow_customer_scheduling'] ?? 0),
            'custSchedMaxPending'     => (int) ($r['cust_sched_max_pending']    ?? 3),
            'custSchedMaxPerDay'      => (int) ($r['cust_sched_max_per_day']    ?? 5),
            'custSchedMaxDays'        => (int) ($r['cust_sched_max_days']       ?? 60),
            'custSchedQuietHours'     => (bool)($r['cust_sched_quiet_hours']    ?? 1),
            'replies'        => (int)$r['replies'],
            'conv'           => (int)$r['conv'],
        ], $rows);
        ok(['agents' => $out]);

    case 'save_agent':
        $d = $body;
        if (empty($d['name'])) err('name required');
        $isNew = empty($d['id']);

        // Build the column list dynamically. The bc_agents table may be
        // missing some of the newer columns if the auto-migration failed
        // (e.g. limited DB privileges) — we still want agent saves to
        // succeed against whatever schema actually exists.
        // Map: column_name => [param_name, value]
        $candidates = array(
            'name'                    => array(':name',      $d['name']),
            'model'                   => array(':model',     isset($d['model'])    ? $d['model']    : 'gemini-2.5-flash'),
            'persona'                 => array(':persona',   isset($d['persona'])  ? $d['persona']  : ''),
            'tasks'                   => array(':tasks',     json_encode(isset($d['tasks']) ? $d['tasks'] : array())),
            'platforms'               => array(':plat',      json_encode(isset($d['plat'])  ? $d['plat']  : array())),
            'active'                  => array(':active',    (int)(isset($d['active'])    ? $d['active']    : 1)),
            'wpm'                     => array(':wpm',       (int)(isset($d['wpm'])       ? $d['wpm']       : 75)),
            'delay_mode'              => array(':delay',     isset($d['delay'])    ? $d['delay']    : 'natural'),
            'style'                   => array(':style',     isset($d['style'])    ? $d['style']    : 'human'),
            'tone'                    => array(':tone',      isset($d['tone'])     ? $d['tone']     : 'Friendly'),
            'escalate'                => array(':escalate',  isset($d['escalate']) ? $d['escalate'] : '3 failures'),
            'use_emoji'               => array(':emoji',     (int)(isset($d['emoji'])     ? $d['emoji']     : 1)),
            'proactive'               => array(':proactive', (int)(isset($d['proactive']) ? $d['proactive'] : 0)),
            'auto_reply_default'      => array(':autoReply', (int)(isset($d['autoReply'])       ? $d['autoReply']       : 1)),
            'typing_indicator'        => array(':typingInd', (int)(isset($d['typingIndicator']) ? $d['typingIndicator'] : 1)),
            'read_receipts'           => array(':readRec',   (int)(isset($d['readReceipts'])    ? $d['readReceipts']    : 0)),
            'read_delay_min'          => array(':rdMin',     (int)(isset($d['readDelayMin']) ? $d['readDelayMin'] : 2)),
            'read_delay_max'          => array(':rdMax',     (int)(isset($d['readDelayMax']) ? $d['readDelayMax'] : 9)),
            'msg_gap_min'             => array(':mgMin',     (int)(isset($d['msgGapMin'])    ? $d['msgGapMin']    : 1)),
            'msg_gap_max'             => array(':mgMax',     (int)(isset($d['msgGapMax'])    ? $d['msgGapMax']    : 4)),
            'reply_private'           => array(':rPriv',     (int)(isset($d['replyPrivate'])         ? $d['replyPrivate']         : 1)),
            'reply_groups'            => array(':rGrp',      (int)(isset($d['replyGroups'])          ? $d['replyGroups']          : 0)),
            'reply_channels'          => array(':rChan',     (int)(isset($d['replyChannels'])        ? $d['replyChannels']        : 0)),
            'reply_only_if_mentioned' => array(':rMention',  (int)(isset($d['replyOnlyIfMentioned']) ? $d['replyOnlyIfMentioned'] : 1)),
            'silence_mode'            => array(':sMode',     1),   // always on — switch retired
            'spam_throttle'           => array(':sThr',      (int)(isset($d['spamThrottle'])        ? $d['spamThrottle']        : 1)),
            'spam_cooldown_sec'       => array(':sCool',     (int)(isset($d['spamCooldownSec'])     ? max(5, min(1800, (int)$d['spamCooldownSec'])) : 60)),
            // Reply hours. schedule arrives as a structured object from the FE;
            // re-encoded here (not blind-passthrough) to strip unknown keys and
            // clamp ranges. v2 stores every block in windows[] — the old encoder
            // kept only days/startMin/endMin, which would have silently dropped
            // every block after the first. startMin/endMin are minutes since
            // midnight (0..1439), days are weekday ints (0=Sun..6=Sat).
            'schedule_json'           => array(':schJson',   (function($d){
                $s = isset($d['schedule']) && is_array($d['schedule']) ? $d['schedule'] : null;
                if (!$s) return null;
                return json_encode(agent_schedule_normalize($s));
            })($d)),
            'hesitation_pct'          => array(':hesPct',    max(0, min(100, (int)(isset($d['hesitationPct'])    ? $d['hesitationPct']    : 0)))),
            'self_correct_pct'        => array(':scPct',     max(0, min(100, (int)(isset($d['selfCorrectPct'])   ? $d['selfCorrectPct']   : 0)))),
            'typo_rate'               => array(':typoR',     max(0, min(100, (int)(isset($d['typoRate'])         ? $d['typoRate']         : 0)))),
            'lowercase_drift'         => array(':lcDrift',   (int)(isset($d['lowercaseDrift'])    ? $d['lowercaseDrift']    : 0)),
            'repetition_guard'        => array(':repG',      (int)(isset($d['repetitionGuard'])   ? $d['repetitionGuard']   : 1)),
            'repetition_window'       => array(':repW',      max(2, min(20, (int)(isset($d['repetitionWindow'])  ? $d['repetitionWindow']  : 6)))),
            'wait_for_user_typing'    => array(':waitTyp',   (int)(isset($d['waitForUserTyping']) ? $d['waitForUserTyping'] : 1)),
            'identity_mode'           => array(':identMode', (function($m){ $m=(string)($m??'agent'); if($m==='name')$m='agent'; if($m==='handle')$m='self'; return in_array($m,['agent','self'],true)?$m:'agent'; })($d['identityMode'] ?? 'agent')),
            'self_name'               => array(':selfName',  mb_substr(trim((string)($d['selfName'] ?? '')), 0, 200)),
            'reveal_ai'               => array(':revealAi',  (int)(!empty($d['revealAi']))),
            // Absent means "sells" so an older client never switches it off.
            'sell_catalog'            => array(':sellCat',   (int)(!isset($d['sellCatalog']) || !empty($d['sellCatalog']))),
            'stop_after_sale'         => array(':stopSale',  (int)(isset($d['stopAfterSale'])    ? $d['stopAfterSale']    : 0)),
            'stop_after_sale_min'     => array(':stopSaleM', max(0, min(1440, (int)(isset($d['stopAfterSaleMin']) ? $d['stopAfterSaleMin'] : 10)))),
            // Retired switches — written from the server's own rule, never
            // from the client, so a stale page can't switch them back on.
            'allow_ai_licenses'       => array(':allowLic',  0),
            'allow_ai_invoices'       => array(':allowInv',  (int)(!isset($d['sellCatalog']) || !empty($d['sellCatalog']))),
            // Absent means ON so an older client (or a ghost-built payload
            // that never heard of it) can't switch renewals off by accident.
            'allow_ai_renewals'       => array(':allowRen',  (int)(!array_key_exists('allowAiRenewals', $d) || !empty($d['allowAiRenewals']))),
            // Deferred actions. The customer flag is ANDed with its parent
            // here too: a client that posts allow_customer_scheduling=1 with
            // allow_scheduling=0 must not end up with a live customer
            // surface on an agent the operator believes is not scheduling.
            'allow_scheduling'          => array(':allowSch',  (int)(!empty($d['allowScheduling']))),
            'allow_customer_scheduling' => array(':allowCSch', (int)(!empty($d['allowScheduling']) && !empty($d['allowCustomerScheduling']))),
            'cust_sched_max_pending'    => array(':csMaxP',    max(0, min(10,  (int)(isset($d['custSchedMaxPending']) ? $d['custSchedMaxPending'] : 3)))),
            'cust_sched_max_per_day'    => array(':csMaxD',    max(0, min(20,  (int)(isset($d['custSchedMaxPerDay'])  ? $d['custSchedMaxPerDay']  : 5)))),
            'cust_sched_max_days'       => array(':csMaxDays', max(1, min(365, (int)(isset($d['custSchedMaxDays'])    ? $d['custSchedMaxDays']    : 60)))),
            'cust_sched_quiet_hours'    => array(':csQuiet',   (int)(!isset($d['custSchedQuietHours']) || !empty($d['custSchedQuietHours']))),
        );
        $cols = array(); $params = array();
        foreach ($candidates as $colName => $pair) {
            if (col_exists($pdo, 'bc_agents', $colName)) {
                $cols[$colName] = $pair[0];
                $params[$pair[0]] = $pair[1];
            }
        }
        if ($isNew) {
            // Stamp the owning account on every new agent. Operators NEVER
            // create agents that belong to another account.
            if (col_exists($pdo,'bc_agents','account_id')) {
                $cols['account_id'] = ':accId'; $params[':accId'] = $ACCOUNT_ID;
            }
            if (col_exists($pdo,'bc_agents','replies')) {
                $cols['replies'] = ':replies'; $params[':replies'] = (int)(isset($d['replies']) ? $d['replies'] : 0);
            }
            if (col_exists($pdo,'bc_agents','conv')) {
                $cols['conv'] = ':conv'; $params[':conv'] = (int)(isset($d['conv']) ? $d['conv'] : 0);
            }
            $colList = implode(',', array_keys($cols));
            $phList  = implode(',', array_values($cols));
            $sql = "INSERT INTO bc_agents ($colList) VALUES ($phList)";
        } else {
            // Verify ownership before allowing the update — a hostile client
            // could otherwise send id=<other operator's id> and rewrite their
            // agent. We re-query rather than trust an ownership claim in body.
            own_agent($pdo, $ACCOUNT_ID, (int)$d['id']);
            $sets = array();
            foreach ($cols as $col => $ph) $sets[] = "$col=$ph";
            $sql = "UPDATE bc_agents SET ".implode(',', $sets)." WHERE id=:id AND account_id=:accId";
            $params[':id']    = (int)$d['id'];
            $params[':accId'] = $ACCOUNT_ID;
        }
        $stmt = $pdo->prepare($sql);
        $stmt->execute($params);
        $newId = $isNew ? (int)$pdo->lastInsertId() : (int)$d['id'];
        ok(['id' => $newId]);

    case 'delete_agent':
        if (empty($body['id'])) err('id required');
        $aid = (int)$body['id'];
        own_agent($pdo, $ACCOUNT_ID, $aid);
        $pdo->prepare("DELETE FROM bc_agents WHERE id=? AND account_id=?")->execute([$aid, $ACCOUNT_ID]);
        // Detach any conversations that pointed at this agent so reply lookups
        // can fall back to the next active agent. Scoped to this account.
        $pdo->prepare("UPDATE bc_conversations SET agent_id=NULL WHERE agent_id=? AND account_id=?")
            ->execute([$aid, $ACCOUNT_ID]);
        ok();

    // ── CREDENTIALS ──────────────────────────────────────────
    // Known keys: tg_bot_token, tg_api_id, tg_api_hash, tg_phone, tg_session,
    // dc_bot_token, llm_gemini, llm_openai, llm_claude, llm_active.
    case 'get_credentials':
        $rows = $pdo->prepare("SELECT * FROM bc_credentials WHERE account_id=?");
        $rows->execute([$ACCOUNT_ID]);
        $out = [];
        foreach ($rows->fetchAll() as $r) {
            $out[$r['key']] = [
                'value' => $r['value'],
                'meta'  => $r['meta'] ? json_decode($r['meta'], true) : null,
                'updated_at' => $r['updated_at'],
            ];
        }
        ok(['credentials' => $out]);

    case 'save_credential':
        if (empty($body['key'])) err('key required');
        // Invoices on direct chats are minted and watched by the server; the
        // browser's copy of the list must not overwrite them.
        if ($body['key'] === 'payments_invoices' && isset($body['meta']) && is_array($body['meta'])) {
            try {
                $pdo->beginTransaction();
                $lk = $pdo->prepare("SELECT 1 FROM bc_credentials WHERE account_id=? AND `key`='payments_invoices' FOR UPDATE");
                $lk->execute([$ACCOUNT_ID]);
                $exists = (bool)$lk->fetchColumn();
                $body['meta'] = array_values(array_slice(dm_shop_merge_browser_list($pdo, (int)$ACCOUNT_ID, array_values($body['meta'])), 0, 500));
                if ($exists) {
                    $pdo->prepare("UPDATE bc_credentials SET value=?, meta=? WHERE account_id=? AND `key`='payments_invoices'")
                        ->execute([$body['value'] ?? '1', json_encode($body['meta']), $ACCOUNT_ID]);
                    $pdo->commit();
                    ok();
                }
                $pdo->commit();
            } catch (Throwable $e) {
                if ($pdo->inTransaction()) $pdo->rollBack();
                error_log('[save_credential] invoice merge failed: ' . $e->getMessage());
            }
        }
        // Composite-key upsert. We rely on the (account_id, key) UNIQUE index
        // added by migration; falls back to manual SELECT-then-UPDATE/INSERT
        // if the index is missing (very old install without the migration).
        $hasComposite = (bool)$pdo->query("SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='bc_credentials' AND INDEX_NAME='uniq_acc_key'")->fetchColumn();
        if ($hasComposite) {
            $stmt = $pdo->prepare("
                INSERT INTO bc_credentials (account_id, `key`, value, meta) VALUES (:a, :k, :v, :m)
                ON DUPLICATE KEY UPDATE value=VALUES(value), meta=VALUES(meta)
            ");
            $stmt->execute([
                ':a' => $ACCOUNT_ID,
                ':k' => $body['key'],
                ':v' => $body['value'] ?? '',
                ':m' => isset($body['meta']) ? json_encode($body['meta']) : null,
            ]);
        } else {
            $sel = $pdo->prepare("SELECT 1 FROM bc_credentials WHERE account_id=? AND `key`=?");
            $sel->execute([$ACCOUNT_ID, $body['key']]);
            if ($sel->fetchColumn()) {
                $pdo->prepare("UPDATE bc_credentials SET value=?, meta=? WHERE account_id=? AND `key`=?")
                    ->execute([$body['value'] ?? '', isset($body['meta']) ? json_encode($body['meta']) : null, $ACCOUNT_ID, $body['key']]);
            } else {
                $pdo->prepare("INSERT INTO bc_credentials (account_id, `key`, value, meta) VALUES (?,?,?,?)")
                    ->execute([$ACCOUNT_ID, $body['key'], $body['value'] ?? '', isset($body['meta']) ? json_encode($body['meta']) : null]);
            }
        }
        // A bot token saved (or the saved accounts changed): clear a stale
        // "No bot token saved." so Settings and the admin console are right.
        if (in_array($body['key'], ['tg_bot_token', 'dc_bot_token', 'platform_accounts'], true)) {
            bot_relay_token_saved($pdo, (int)$ACCOUNT_ID, $body['key'] === 'tg_bot_token' ? 'telegram' : ($body['key'] === 'dc_bot_token' ? 'discord' : null));
        }
        // Auto-promote the first LLM key entered to "active" so the user
        // doesn't have to also click the picker for things to work. Scoped
        // to THIS account so promoting one operator's key doesn't leak.
        $llmKeys = ['llm_gemini'=>'gemini', 'llm_openai'=>'openai', 'llm_claude'=>'claude'];
        if (isset($llmKeys[$body['key']]) && !empty($body['value'])) {
            $hasActive = $pdo->prepare("SELECT value FROM bc_credentials WHERE `key`='llm_active' AND account_id=? AND value<>''");
            $hasActive->execute([$ACCOUNT_ID]);
            if (!$hasActive->fetchColumn()) {
                if ($hasComposite) {
                    $pdo->prepare("INSERT INTO bc_credentials (account_id, `key`, value) VALUES (?, 'llm_active', ?)
                                   ON DUPLICATE KEY UPDATE value=VALUES(value)")
                        ->execute([$ACCOUNT_ID, $llmKeys[$body['key']]]);
                } else {
                    $pdo->prepare("INSERT INTO bc_credentials (account_id, `key`, value) VALUES (?, 'llm_active', ?)")
                        ->execute([$ACCOUNT_ID, $llmKeys[$body['key']]]);
                }
            }
        }
        ok();

    case 'delete_credential':
        if (empty($body['key'])) err('key required');
        $pdo->prepare("DELETE FROM bc_credentials WHERE `key`=? AND account_id=?")
            ->execute([$body['key'], $ACCOUNT_ID]);
        ok();

    case 'set_active_llm':
        // Accepted values: gemini | openai | claude | builtin (the site's
        // own AI, only while the administrator has it switched on)
        $which = strtolower($body['provider'] ?? '');
        if (!in_array($which, ['gemini','openai','claude','builtin'], true)) err('provider must be gemini|openai|claude|builtin');
        if ($which === 'builtin' && !llm_builtin()) err('The built-in AI isn’t available right now. Add a key of your own instead.');
        $hasComposite = (bool)$pdo->query("SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='bc_credentials' AND INDEX_NAME='uniq_acc_key'")->fetchColumn();
        if ($hasComposite) {
            $pdo->prepare("INSERT INTO bc_credentials (account_id, `key`, value) VALUES (?, 'llm_active', ?)
                           ON DUPLICATE KEY UPDATE value=VALUES(value)")
                ->execute([$ACCOUNT_ID, $which]);
        } else {
            $pdo->prepare("DELETE FROM bc_credentials WHERE `key`='llm_active' AND account_id=?")->execute([$ACCOUNT_ID]);
            $pdo->prepare("INSERT INTO bc_credentials (account_id, `key`, value) VALUES (?, 'llm_active', ?)")->execute([$ACCOUNT_ID, $which]);
        }
        ok(['provider'=>$which]);

    case 'set_llm_model':
        // Persist the model string the dashboard ghost (and other LLM
        // call-sites) should use for a given provider. One row per
        // (account, provider) — keys: llm_gemini_model | llm_openai_model
        // | llm_claude_model. Values are validated against a whitelist
        // so an LLM-issued curl can't pivot us onto an unknown model.
        $prov  = strtolower($body['provider'] ?? '');
        $model = trim((string)($body['model'] ?? ''));
        if (!in_array($prov, ['gemini','openai','claude'], true)) err('provider must be gemini|openai|claude');
        $allowed = llm_allowed_models($prov);
        if (!in_array($model, $allowed, true)) err('unknown model for ' . $prov);
        $credKey = 'llm_' . $prov . '_model';
        $hasComposite = (bool)$pdo->query("SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='bc_credentials' AND INDEX_NAME='uniq_acc_key'")->fetchColumn();
        if ($hasComposite) {
            $pdo->prepare("INSERT INTO bc_credentials (account_id, `key`, value) VALUES (?, ?, ?)
                           ON DUPLICATE KEY UPDATE value=VALUES(value)")
                ->execute([$ACCOUNT_ID, $credKey, $model]);
        } else {
            $pdo->prepare("DELETE FROM bc_credentials WHERE `key`=? AND account_id=?")->execute([$credKey, $ACCOUNT_ID]);
            $pdo->prepare("INSERT INTO bc_credentials (account_id, `key`, value) VALUES (?, ?, ?)")->execute([$ACCOUNT_ID, $credKey, $model]);
        }
        ok(['provider'=>$prov, 'model'=>$model]);

    case 'get_llm_models':
        // Returns the catalog of supported models per provider plus the
        // currently-selected model (if any) for this account. The UI
        // builds the dropdown from this so the source of truth is
        // server-side and stays in sync if the catalog is updated.
        $row = $pdo->prepare("SELECT `key`, value FROM bc_credentials WHERE account_id=? AND `key` IN ('llm_gemini_model','llm_openai_model','llm_claude_model')");
        $row->execute([$ACCOUNT_ID]);
        $sel = ['gemini'=>'', 'openai'=>'', 'claude'=>''];
        foreach ($row->fetchAll(PDO::FETCH_ASSOC) as $r) {
            if ($r['key'] === 'llm_gemini_model') $sel['gemini'] = (string)$r['value'];
            if ($r['key'] === 'llm_openai_model') $sel['openai'] = (string)$r['value'];
            if ($r['key'] === 'llm_claude_model') $sel['claude'] = (string)$r['value'];
        }
        ok([
            'catalog' => llm_model_catalog(),
            'selected' => $sel,
            'defaults' => [
                'gemini' => llm_default_model('gemini'),
                'openai' => llm_default_model('openai'),
                'claude' => llm_default_model('claude'),
            ],
            // The site's own AI (admin.php): whether it can be chosen, and its model.
            'builtin' => llm_builtin_public(),
        ]);

    // ── MEMORY (per-conversation JSON) ───────────────────────
    case 'ai_memory_get':
        $convId = $_GET['conv_id'] ?? $body['conv_id'] ?? '';
        if (!$convId) err('conv_id required');
        own_conv($pdo, $ACCOUNT_ID, $convId);
        ok(['memory' => mem_load($convId)]);

    case 'ai_memory_save':
        $convId = $body['conv_id'] ?? '';
        if (!$convId) err('conv_id required');
        own_conv($pdo, $ACCOUNT_ID, $convId);
        $patch  = is_array($body['patch'] ?? null) ? $body['patch'] : [];
        $mem = mem_merge(mem_load($convId), $patch);
        mem_save($convId, $mem);
        ok(['memory'=>$mem]);

    // ── END-USER PIPELINE (operator-side CRUD) ───────────────
    // Operator manages an end-user's verification record + purchases manually
    // (or via integration). The AI agent reads, NEVER writes — so a hostile
    // user can't trick the agent into granting them a refund or marking
    // themselves as a "VIP" customer.
    case 'get_end_user':
        // Look up an end-user record for a given conv. Auto-creates a stub
        // (with the conv's name/handle) the first time so the editor always
        // has something to render.
        $convId = $_GET['conv_id'] ?? $body['conv_id'] ?? '';
        if (!$convId) err('conv_id required');
        // A direct chat's record ('dm_<thread>_<owner>') only exists once an
        // agent has worked the chat (dm_shop_ensure). Before that there is
        // nothing to show yet, which isn't an error.
        $dmPc = dm_shop_parse_conv((string)$convId);
        if ($dmPc && $dmPc['owner'] === (int)$ACCOUNT_ID) {
            $dx = $pdo->prepare("SELECT 1 FROM bc_conversations WHERE id=? AND account_id=?");
            $dx->execute([$convId, $ACCOUNT_ID]);
            if (!$dx->fetchColumn()) {
                ok(['end_user' => null, 'conversation' => null, 'purchases' => [], 'transactions' => [],
                    'memory' => (object)[], 'summary' => '', 'stats' => (object)[], 'crm' => (object)[],
                    'escalation' => null, 'dm_ids' => (object)[], 'dm_agent' => null,
                    'server_now_ms' => (int)(microtime(true) * 1000)]);
            }
        }
        own_conv($pdo, $ACCOUNT_ID, $convId);
        $cs = $pdo->prepare("SELECT name, handle, platform, chat_id FROM bc_conversations WHERE id=? AND account_id=?");
        $cs->execute([$convId, $ACCOUNT_ID]);
        $cv = $cs->fetch();
        $eu = $pdo->prepare("SELECT * FROM bc_end_users WHERE account_id=? AND conv_id=?");
        $eu->execute([$ACCOUNT_ID, $convId]);
        $row = $eu->fetch();
        if (!$row && $cv) {
            $ins = $pdo->prepare("INSERT INTO bc_end_users (account_id, conv_id, platform, chat_id, name, handle) VALUES (?,?,?,?,?,?)");
            $ins->execute([$ACCOUNT_ID, $convId, $cv['platform'], $cv['chat_id'], $cv['name'] ?? '', $cv['handle'] ?? '']);
            $eu->execute([$ACCOUNT_ID, $convId]);
            $row = $eu->fetch();
        }
        // Pull purchases + transactions in the same round-trip.
        $purchases = [];
        $txs = [];
        if ($row) {
            $p = $pdo->prepare("
                SELECT p.id, p.purchased_at, p.expires_at, p.status, p.notes, p.product_id,
                       p.serial_key, p.username,
                       pr.name AS product_name, pr.sku AS product_sku, pr.price AS product_price, pr.type AS product_type,
                       pr.allow_username, pr.allow_serial, pr.allow_account_creation
                FROM bc_end_user_products p
                LEFT JOIN bc_products pr ON pr.id = p.product_id
                WHERE p.account_id=? AND p.end_user_id=?
                ORDER BY p.purchased_at DESC
            ");
            $p->execute([$ACCOUNT_ID, (int)$row['id']]);
            $purchases = $p->fetchAll();
            $t = $pdo->prepare("
                SELECT t.id, t.amount, t.currency, t.status, t.reference, t.notes, t.created_at, t.product_id,
                       UNIX_TIMESTAMP(t.created_at) * 1000 AS created_ts,
                       pr.name AS product_name
                FROM bc_end_user_transactions t
                LEFT JOIN bc_products pr ON pr.id = t.product_id
                WHERE t.account_id=? AND t.end_user_id=?
                ORDER BY t.created_at DESC
            ");
            $t->execute([$ACCOUNT_ID, (int)$row['id']]);
            $txs = $t->fetchAll();
        }

        // ── EXTENDED CUSTOMER RECORD ──────────────────────────────
        // The Customer Record drawer in the UI needs much more than the
        // bare profile + purchases + transactions. We also surface:
        //   • memory   — the LLM's structured tree (notes, facts, prefs,
        //                signals, open_threads, plus the latest_thinking
        //                snapshot we capture in ai_reply)
        //   • summary  — the conversation's running one-liner (mem_summary)
        //   • stats    — message counts, first/last contact, total spend
        //   • invoices — payment requests we've sent this conversation
        //                (joined from the per-conversation invoice store
        //                where available)
        $mem = mem_load($convId);

        // Mem_summary lives on the conversation row, not in the JSON memory.
        $sumStmt = $pdo->prepare("SELECT mem_summary, name, handle, platform FROM bc_conversations WHERE id=? AND account_id=?");
        $sumStmt->execute([$convId, $ACCOUNT_ID]);
        $summaryRow = $sumStmt->fetch();
        $memSummary = is_array($summaryRow) ? (string)($summaryRow['mem_summary'] ?? '') : '';

        // Message stats — total counts + first/last contact timestamps so
        // the operator can see at a glance how active this customer is.
        $statsStmt = $pdo->prepare("
            SELECT
                COUNT(*) AS total,
                SUM(CASE WHEN role='in'  THEN 1 ELSE 0 END) AS inbound,
                SUM(CASE WHEN role='out' THEN 1 ELSE 0 END) AS outbound,
                MIN(created_at) AS first_at,
                MAX(created_at) AS last_at
            FROM bc_messages WHERE conv_id=? AND account_id=?
        ");
        $statsStmt->execute([$convId, $ACCOUNT_ID]);
        $statsRow = $statsStmt->fetch() ?: [];
        $stats = [
            'total_messages'    => (int)($statsRow['total']    ?? 0),
            'inbound_messages'  => (int)($statsRow['inbound']  ?? 0),
            'outbound_messages' => (int)($statsRow['outbound'] ?? 0),
            'first_contact_at'  => $statsRow['first_at'] ?? null,
            'last_contact_at'   => $statsRow['last_at']  ?? null,
        ];

        // Total spend — sum of completed transactions, grouped by currency.
        $spendByCurrency = [];
        foreach ($txs as $t0) {
            if (($t0['status'] ?? '') !== 'completed') continue;
            $cur = strtoupper((string)($t0['currency'] ?? ''));
            $amt = (float)($t0['amount'] ?? 0);
            if ($cur === '' || !is_finite($amt)) continue;
            $spendByCurrency[$cur] = ($spendByCurrency[$cur] ?? 0) + $amt;
        }
        $stats['spend_by_currency'] = $spendByCurrency;

        // ── CRM BLOCK — curated, ranked, ready to render ──────────────
        // Builds a single object the front-end panel consumes directly.
        // Grouping + ordering happen here once instead of in every panel
        // render. Empty groups are omitted so the UI can map and skip
        // without every consumer doing the same null-checks.
        $crm = [];

        // ABOUT — stable identity attributes the agent has captured. Sourced
        // from memory.profile (LLM-curated) and the end_user row, with the
        // end_user fields winning when both are present.
        $about = [];
        $profileMem = is_array($mem['profile'] ?? null) ? $mem['profile'] : [];
        $aboutKeys = ['name','role','company','location','language','timezone','age_range'];
        foreach ($aboutKeys as $k) {
            $v = $profileMem[$k] ?? null;
            if ($v === null || $v === '') continue;
            $about[] = ['key' => $k, 'value' => (string)$v];
        }
        if ($about) $crm['about'] = $about;

        // INTERESTS — product engagement timeline. Already shaped server-side
        // (mem_merge keeps the list dedup'd & status-aware).
        $interests = is_array($mem['interests'] ?? null) ? $mem['interests'] : [];
        if ($interests) $crm['interests'] = array_values($interests);

        // FACTS / PREFS — sparse merges live on memory; we just expose them
        // in ordered KV form so the panel can render predictably.
        $factsMem = is_array($mem['facts'] ?? null) ? $mem['facts'] : [];
        $facts = [];
        foreach ($factsMem as $k => $v) {
            if ($v === null || $v === '' || !is_scalar($v)) continue;
            $facts[] = ['key' => $k, 'value' => (string)$v];
        }
        if ($facts) $crm['facts'] = $facts;

        $prefsMem = is_array($mem['prefs'] ?? null) ? $mem['prefs'] : [];
        $prefs = [];
        foreach ($prefsMem as $k => $v) {
            if ($v === null || $v === '' || !is_scalar($v)) continue;
            $prefs[] = ['key' => $k, 'value' => (string)$v];
        }
        if ($prefs) $crm['prefs'] = $prefs;

        // OPEN THREADS — questions the agent owes the customer. Newest first.
        $threads = is_array($mem['open_threads'] ?? null) ? $mem['open_threads'] : [];
        $threads = array_values(array_filter(array_map(function($t){
            return is_string($t) ? $t : ($t['q'] ?? $t['text'] ?? null);
        }, $threads), fn($x) => is_string($x) && $x !== ''));
        if ($threads) $crm['open_threads'] = array_reverse($threads);

        // ACTIVITY — funnel signals as a chronologically ordered timeline.
        // Latest 12 only; prefixes (q:/p:/c:/obj:/a:/flag:) are kept so the
        // UI can color-code without re-deriving them.
        $signals = is_array($mem['signals'] ?? null) ? $mem['signals'] : [];
        if ($signals) {
            $tail = array_slice($signals, -12);
            $crm['activity'] = array_values(array_filter($tail, fn($s) => is_string($s) && $s !== ''));
        }

        // NOTES — topic-consolidated structured records {n,t,u,x}, newest
        // first. Consolidation runs on read too, so conversations whose
        // memory file still holds legacy duplicate strings render clean
        // immediately without waiting for the next AI turn to rewrite it.
        $notes = is_array($mem['notes'] ?? null) ? mem_notes_consolidate($mem['notes'], 15, mem_notes_legacy_base($mem)) : [];
        if ($notes) {
            $crm['notes'] = array_values(array_slice(array_reverse($notes), 0, 12));
        }
        // LANGUAGE — the BCP-47 code of the language the agent last replied
        // in (persisted in ai_reply), plus whatever the model recorded in
        // profile.language. The popup shows it as a chip under the name.
        $replyLangOut = (string)($mem['reply_lang'] ?? '');
        $profLangOut  = trim((string)(is_array($mem['profile'] ?? null) ? ($mem['profile']['language'] ?? '') : ''));
        if ($replyLangOut !== '' || $profLangOut !== '') {
            $crm['language'] = ['code' => $replyLangOut, 'name' => $profLangOut];
        }

        // CHAPTERS — narrative spans of the conversation, oldest first so
        // the panel renders them in the order they occurred. The front-end
        // is responsible for rendering the open chapter with a glow.
        $chapters = is_array($mem['chapters'] ?? null) ? $mem['chapters'] : [];
        if ($chapters) {
            // Defensive — drop any malformed entries (e.g. legacy file that
            // somehow has a non-array element) so the front-end never has
            // to worry about shape.
            $chapters = array_values(array_filter($chapters, fn($c) => is_array($c) && !empty($c['title'])));
            // Collapse back-to-back duplicates on read so conversations that
            // already picked one up display cleanly straight away.
            $chapters = mem_chapters_dedupe($chapters);
            if ($chapters) $crm['chapters'] = $chapters;
        }

        // Headline scores (already on memory; copied here for one-stop access).
        $crm['scores'] = [
            'trust'      => is_numeric($mem['trust'] ?? null)      ? (int)$mem['trust']      : null,
            'engagement' => is_numeric($mem['engagement'] ?? null) ? (int)$mem['engagement'] : null,
            'happiness'  => is_numeric($mem['happiness'] ?? null)  ? (int)$mem['happiness']  : null,
        ];
        $crm['stage'] = $mem['stage'] ?? 'new';
        $crm['stage_reason'] = (string)($mem['last_stage_reason'] ?? '');

        // ── ESCALATION ── decode the JSON blob so the front-end gets a
        // structured object (not a raw string). Pending escalations also
        // get hoisted onto the conversation row's stage so the inbox
        // filter picks them up without re-fetching.
        $escalationOut = null;
        if ($row && !empty($row['escalation'])) {
            $j = json_decode((string)$row['escalation'], true);
            if (is_array($j) && !empty($j['status'])) $escalationOut = $j;
            // Replace the raw text with the parsed object so the front-end
            // receives a usable shape directly off `end_user.escalation`.
            $row['escalation'] = $escalationOut;
        } else if ($row) {
            $row['escalation'] = null;
        }

        // DIRECT CHATS. Their bubbles carry direct-message ids, while the
        // record (interests, notes, chapters, escalations) points at the
        // readable copy's ids (bc_messages, msg_uid 'dm:<owner>:<dm id>'),
        // so the chat gets the mapping to place its separators exactly. It
        // also gets why the agent stepped down (e.g. Stop After Sale) and
        // when, for the "AI unassigned" line every other chat shows.
        $dmIds = null; $dmAgent = null;
        if ($dmPc) {
            $dmIds = [];
            try {
                $pre = 'dm:' . (int)$ACCOUNT_ID . ':';
                $q = $pdo->prepare("SELECT id, msg_uid FROM bc_messages WHERE conv_id=? AND account_id=? AND msg_uid LIKE ? ORDER BY id DESC LIMIT 800");
                $q->execute([$convId, $ACCOUNT_ID, $pre . '%']);
                foreach ($q->fetchAll() as $mr) {
                    $sid = (int)substr((string)$mr['msg_uid'], strlen($pre));
                    if ($sid > 0 && !isset($dmIds[$sid])) $dmIds[$sid] = (int)$mr['id'];
                }
            } catch (Throwable $e) {}
            try {
                $q = $pdo->prepare("SELECT unassign_reason, UNIX_TIMESTAMP(unassigned_at) AS at_s FROM bc_conversations WHERE id=? AND account_id=?");
                $q->execute([$convId, $ACCOUNT_ID]);
                $ar = $q->fetch();
                if ($ar) $dmAgent = ['unassign_reason' => (string)($ar['unassign_reason'] ?? ''), 'unassigned_at_ms' => (int)($ar['at_s'] ?? 0) * 1000];
            } catch (Throwable $e) {}
        }

        ok([
            'dm_ids'       => $dmIds === null ? null : (object)$dmIds,
            'dm_agent'     => $dmAgent,
            'end_user'     => $row,
            'conversation' => $cv ? [
                'name'     => $cv['name'] ?? '',
                'handle'   => $cv['handle'] ?? '',
                'platform' => $cv['platform'] ?? '',
                // Avatar from bc_conversations is populated by Form1.vb on
                // every inbound. Used as a fallback in the profile popup
                // when bc_end_users.avatar_url hasn't been backfilled yet.
                'avatar'   => (function() use ($pdo, $convId, $ACCOUNT_ID) {
                    $q = $pdo->prepare("SELECT avatar FROM bc_conversations WHERE id=? AND account_id=?");
                    $q->execute([$convId, $ACCOUNT_ID]);
                    $r = $q->fetch();
                    return is_array($r) ? (string)($r['avatar'] ?? '') : '';
                })(),
            ] : null,
            'purchases'    => $purchases,
            'transactions' => $txs,
            'memory'       => $mem,
            'summary'      => $memSummary,
            'stats'        => $stats,
            'crm'          => $crm,
            'escalation'   => $escalationOut,
            // Server clock, so the chat can line up stamps written by the
            // browser (live bubbles, invoices) with stamps written here.
            'server_now_ms'=> (int)(microtime(true) * 1000),
        ]);

    case 'save_end_user':
        $convId = $body['conv_id'] ?? '';
        if (!$convId) err('conv_id required');
        own_conv($pdo, $ACCOUNT_ID, $convId);
        $cs = $pdo->prepare("SELECT platform, chat_id FROM bc_conversations WHERE id=? AND account_id=?");
        $cs->execute([$convId, $ACCOUNT_ID]);
        $cv = $cs->fetch();
        if (!$cv) err('conversation not found');
        $stmt = $pdo->prepare("
            INSERT INTO bc_end_users (account_id, conv_id, platform, chat_id, name, handle, email, phone, notes, verified)
            VALUES (:a,:c,:p,:ci,:n,:h,:e,:ph,:no,:v)
            ON DUPLICATE KEY UPDATE
                name=VALUES(name), handle=VALUES(handle),
                email=VALUES(email), phone=VALUES(phone),
                notes=VALUES(notes), verified=VALUES(verified)
        ");
        $stmt->execute([
            ':a'  => $ACCOUNT_ID,
            ':c'  => $convId,
            ':p'  => $cv['platform'],
            ':ci' => $cv['chat_id'],
            ':n'  => (string)($body['name']     ?? ''),
            ':h'  => (string)($body['handle']   ?? ''),
            ':e'  => (string)($body['email']    ?? ''),
            ':ph' => (string)($body['phone']    ?? ''),
            ':no' => (string)($body['notes']    ?? ''),
            ':v'  => !empty($body['verified']) ? 1 : 0,
        ]);
        ok();

    // ── Upsert platform-supplied profile metadata ──────────────────────
    // Called by Form1.vb on inbound when it has fresh avatar/cover/bio/
    // status from the platform's user-profile API. UNLIKE save_end_user
    // this only writes metadata fields the OPERATOR doesn't typically
    // edit — so it never clobbers their notes/verified/email overrides.
    // Each field is optional: only fields present in the request body
    // are written. Missing fields are left alone (COALESCE pattern).
    case 'upsert_end_user_meta':
        $convId = $body['conv_id'] ?? '';
        if (!$convId) err('conv_id required');
        own_conv($pdo, $ACCOUNT_ID, $convId);
        $cs = $pdo->prepare("SELECT platform, chat_id, name, handle FROM bc_conversations WHERE id=? AND account_id=?");
        $cs->execute([$convId, $ACCOUNT_ID]);
        $cv = $cs->fetch();
        if (!$cv) err('conversation not found');
        // Auto-create stub so the metadata has somewhere to land.
        $pdo->prepare("INSERT IGNORE INTO bc_end_users (account_id, conv_id, platform, chat_id, name, handle) VALUES (?,?,?,?,?,?)")
            ->execute([$ACCOUNT_ID, $convId, $cv['platform'], $cv['chat_id'], $cv['name'] ?? '', $cv['handle'] ?? '']);
        // Build a dynamic UPDATE that only touches the supplied fields.
        $sets = [];
        $args = [];
        foreach (['avatar_url','cover_url','bio','status_text'] as $col) {
            if (array_key_exists($col, $body)) {
                $v = $body[$col];
                $sets[] = "$col = ?";
                $args[] = ($v === null || $v === '') ? null : (string)$v;
            }
        }
        if ($sets) {
            $args[] = $ACCOUNT_ID;
            $args[] = $convId;
            $sql = "UPDATE bc_end_users SET " . implode(', ', $sets) . " WHERE account_id=? AND conv_id=?";
            $pdo->prepare($sql)->execute($args);
        }
        // Mirror avatar onto bc_conversations too so the inbox row stays
        // in sync without a second round-trip from the host.
        if (array_key_exists('avatar_url', $body)) {
            $pdo->prepare("UPDATE bc_conversations SET avatar=? WHERE id=? AND account_id=?")
                ->execute([(string)($body['avatar_url'] ?? ''), $convId, $ACCOUNT_ID]);
        }
        ok();

    // ── Block / unblock an end user for this conversation ──────────────
    // Persists `is_blocked` on bc_end_users and notifies the .NET host so
    // the platform-side block (Telegram User-API Contacts.block, Discord
    // ignore) is applied immediately. The host's response comes back via
    // the bcEvent bus — the API layer just records the desired state.
    //
    // Auto-reply round-trip: when blocking we set bc_conversations.auto_reply=0
    // so a stale ai_reply request can't slip through. Previously, unblocking
    // never RESTORED auto_reply, so the AI silently stopped replying forever.
    // Fix: on first block, snapshot the prior auto_reply value into
    // bc_end_users.auto_reply_before_block. On unblock, restore it (or
    // fall back to the agent's auto_reply_default if no snapshot exists,
    // which covers users who were blocked before this fix shipped).
    case 'set_end_user_block':
        $convId  = $body['conv_id'] ?? '';
        $blocked = !empty($body['blocked']) ? 1 : 0;
        if (!$convId) err('conv_id required');
        own_conv($pdo, $ACCOUNT_ID, $convId);
        // Auto-create a stub end_user row if one doesn't exist yet so the
        // flag has somewhere to live.
        $cs = $pdo->prepare("SELECT platform, chat_id, name, handle, auto_reply, agent_id FROM bc_conversations WHERE id=? AND account_id=?");
        $cs->execute([$convId, $ACCOUNT_ID]);
        $cv = $cs->fetch();
        if (!$cv) err('conversation not found');
        $pdo->prepare("INSERT IGNORE INTO bc_end_users (account_id, conv_id, platform, chat_id, name, handle) VALUES (?,?,?,?,?,?)")
            ->execute([$ACCOUNT_ID, $convId, $cv['platform'], $cv['chat_id'], $cv['name'] ?? '', $cv['handle'] ?? '']);

        // Schema upgrade — snapshot column for restoring auto_reply on unblock.
        if (!col_exists($pdo,'bc_end_users','auto_reply_before_block')) {
            try_alter($pdo, "ALTER TABLE bc_end_users ADD COLUMN auto_reply_before_block TINYINT(1) DEFAULT NULL AFTER is_blocked");
        }

        if ($blocked) {
            // BLOCKING — capture the current auto_reply BEFORE we flip it,
            // so unblock can put it back exactly where it was. Use a single
            // round trip so a concurrent set_auto_reply can't race us.
            $priorAutoReply = (int)($cv['auto_reply'] ?? 0);
            $pdo->prepare("UPDATE bc_end_users
                              SET is_blocked=1,
                                  blocked_at=NOW(),
                                  auto_reply_before_block=?
                            WHERE account_id=? AND conv_id=?")
                ->execute([$priorAutoReply, $ACCOUNT_ID, $convId]);
            $pdo->prepare("UPDATE bc_conversations SET auto_reply=0 WHERE id=? AND account_id=?")
                ->execute([$convId, $ACCOUNT_ID]);
            ok([
                'is_blocked' => 1,
                'auto_reply' => 0,
                'platform'   => $cv['platform'],
                'chat_id'    => $cv['chat_id'],
            ]);
        } else {
            // UNBLOCKING — restore the snapshotted auto_reply. If there's no
            // snapshot (legacy block from before this fix), fall back to the
            // agent's auto_reply_default so the AI starts replying again on
            // its own. This is the bug the user reported: "the agent is not
            // replying once I unblocked".
            $snap = $pdo->prepare("SELECT auto_reply_before_block FROM bc_end_users WHERE account_id=? AND conv_id=?");
            $snap->execute([$ACCOUNT_ID, $convId]);
            $snapRow = $snap->fetch();
            $restore = null;
            if ($snapRow && $snapRow['auto_reply_before_block'] !== null) {
                $restore = (int)$snapRow['auto_reply_before_block'];
            } else {
                // Legacy fallback: use the agent's auto_reply_default.
                if (!empty($cv['agent_id'])) {
                    $a = $pdo->prepare("SELECT auto_reply_default FROM bc_agents WHERE id=? AND account_id=?");
                    $a->execute([(int)$cv['agent_id'], $ACCOUNT_ID]);
                    $aRow = $a->fetch();
                    if ($aRow) $restore = (int)$aRow['auto_reply_default'];
                }
                // Last-resort default: ON. Better to over-restore than to
                // leave the user stuck wondering why the AI is silent.
                if ($restore === null) $restore = 1;
            }
            $pdo->prepare("UPDATE bc_end_users
                              SET is_blocked=0,
                                  blocked_at=NULL,
                                  auto_reply_before_block=NULL
                            WHERE account_id=? AND conv_id=?")
                ->execute([$ACCOUNT_ID, $convId]);
            $pdo->prepare("UPDATE bc_conversations SET auto_reply=? WHERE id=? AND account_id=?")
                ->execute([$restore, $convId, $ACCOUNT_ID]);
            ok([
                'is_blocked' => 0,
                'auto_reply' => $restore,
                'platform'   => $cv['platform'],
                'chat_id'    => $cv['chat_id'],
            ]);
        }

    // ── Mute / unmute an end user (suppress AI auto-reply only) ────────
    // Inbound messages still arrive in the operator's inbox; the AI just
    // doesn't compose a reply for them. Useful for "I want to handle
    // this VIP myself" without breaking the chat platform-side.
    case 'set_end_user_mute':
        $convId = $body['conv_id'] ?? '';
        $muted  = !empty($body['muted']) ? 1 : 0;
        if (!$convId) err('conv_id required');
        own_conv($pdo, $ACCOUNT_ID, $convId);
        $cs = $pdo->prepare("SELECT platform, chat_id, name, handle FROM bc_conversations WHERE id=? AND account_id=?");
        $cs->execute([$convId, $ACCOUNT_ID]);
        $cv = $cs->fetch();
        if (!$cv) err('conversation not found');
        $pdo->prepare("INSERT IGNORE INTO bc_end_users (account_id, conv_id, platform, chat_id, name, handle) VALUES (?,?,?,?,?,?)")
            ->execute([$ACCOUNT_ID, $convId, $cv['platform'], $cv['chat_id'], $cv['name'] ?? '', $cv['handle'] ?? '']);
        $upd = $pdo->prepare("UPDATE bc_end_users SET is_muted=?, muted_at=" . ($muted ? "NOW()" : "NULL") . " WHERE account_id=? AND conv_id=?");
        $upd->execute([$muted, $ACCOUNT_ID, $convId]);
        ok(['is_muted' => $muted]);

    // ── ESCALATION ENDPOINTS ──────────────────────────────────────────
    // Mark a conversation as escalated to a human. The AI subsequently
    // refuses to auto-reply (the regular reply pipeline checks the flag
    // before generating), and the front-end shows the user under the
    // Escalated filter with a banner in their profile popup. Operators
    // resolve via 'resolve_escalation' once the issue is handled.
    case 'escalate_conv':
        $convId = $body['conv_id'] ?? '';
        $kind   = strtolower(trim((string)($body['kind']    ?? 'help')));   // refund | help | manual
        $reason = trim((string)($body['reason']  ?? ''));
        $msg    = trim((string)($body['message'] ?? ''));
        if (!$convId) err('conv_id required');
        if (!in_array($kind, ['refund','help','manual'], true)) $kind = 'help';
        own_conv($pdo, $ACCOUNT_ID, $convId);
        $cs = $pdo->prepare("SELECT platform, chat_id, name, handle FROM bc_conversations WHERE id=? AND account_id=?");
        $cs->execute([$convId, $ACCOUNT_ID]);
        $cv = $cs->fetch();
        if (!$cv) err('conversation not found');
        $pdo->prepare("INSERT IGNORE INTO bc_end_users (account_id, conv_id, platform, chat_id, name, handle) VALUES (?,?,?,?,?,?)")
            ->execute([$ACCOUNT_ID, $convId, $cv['platform'], $cv['chat_id'], $cv['name'] ?? '', $cv['handle'] ?? '']);
        // Build the escalation blob. Don't overwrite an existing 'pending'
        // record's raised_at — escalating again on an already-pending row
        // is a no-op for the timestamp (the original raise time is what
        // the operator wants to see).
        $existing = $pdo->prepare("SELECT escalation FROM bc_end_users WHERE account_id=? AND conv_id=?");
        $existing->execute([$ACCOUNT_ID, $convId]);
        $exRaw  = (string)($existing->fetchColumn() ?: '');
        $exJson = $exRaw ? (json_decode($exRaw, true) ?: null) : null;
        $raisedAt = (is_array($exJson) && ($exJson['status'] ?? '') === 'pending' && !empty($exJson['raised_at']))
            ? $exJson['raised_at']
            : gmdate('c');
        $blob = [
            'status'     => 'pending',
            'kind'       => $kind,
            'reason'     => $reason ?: ($kind === 'refund' ? 'refund_request' : ($kind === 'help' ? 'help_request' : 'manual')),
            'message'    => mb_substr($msg, 0, 280),
            'raised_at'  => $raisedAt,
        ];
        // raised_msg_id — newest message at the moment of the raise, so the
        // chat can put the hand-over separator exactly under it.
        if (is_array($exJson) && ($exJson['status'] ?? '') === 'pending' && !empty($exJson['raised_msg_id'])) {
            $blob['raised_msg_id'] = (int)$exJson['raised_msg_id'];
        } else {
            try {
                $rm = $pdo->prepare("SELECT id FROM bc_messages WHERE conv_id=? AND account_id=? ORDER BY id DESC LIMIT 1");
                $rm->execute([$convId, $ACCOUNT_ID]);
                $rmId = (int)$rm->fetchColumn();
                if ($rmId) $blob['raised_msg_id'] = $rmId;
            } catch (Throwable $e) { /* optional */ }
        }
        $pdo->prepare("UPDATE bc_end_users SET escalation=? WHERE account_id=? AND conv_id=?")
            ->execute([json_encode($blob, JSON_UNESCAPED_UNICODE), $ACCOUNT_ID, $convId]);
        // Also auto-mute so the AI stops replying until a human resolves.
        $pdo->prepare("UPDATE bc_end_users SET is_muted=1, muted_at=NOW() WHERE account_id=? AND conv_id=?")
            ->execute([$ACCOUNT_ID, $convId]);
        // Stamp the conversation stage so the inbox filter picks it up
        // immediately (the /get_conversations response surfaces this stage
        // and the front-end MSGS_STORE.load() merges it into the live row).
        $pdo->prepare("UPDATE bc_conversations SET stage='escalated' WHERE id=? AND account_id=?")
            ->execute([$convId, $ACCOUNT_ID]);
        ok(['escalation' => $blob]);

    case 'resolve_escalation':
        $convId = $body['conv_id'] ?? '';
        if (!$convId) err('conv_id required');
        own_conv($pdo, $ACCOUNT_ID, $convId);
        // Mark resolved + clear the auto-mute, restoring AI auto-reply.
        // We KEEP the resolved record (status='resolved') in the JSON so
        // the operator has an audit trail; the UI banner only renders for
        // status='pending' so a resolved record won't re-show.
        // ── ROBUSTNESS: ensure the end_users row exists ────────────────
        // Earlier versions of this handler silently no-op'd if the row
        // had been deleted (e.g. by a Reset) or hadn't been created yet
        // — operators reported "I clicked resolve and nothing happened".
        // We materialise the row from the conversation record so the
        // UPDATE always lands on a real target.
        $cs = $pdo->prepare("SELECT platform, chat_id, name, handle FROM bc_conversations WHERE id=? AND account_id=?");
        $cs->execute([$convId, $ACCOUNT_ID]);
        $cv = $cs->fetch();
        if ($cv) {
            $pdo->prepare("INSERT IGNORE INTO bc_end_users (account_id, conv_id, platform, chat_id, name, handle) VALUES (?,?,?,?,?,?)")
                ->execute([$ACCOUNT_ID, $convId, $cv['platform'], $cv['chat_id'], $cv['name'] ?? '', $cv['handle'] ?? '']);
        }
        $existing = $pdo->prepare("SELECT escalation FROM bc_end_users WHERE account_id=? AND conv_id=?");
        $existing->execute([$ACCOUNT_ID, $convId]);
        $exRaw  = (string)($existing->fetchColumn() ?: '');
        $exJson = $exRaw ? (json_decode($exRaw, true) ?: []) : [];
        if (!is_array($exJson)) $exJson = [];
        // If the row exists but has no escalation blob, synthesise a
        // minimal one so the resolved record makes sense in audit logs.
        // ("operator resolved an escalation that wasn't on the server"
        // is a real case — e.g. when the popup mirrored a stage-based
        // pseudo-escalation from `stage='needs_help'`.)
        if (empty($exJson['raised_at']))   $exJson['raised_at']  = gmdate('c');
        if (empty($exJson['kind']))        $exJson['kind']       = 'help';
        if (empty($exJson['reason']))      $exJson['reason']     = 'manual_resolve';
        $exJson['status']      = 'resolved';
        $exJson['resolved_at'] = gmdate('c');
        $exJson['resolved_by'] = (int)($ACCOUNT_ID ?? 0);
        // resolved_msg_id — the newest message id at the moment of resolution.
        // ai_reply compares against it (ids, not timestamps: created_at is DB
        // time, resolved_at is PHP UTC, and the two can disagree) to know
        // whether the AI has spoken since being resumed.
        $lastMsg = $pdo->prepare("SELECT id, role FROM bc_messages WHERE conv_id=? AND account_id=? ORDER BY id DESC LIMIT 1");
        $lastMsg->execute([$convId, $ACCOUNT_ID]);
        $lastRow = $lastMsg->fetch() ?: null;
        $exJson['resolved_msg_id'] = $lastRow ? (int)$lastRow['id'] : 0;
        $pdo->prepare("UPDATE bc_end_users SET escalation=?, is_muted=0, muted_at=NULL WHERE account_id=? AND conv_id=?")
            ->execute([json_encode($exJson, JSON_UNESCAPED_UNICODE), $ACCOUNT_ID, $convId]);
        // Restore conversation stage so it leaves the Escalated filter.
        // Someone who has already paid comes back as a customer, not as a
        // fresh lead. Strict stage filter means a stage that's already been
        // moved on (e.g. 'closed') is left alone.
        conv_restore_stage_after_escalation($pdo, $ACCOUNT_ID, $convId);
        // RESUME AI — "Resolve & resume AI" must actually turn replies back
        // on. Callers that only want to clear the flag (e.g. a ghost-command
        // de-escalate without resume) pass resume_ai=0.
        $resumeAi = !isset($body['resume_ai']) || (string)$body['resume_ai'] === '1' || $body['resume_ai'] === true;
        if ($resumeAi) {
            $pdo->prepare("UPDATE bc_conversations SET auto_reply=1 WHERE id=? AND account_id=?")
                ->execute([$convId, $ACCOUNT_ID]);
        }
        // Record the resolution in the AI's memory so its recent_signals show
        // the hand-over is over ("esc:refund … esc:resolved"), not still open.
        // Also CLOSE the chapter that was open when the conversation was
        // handed over. Left open, the next turn saw "open_chapter: Refund
        // request" and re-narrated it as ongoing. `closed_msg_id` marks the
        // resolution point: mem_merge will only reopen / extend this chapter
        // if the customer raises the topic in a message sent after it.
        try {
            $memR = mem_load($convId);
            $memR = mem_merge($memR, ['signals' => ['esc:resolved']]);
            $memR = mem_chapters_close_for_resolution($memR, $exJson);
            mem_save($convId, $memR);
        } catch (Throwable $e) { error_log('[resolve_escalation] memory note failed: ' . $e->getMessage()); }
        if (!empty($resumeAi)) bot_relay_nudge($pdo, (int)$ACCOUNT_ID, (string)$convId);
        ok([
            'escalation'     => $exJson,
            'resolved'       => true,
            'auto_reply'     => $resumeAi,
            // true when the customer's message is the last one in the thread,
            // i.e. they're still waiting on an answer from the pause window.
            'awaiting_reply' => $lastRow ? (($lastRow['role'] ?? '') === 'in') : false,
        ]);

    // ── CRYPTO RATES (read-only) ──────────────────────────────────────
    // Public passthrough to the cached crypto_rates() helper. The frontend
    // popup uses this to display USD-equivalents alongside crypto totals
    // without each account having to maintain its own rate cache.
    case 'get_crypto_rates':
        try { $r = crypto_rates(); }
        catch (Throwable $e) { $r = ['rates'=>[], 'updated_at'=>0, 'source'=>'none']; }
        ok($r);

    // ── Block-explorer passthrough (wallet activity) ──────────────────
    // The wallet page reads balances and recent transactions for a payout
    // address from public block explorers. It calls them directly first;
    // when the browser can't (CORS, WebView rules) it comes here instead.
    // Only these read-only explorer hosts are reachable, over HTTPS, and a
    // POST body is only forwarded to the Solana RPC.
    case 'explorer_get': {
        $url   = trim((string)($body['url'] ?? ($_GET['url'] ?? '')));
        $parts = parse_url($url);
        $host  = strtolower((string)($parts['host'] ?? ''));
        $allowed = [
            'mempool.space', 'litecoinspace.org', 'api.blockchair.com',
            'eth.blockscout.com', 'polygon.blockscout.com',
            'api.trongrid.io', 'api.mainnet-beta.solana.com',
        ];
        if (strtolower((string)($parts['scheme'] ?? '')) !== 'https' || !in_array($host, $allowed, true)
            || isset($parts['user']) || isset($parts['port'])) {
            err('explorer host not allowed');
        }
        $post = $body['post'] ?? null;
        if ($post !== null && $host !== 'api.mainnet-beta.solana.com') err('explorer POST not allowed');

        // Short shared cache so several open windows don't each hit the
        // explorer's rate limit.
        $ckey = sys_get_temp_dir() . '/bc_explorer_' . md5($url . '|' . json_encode($post));
        if (is_file($ckey) && (time() - filemtime($ckey)) < 30) {
            $cached = json_decode((string)@file_get_contents($ckey), true);
            if (is_array($cached)) ok($cached);
        }

        $headers = ['Accept: application/json'];
        $ch = curl_init($url);
        $opts = [
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_TIMEOUT        => 15,
            CURLOPT_CONNECTTIMEOUT => 6,
            CURLOPT_FOLLOWLOCATION => false,
            CURLOPT_USERAGENT      => 'BotCommand/1.0 (+wallet activity)',
            CURLOPT_PROTOCOLS      => CURLPROTO_HTTPS,
        ];
        if ($post !== null) {
            $opts[CURLOPT_POST]       = true;
            $opts[CURLOPT_POSTFIELDS] = json_encode($post, JSON_UNESCAPED_SLASHES);
            $headers[] = 'Content-Type: application/json';
        }
        $opts[CURLOPT_HTTPHEADER] = $headers;
        curl_setopt_array($ch, $opts);
        $res  = curl_exec($ch);
        $code = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
        $cerr = $res === false ? curl_error($ch) : '';
        curl_close($ch);
        if ($res === false) err('explorer unreachable: ' . $cerr);
        if (strlen($res) > 3000000) err('explorer response too large');
        $out = ['status' => $code, 'data' => json_decode($res, true)];
        if ($code >= 200 && $code < 300) @file_put_contents($ckey, json_encode($out));
        ok($out);
    }

    // ── Add a purchase record for an end user ──────────────────────────
    // The orphan code that used to live here (no `case` line) was unreachable;
    // this restores the missing endpoint. Optionally accepts serial_key /
    // username for licensable products. Each is normalised + duplicate-checked
    // per-account so a serial key collision is detected before insert.
    case 'add_end_user_purchase':
        $eid = (int)($body['end_user_id'] ?? 0);
        $pid = (int)($body['product_id']  ?? 0);
        if (!$eid) err('end_user_id required');
        if (!$pid) err('product_id required');
        own_end_user($pdo, $ACCOUNT_ID, $eid);
        own_product($pdo, $ACCOUNT_ID, $pid);
        $serialKey = trim((string)($body['serial_key'] ?? ''));
        $username  = trim((string)($body['username']   ?? ''));
        // Reject duplicate serials within the same account so the public
        // verify_license endpoint always resolves a single license row.
        if ($serialKey !== '') {
            $dup = $pdo->prepare("SELECT id FROM bc_end_user_products WHERE account_id=? AND serial_key=? LIMIT 1");
            $dup->execute([$ACCOUNT_ID, $serialKey]);
            if ($dup->fetchColumn()) err('serial_key already exists');
        }
        $stmt = $pdo->prepare("INSERT INTO bc_end_user_products (account_id, end_user_id, product_id, expires_at, status, serial_key, username, notes) VALUES (?,?,?,?,?,?,?,?)");
        $stmt->execute([
            $ACCOUNT_ID, $eid, $pid,
            !empty($body['expires_at']) ? $body['expires_at'] : null,
            $body['status'] ?? 'active',
            $serialKey,
            $username,
            $body['notes'] ?? '',
        ]);
        ok(['id' => (int)$pdo->lastInsertId()]);

    case 'delete_end_user_purchase':
        $id = (int)($body['id'] ?? 0);
        if (!$id) err('id required');
        // Scope-delete via WHERE account_id — silently succeeds with 0 rows
        // if the record doesn't belong to this account.
        $pdo->prepare("DELETE FROM bc_end_user_products WHERE id=? AND account_id=?")->execute([$id, $ACCOUNT_ID]);
        ok();

    // ── Update a single purchase row ───────────────────────────────────
    // Operator-side edits from the new licenses panel: change status (for
    // revoke / extend), expiry date, serial key, username, or notes. Each
    // field is optional — only supplied fields get written. Duplicate serial
    // detection mirrors add_end_user_purchase.
    case 'update_end_user_purchase':
        $id = (int)($body['id'] ?? 0);
        if (!$id) err('id required');
        // Verify ownership: scope-load the row, refuse if not ours.
        $owns = $pdo->prepare("SELECT id FROM bc_end_user_products WHERE id=? AND account_id=?");
        $owns->execute([$id, $ACCOUNT_ID]);
        if (!$owns->fetchColumn()) err('purchase not found');

        $sets = [];
        $args = [];
        if (array_key_exists('status', $body)) {
            $st = (string)$body['status'];
            // Whitelist statuses so an attacker can't write arbitrary strings.
            if (!in_array($st, ['active','expired','cancelled','suspended','pending'], true)) {
                err('invalid status');
            }
            $sets[] = 'status = ?'; $args[] = $st;
        }
        if (array_key_exists('expires_at', $body)) {
            $sets[] = 'expires_at = ?';
            $args[] = !empty($body['expires_at']) ? $body['expires_at'] : null;
        }
        if (array_key_exists('serial_key', $body)) {
            $sk = trim((string)$body['serial_key']);
            if ($sk !== '') {
                $dup = $pdo->prepare("SELECT id FROM bc_end_user_products WHERE account_id=? AND serial_key=? AND id<>? LIMIT 1");
                $dup->execute([$ACCOUNT_ID, $sk, $id]);
                if ($dup->fetchColumn()) err('serial_key already exists');
            }
            $sets[] = 'serial_key = ?'; $args[] = $sk;
        }
        if (array_key_exists('username', $body)) {
            $sets[] = 'username = ?'; $args[] = trim((string)$body['username']);
        }
        if (array_key_exists('notes', $body)) {
            $sets[] = 'notes = ?'; $args[] = (string)$body['notes'];
        }
        if (!$sets) ok(['updated' => 0]);
        $args[] = $id;
        $args[] = $ACCOUNT_ID;
        $sql = "UPDATE bc_end_user_products SET " . implode(', ', $sets) . " WHERE id=? AND account_id=?";
        $pdo->prepare($sql)->execute($args);
        ok(['updated' => 1]);

    // ── List active licenses across all conversations ─────────────────
    // Powers the new Customers/Licenses slideout. Each row carries enough
    // to render without a per-row drill-down: product info, end-user
    // identity (name/handle/avatar), purchase + expiry dates, serial,
    // username binding, and the conv_id so the operator can jump into
    // the conversation if they want to.
    case 'get_active_licenses':
        $statusFilter = (string)($_GET['status'] ?? $body['status'] ?? '');
        $q            = trim((string)($_GET['q']  ?? $body['q']  ?? ''));
        // The LEFT JOIN on bc_end_user_transactions picks the payment that
        // issued each license (auto-issue links it via license_id) — the
        // newest one only, so a license row can never be duplicated.
        $sql = "
            SELECT p.id, p.product_id, p.end_user_id, p.purchased_at, p.expires_at,
                   p.status, p.serial_key, p.username, p.notes,
                   pr.name AS product_name, pr.sku AS product_sku, pr.type AS product_type,
                   pr.price AS product_price, pr.allow_username, pr.allow_serial,
                   pr.allow_account_creation,
                   eu.id AS eu_id, eu.conv_id, eu.name AS eu_name, eu.handle AS eu_handle,
                   eu.email AS eu_email, eu.phone AS eu_phone, eu.avatar_url AS eu_avatar,
                   eu.platform AS eu_platform,
                   t.id AS tx_id, t.amount AS tx_amount, t.currency AS tx_currency,
                   t.reference AS tx_reference, t.created_at AS tx_created_at,
                   t.delivered_at AS tx_delivered_at
            FROM bc_end_user_products p
            LEFT JOIN bc_products  pr ON pr.id = p.product_id
            LEFT JOIN bc_end_users eu ON eu.id = p.end_user_id
            LEFT JOIN bc_end_user_transactions t ON t.id = (
                SELECT MAX(t2.id) FROM bc_end_user_transactions t2
                WHERE t2.account_id = p.account_id AND t2.license_id = p.id
            )
            WHERE p.account_id = ?
        ";
        $args = [$ACCOUNT_ID];
        // Keys and codes handed out from a product's "Keys and codes" list
        // are not licences: a paid sale still gets an internal row (it is
        // what makes delivery idempotent), but the item itself is shown on
        // the sale's invoice (get_invoice_keys), not here. A row is left
        // out when it stands only for such an item: linked to a stock item
        // and carrying no key of its own (blank, or the item itself on rows
        // issued before this change). A package that also generates its own
        // serial keeps its row, because that serial IS a licence.
        if (stock_ready($pdo)) {
            try {
                $sx = $pdo->prepare("SELECT COALESCE(s.license_id, t.license_id) AS lid, s.item
                                      FROM bc_product_stock s
                                      LEFT JOIN bc_end_user_transactions t ON t.id = s.tx_id AND t.account_id = s.account_id
                                     WHERE s.account_id=? AND s.tx_id IS NOT NULL AND s.status IN ('given','owed')");
                $sx->execute([$ACCOUNT_ID]);
                $stockLic = [];
                foreach ($sx->fetchAll() as $x) {
                    $lid = (int)($x['lid'] ?? 0);
                    if ($lid > 0) $stockLic[$lid][] = (string)$x['item'];
                }
                if ($stockLic) {
                    $keyOf = $pdo->prepare("SELECT id, serial_key FROM bc_end_user_products WHERE account_id=? AND id IN ("
                        . implode(',', array_map('intval', array_keys($stockLic))) . ")");
                    $keyOf->execute([$ACCOUNT_ID]);
                    $hide = [];
                    foreach ($keyOf->fetchAll() as $k) {
                        $serial = trim((string)($k['serial_key'] ?? ''));
                        if ($serial === '' || in_array($serial, array_map('trim', $stockLic[(int)$k['id']] ?? []), true)) $hide[] = (int)$k['id'];
                    }
                    if ($hide) $sql .= " AND p.id NOT IN (" . implode(',', $hide) . ")";
                }
            } catch (\Throwable $e) { error_log('[licenses] stock item filter skipped: ' . $e->getMessage()); }
        }
        if ($statusFilter && in_array($statusFilter, ['active','expired','cancelled','suspended','pending'], true)) {
            $sql .= " AND p.status = ?";
            $args[] = $statusFilter;
        }
        if ($q !== '') {
            // Case-insensitive search across the key identity fields. Bound
            // parameters — never string-interpolated — so SQL injection isn't
            // reachable here.
            $sql .= " AND (eu.name LIKE ? OR eu.handle LIKE ? OR eu.email LIKE ? OR p.username LIKE ? OR p.serial_key LIKE ? OR pr.name LIKE ? OR pr.sku LIKE ?)";
            $like = '%' . $q . '%';
            for ($i = 0; $i < 7; $i++) $args[] = $like;
        }
        $sql .= " ORDER BY p.purchased_at DESC LIMIT 500";
        $stmt = $pdo->prepare($sql);
        $stmt->execute($args);
        $rows = $stmt->fetchAll();
        $licenses = array_map(function($r) {
            return [
                'id'             => (int)$r['id'],
                'product_id'     => (int)$r['product_id'],
                'product_name'   => $r['product_name'],
                'product_sku'    => $r['product_sku'],
                'product_type'   => $r['product_type'],
                'product_price'  => $r['product_price'],
                'allowUsername'  => !empty($r['allow_username']),
                'allowSerial'    => !empty($r['allow_serial']),
                'allowAccountCreation' => !empty($r['allow_account_creation']),
                'end_user_id'    => (int)$r['eu_id'],
                'conv_id'        => $r['conv_id'],
                'customer_name'  => $r['eu_name'],
                'customer_handle'=> $r['eu_handle'],
                'customer_email' => $r['eu_email'],
                'customer_phone' => $r['eu_phone'],
                'customer_avatar'=> $r['eu_avatar'],
                'platform'       => $r['eu_platform'],
                'purchased_at'   => $r['purchased_at'],
                'expires_at'     => $r['expires_at'],
                'status'         => $r['status'],
                'serial_key'     => $r['serial_key'],
                'username'       => $r['username'],
                'notes'          => $r['notes'],
                // Payment that issued the license (null when added by hand).
                'payment_tx_id'     => $r['tx_id'] !== null ? (int)$r['tx_id'] : null,
                'payment_amount'    => $r['tx_amount'] ?? null,
                'payment_currency'  => $r['tx_currency'] ?? null,
                'payment_reference' => $r['tx_reference'] ?? null,
                'paid_at'           => $r['tx_created_at'] ?? null,
                'delivered_at'      => $r['tx_delivered_at'] ?? null,
            ];
        }, $rows);
        ok(['licenses' => $licenses]);

    // ── Get this account's license-API key (creating one if missing) ──
    // Stored in bc_credentials under key=license_api_key, scoped per-account
    // by the existing UNIQUE (account_id, key) index. The key is a
    // 32-byte hex string from random_bytes — long enough that brute-force
    // guessing is infeasible at any realistic rate-limit ceiling.
    case 'get_license_api_key':
        $s = $pdo->prepare("SELECT value FROM bc_credentials WHERE account_id=? AND `key`=?");
        $s->execute([$ACCOUNT_ID, 'license_api_key']);
        $key = (string)($s->fetchColumn() ?: '');
        if ($key === '') {
            $key = bin2hex(random_bytes(32));
            $pdo->prepare("INSERT INTO bc_credentials (account_id, `key`, value) VALUES (?,?,?)
                ON DUPLICATE KEY UPDATE value=VALUES(value)")
                ->execute([$ACCOUNT_ID, 'license_api_key', $key]);
        }
        ok(['api_key' => $key]);

    case 'regen_license_api_key':
        $key = bin2hex(random_bytes(32));
        $pdo->prepare("INSERT INTO bc_credentials (account_id, `key`, value) VALUES (?,?,?)
            ON DUPLICATE KEY UPDATE value=VALUES(value)")
            ->execute([$ACCOUNT_ID, 'license_api_key', $key]);
        ok(['api_key' => $key]);

    case 'add_end_user_transaction':
        $eid = (int)($body['end_user_id'] ?? 0);
        if (!$eid) err('end_user_id required');
        own_end_user($pdo, $ACCOUNT_ID, $eid);
        $pid = isset($body['product_id']) && (int)$body['product_id'] > 0 ? (int)$body['product_id'] : null;
        if ($pid) own_product($pdo, $ACCOUNT_ID, $pid);
        $stmt = $pdo->prepare("INSERT INTO bc_end_user_transactions (account_id, end_user_id, product_id, amount, currency, status, reference, notes) VALUES (?,?,?,?,?,?,?,?)");
        $stmt->execute([
            $ACCOUNT_ID, $eid, $pid,
            (string)($body['amount']    ?? ''),
            (string)($body['currency']  ?? 'USD'),
            (string)($body['status']    ?? 'completed'),
            (string)($body['reference'] ?? ''),
            (string)($body['notes']     ?? ''),
        ]);
        // A transaction the operator records by hand counts the same as one
        // the AI banked — if it's completed, this contact has bought. The
        // conversation has to be looked up because this endpoint is keyed on
        // the end user rather than the conversation.
        if (strtolower((string)($body['status'] ?? 'completed')) === 'completed') {
            try {
                $cq = $pdo->prepare("SELECT conv_id FROM bc_end_users WHERE id=? AND account_id=?");
                $cq->execute([$eid, $ACCOUNT_ID]);
                $cid = (string)$cq->fetchColumn();
                if ($cid !== '') conv_mark_customer($pdo, $ACCOUNT_ID, $cid);
            } catch (\Throwable $e) {
                error_log('[stage] manual txn promote failed: ' . $e->getMessage());
            }
        }
        ok(['id' => (int)$pdo->lastInsertId()]);

    case 'delete_end_user_transaction':
        $id = (int)($body['id'] ?? 0);
        if (!$id) err('id required');
        $pdo->prepare("DELETE FROM bc_end_user_transactions WHERE id=? AND account_id=?")->execute([$id, $ACCOUNT_ID]);
        ok();

    // ── Record a confirmed crypto invoice as a transaction + auto-issue ──
    // Front-end calls this from the `invoiceConfirmed` event handler. The
    // invoice metadata lives in PAYMENTS_STORE (CRED_STORE-backed JSON);
    // this endpoint promotes it to a first-class bc_end_user_transactions
    // row so:
    //   1. It shows up in pipeline.transactions for the AI to read.
    //   2. The license auto-issuer can consume it (one txn → one license).
    //
    // Idempotency: keyed on (account_id, reference). The same invoice id
    // arriving twice (network retry, polling race) inserts only once and
    // the second call returns the original transaction_id + license_id.
    case 'record_invoice_payment':
        bc_act_record_invoice_payment($pdo, (int)$ACCOUNT_ID, $body);
        err('No response');

    // ── INTERNAL: confirm post-payment delivery completed ─────────────
    // Called by the FE AFTER it has successfully pushed every part of
    // the delivery payload (text + attachments) returned by
    // record_invoice_payment. This stamps `delivered_at` so subsequent
    // polling-watchdog replays of invoiceConfirmed see already_delivered
    // and skip re-dispatch. If the FE never reaches this call (network
    // drop, bridge crash, page reload mid-dispatch), the txn stays
    // un-stamped and the watchdog will re-fire on its next pass — which
    // is exactly what we want (auto-recovery without operator action).
    case 'confirm_delivery':
        $txId = isset($body['transaction_id']) ? (int)$body['transaction_id'] : 0;
        if ($txId <= 0) err('transaction_id required');
        // Ownership check + must already be a completed txn before we'll
        // stamp it. Prevents a malicious FE from forging delivery on a
        // txn it doesn't own / on one that hasn't actually been paid.
        $own = $pdo->prepare("SELECT id, status FROM bc_end_user_transactions
                                WHERE id = ? AND account_id = ?");
        $own->execute([$txId, $ACCOUNT_ID]);
        $tx = $own->fetch();
        if (!$tx) err('transaction not found');
        if (($tx['status'] ?? '') !== 'completed') err('transaction not completed');
        $res = confirm_delivery_for_transaction($pdo, $ACCOUNT_ID, $txId);
        ok($res);

    // ── PUBLIC: verify a licence ──────────────────────────────────────
    // Auth: api_key (GET, POST, JSON body, or X-API-Key header).
    // Lookup by any of { username | serial | email }, optionally narrowed
    // by product_sku. Stable response shape so callers branch on
    // .valid / .status instead of parsing prose.
    case 'verify_license':

        // ── Input collection ──────────────────────────────────────────
        // The HTML form POSTs (keeps the key out of the URL), machines
        // usually GET or POST JSON, so read all three sources.
        $vlIn = function (string $name, $default = '') use ($body) {
            foreach ([$_POST, $_GET, $body] as $src) {
                if (is_array($src) && isset($src[$name]) && $src[$name] !== '') {
                    return $src[$name];
                }
            }
            return $default;
        };

        // The console form sends one lookup field plus a picker (lookup_by)
        // instead of three boxes. Map it back onto the named field so the
        // rest of the endpoint reads serial / username / email as always.
        $lkByIn  = strtolower(trim((string)($_POST['lookup_by'] ?? '')));
        $lkValIn = trim((string)($_POST['lookup'] ?? ''));
        if (in_array($lkByIn, ['serial', 'username', 'email'], true) && $lkValIn !== '' && empty($_POST[$lkByIn])) {
            $_POST[$lkByIn] = $lkValIn;
        }

        $isPost    = ($_SERVER['REQUEST_METHOD'] === 'POST');
        $accept    = (string)($_SERVER['HTTP_ACCEPT'] ?? '');
        $formatIn  = strtolower(trim((string)$vlIn('format', '')));
        $isFormPost = $isPost && !empty($_POST);   // real <form>, not JSON

        $wantsHtml = false;
        if ($formatIn === 'html') {
            $wantsHtml = true;                      // explicit, incl. the form
        } elseif ($formatIn === 'json') {
            $wantsHtml = false;                     // explicit override
        } elseif (!$isPost && stripos($accept, 'text/html') !== false) {
            $wantsHtml = true;                      // browser address bar
        } elseif ($isFormPost && stripos($accept, 'text/html') !== false) {
            $wantsHtml = true;                      // form post without the hidden field
        }

        $vlUrls = bc_self_urls();

        // ── The console page ──────────────────────────────────────────
        // One closure, called from every branch (empty form, auth error,
        // rate limit, hit, miss) so the chrome never diverges.
        $renderHtml = function (array $opts) use ($vlUrls) {
            $esc = fn($v) => htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8');

            $apiKey   = (string)($opts['apiKey']   ?? '');
            $username = (string)($opts['username'] ?? '');
            $serial   = (string)($opts['serial']   ?? '');
            $email    = (string)($opts['email']    ?? '');
            $sku      = (string)($opts['sku']      ?? '');
            $reveal   = !empty($opts['reveal']);
            $state    = (string)($opts['state'] ?? 'form');
            $resp     = is_array($opts['resp'] ?? null) ? $opts['resp'] : null;
            $error    = (string)($opts['error'] ?? '');
            $diag     = is_array($opts['diag'] ?? null) ? $opts['diag'] : null;

            $endpoint = $vlUrls['verify_endpoint'];
            $apiBase  = $vlUrls['api'];

            // JSON exactly as a server integration would receive it.
            $rawJson = $resp !== null
                ? json_encode($resp, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE)
                : '';

            // A GET link that reproduces this same check as JSON. Only
            // offered once a check has actually run, and it deliberately
            // carries the key — the operator asked to see the raw output.
            $jsonLink = '';
            if ($resp !== null && $apiKey !== '') {
                $q = ['action' => 'verify_license', 'format' => 'json', 'api_key' => $apiKey];
                if ($username !== '') $q['username']    = $username;
                if ($serial   !== '') $q['serial']      = $serial;
                if ($email    !== '') $q['email']       = $email;
                if ($sku      !== '') $q['product_sku'] = $sku;
                if ($reveal)          $q['reveal']      = '1';
                $jsonLink = $apiBase . '?' . http_build_query($q);
            }

            // ── Page ──────────────────────────────────────────────────
            // One focused column in the panel's own look: the glass card,
            // filled groups of label / value rows, small grey captions and
            // the accent the operator picked (read from the panel's saved
            // theme on this same origin, purple if there is none). The
            // result appears under the form; integration code and the
            // status reference fold away until they are wanted.
            $ico = function (string $name, int $s = 14) {
                $p = [
                    'key'   => '<circle cx="7.5" cy="15.5" r="4.5"/><path d="M10.7 12.3 21 2M17 6l3 3M15 8l2 2"/>',
                    'eye'   => '<path d="M2 12s3.6-7 10-7 10 7 10 7-3.6 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/>',
                    'copy'  => '<rect x="9" y="9" width="12" height="12" rx="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/>',
                    'chev'  => '<polyline points="9 18 15 12 9 6"/>',
                    'down'  => '<polyline points="6 9 12 15 18 9"/>',
                    'ext'   => '<path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"/><polyline points="15 3 21 3 21 9"/><line x1="10" y1="14" x2="21" y2="3"/>',
                    'check' => '<path d="M20 6 9 17l-5-5"/>',
                    'code'  => '<polyline points="16 18 22 12 16 6"/><polyline points="8 6 2 12 8 18"/>',
                    'list'  => '<line x1="8" y1="6" x2="21" y2="6"/><line x1="8" y1="12" x2="21" y2="12"/><line x1="8" y1="18" x2="21" y2="18"/><line x1="3" y1="6" x2="3.01" y2="6"/><line x1="3" y1="12" x2="3.01" y2="12"/><line x1="3" y1="18" x2="3.01" y2="18"/>',
                ][$name] ?? '';
                return '<svg width="' . $s . '" height="' . $s . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' . $p . '</svg>';
            };
            $row = function (string $label, string $valueHtml, bool $mono = false) use ($esc) {
                return '<div class="row"><span class="lbl">' . $esc($label) . '</span><span class="val' . ($mono ? ' m' : '') . '">' . $valueHtml . '</span></div>';
            };

            // ── Result ────────────────────────────────────────────────
            $result = '';
            $tone = ''; $title = ''; $sub = ''; $note = ''; $rows = ''; $badge = '';

            if ($state === 'auth_error' || $state === 'rate_limited') {
                $isRate = ($state === 'rate_limited');
                $tone  = 'bad';
                $title = $isRate ? 'Too many checks' : 'Key not accepted';
                $sub   = $error ?: 'The request was rejected.';
                $note  = $isRate
                    ? 'Each key allows 60 checks a minute. Try again shortly.'
                    : 'Copy the current key from Licenses › License API in the panel.';
                $badge = $isRate ? '429' : '401';

            } elseif ($state === 'not_found') {
                $tone  = 'warn';
                $title = 'No match';
                $sub   = 'Nothing in this account matches those details.';
                $note  = 'Serials are case-sensitive and include the dashes.';
                $badge = 'valid: false';
                if ($diag) {
                    if (!empty($diag['serial_exists_under_other_account'])) {
                        $note = 'That serial exists, but under a different account. Use the key from the account that sold it.';
                    } elseif (!empty($diag['hint'])) {
                        $note = (string)$diag['hint'];
                    }
                    $rows .= $row('Key account', '#' . $esc($diag['resolved_account_id'] ?? '?'), true);
                    $rows .= $row('Licenses', $esc($diag['licenses_in_account'] ?? '?'), true);
                }

            } elseif ($state === 'valid' || $state === 'invalid') {
                $isValid  = ($state === 'valid');
                $status   = strtolower((string)($resp['status'] ?? 'unknown'));
                $days     = $resp['days_remaining'] ?? null;
                $expires  = (string)($resp['expires_at'] ?? '');
                $bought   = (string)($resp['purchased_at'] ?? '');
                $prodName = (string)($resp['product']['name'] ?? '');

                $tone  = $isValid ? 'good' : 'warn';
                $title = ucfirst($status);
                $badge = $isValid ? 'valid: true' : 'valid: false';
                if ($isValid) {
                    if (is_int($days))       $sub = $days . ' day' . ($days === 1 ? '' : 's') . ' left';
                    elseif ($expires === '') $sub = 'No expiry';
                    else                     $sub = 'Until ' . substr($expires, 0, 10);
                    $note = 'Let the customer in.';
                } else {
                    $sub = [
                        'expired'   => 'The term has ended',
                        'cancelled' => 'Revoked',
                        'suspended' => 'On hold',
                        'pending'   => 'Payment not settled',
                    ][$status] ?? 'Not currently valid';
                    if ($status === 'expired' && is_int($days) && $days < 0) {
                        $sub = 'Ended ' . abs($days) . ' day' . (abs($days) === 1 ? '' : 's') . ' ago';
                    }
                    $note = [
                        'expired'   => 'Ask the customer to renew. The serial stays the same.',
                        'cancelled' => 'Do not honour this license.',
                        'suspended' => 'Treat it as blocked. It can be switched back on later.',
                        'pending'   => 'Nothing to honour until payment settles.',
                    ][$status] ?? 'Do not honour this license.';
                }

                $rows .= $row('Product', $esc($prodName ?: 'Unnamed product'));
                $rows .= $row('Expires', $expires ? $esc(substr($expires, 0, 10)) : 'Never');
                if ($bought) $rows .= $row('Purchased', $esc(substr($bought, 0, 10)));
                if (!empty($resp['matched_by'])) {
                    $mb = ['serial' => 'Serial key', 'username' => 'Username', 'handle' => 'Chat handle', 'email' => 'Email'][$resp['matched_by']] ?? $resp['matched_by'];
                    $rows .= $row('Matched on', $esc($mb));
                }
                if (!empty($resp['serial_key'])) $rows .= $row('Serial', $esc($resp['serial_key']), true);
                if (!empty($resp['username']))   $rows .= $row('Username', $esc($resp['username']), true);
                if (isset($resp['customer']) && is_array($resp['customer'])) {
                    $c = $resp['customer'];
                    if (!empty($c['name']))   $rows .= $row('Customer', $esc($c['name']));
                    if (!empty($c['handle'])) $rows .= $row('Handle', '@' . $esc($c['handle']), true);
                    if (!empty($c['email']))  $rows .= $row('Email', $esc($c['email']), true);
                }
            }

            if ($tone !== '') {
                $result  = '<section class="card res" id="result" data-tone="' . $tone . '" aria-live="polite">';
                $result .= '<div class="res-hd"><span class="res-dot" aria-hidden="true"></span>'
                         . '<div class="res-txt"><h2>' . $esc($title) . '</h2>'
                         . ($sub !== '' ? '<p>' . $esc($sub) . '</p>' : '') . '</div>'
                         . ($badge !== '' ? '<span class="badge m">' . $esc($badge) . '</span>' : '')
                         . '</div>';
                if ($note !== '') $result .= '<p class="res-note">' . $esc($note) . '</p>';
                if ($rows !== '') $result .= '<div class="group">' . $rows . '</div>';
                if ($rawJson !== '') {
                    $result .= '<details class="fold raw"><summary><span>Response</span><span class="sum">What your server receives</span>' . $ico('chev', 12) . '</summary>'
                             . '<div class="raw-body"><pre id="jsonout">' . $esc($rawJson) . '</pre>'
                             . '<div class="raw-acts">'
                             . '<button type="button" class="btn-ghost" data-copy="json">' . $ico('copy', 12) . '<span>Copy</span></button>';
                    if ($jsonLink !== '') {
                        $result .= '<button type="button" class="btn-ghost" data-copy="link">' . $ico('copy', 12) . '<span>Copy URL</span></button>'
                                 . '<a class="btn-ghost" href="' . $esc($jsonLink) . '" target="_blank" rel="noopener noreferrer">' . $ico('ext', 12) . '<span>Open</span></a>'
                                 . '<span id="jsonlink" hidden>' . $esc($jsonLink) . '</span>';
                    }
                    $result .= '</div></div></details>';
                }
                $result .= '</section>';
            }

            // ── Form state ────────────────────────────────────────────
            // One lookup field with a picker in place of three boxes. The
            // picker posts lookup_by + lookup, which the endpoint maps back
            // onto serial / username / email, so it works without script.
            $lkBy  = $serial !== '' ? 'serial' : ($username !== '' ? 'username' : ($email !== '' ? 'email' : 'serial'));
            $lkVal = ['serial' => $serial, 'username' => $username, 'email' => $email][$lkBy];
            $lkPh  = ['serial' => 'ABCD-1234-EFGH-5678', 'username' => 'alice', 'email' => 'customer@example.com'][$lkBy];
            $opt   = function ($v, $l) use ($lkBy) { return '<option value="' . $v . '"' . ($lkBy === $v ? ' selected' : '') . '>' . $l . '</option>'; };
            $checked = $reveal ? ' checked' : '';
            $self    = $esc(strtok((string)$_SERVER['REQUEST_URI'], '?') ?: '/api.php');

            if (!headers_sent()) {
                header('Content-Type: text/html; charset=utf-8');
                // A page that renders a secret should never be cached or indexed.
                header('Cache-Control: no-store, max-age=0');
                header('X-Robots-Tag: noindex, nofollow');
                header('Referrer-Policy: no-referrer');
            }

            $css = <<<'CSS'
:root{
  --acc:#4e9a6c;
  --t1:#eeeef5; --t2:#c8c9d8; --t3:#8a8aa8; --t4:#6a6c86;
  --line:rgba(255,255,255,.065); --field:rgba(255,255,255,.035);
  --good:#58be8c; --warn:#dea85c; --bad:#e66e68;
  --font:"Inter",-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;
  --mono:"JetBrains Mono",ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;
}
*{box-sizing:border-box;margin:0;padding:0}
html{-webkit-text-size-adjust:100%;background:var(--fxb1,#05060a)}
body{min-height:100vh;color:var(--t1);font:400 13px/1.5 var(--font);font-feature-settings:"cv11","ss01";
  -webkit-font-smoothing:antialiased;padding:32px 20px;position:relative;
  display:flex;flex-direction:column;justify-content:center}
/* The panel's own background (style, palette, speed) sits underneath,
   toned down by .bg-dim so it reads as ambience behind a tool page. */
.bg-dim{position:fixed;inset:0;z-index:0;pointer-events:none;background:rgba(4,5,10,.32)}
.wrap{position:relative;z-index:1;width:100%;max-width:520px;margin:0 auto;display:flex;flex-direction:column;gap:14px}
a{color:inherit}
:focus-visible{outline:none;box-shadow:0 0 0 2px color-mix(in oklab,var(--acc) 55%,transparent)}
.m{font-family:var(--mono);font-size:11.5px;letter-spacing:0}
.dim{color:var(--t3)}

/* header */
.hd{display:flex;align-items:center;gap:12px;padding:0 2px 6px}
.mark{flex:0 0 auto;width:34px;height:34px;border-radius:10px;display:inline-flex;align-items:center;justify-content:center;
  color:color-mix(in oklab,var(--acc) 30%,#f3f3f8);background:color-mix(in oklab,var(--acc) 16%,transparent);
  box-shadow:inset 0 0 0 1px color-mix(in oklab,var(--acc) 34%,transparent)}
.hd h1{font-size:16px;font-weight:600;letter-spacing:-.018em;line-height:1.25}
.hd p{margin-top:2px;font-size:12px;color:var(--t3)}

/* glass card, as the panel's settings windows */
.card{background:rgba(12,13,24,.66);-webkit-backdrop-filter:blur(24px) saturate(180%);backdrop-filter:blur(24px) saturate(180%);
  border:1px solid rgba(255,255,255,.09);border-radius:16px;
  box-shadow:inset 0 1px 0 rgba(255,255,255,.06),0 24px 60px -16px rgba(0,0,0,.65),0 4px 14px rgba(0,0,0,.28)}
.card-body{padding:16px;display:flex;flex-direction:column;gap:14px}
.sec{display:flex;flex-direction:column;gap:6px}
.cap{padding:0 2px;font-size:11px;font-weight:550;color:rgba(172,176,198,.72);letter-spacing:-.003em}

/* filled groups of rows */
.group{border-radius:10px;background:var(--field);box-shadow:inset 0 0 0 .5px rgba(255,255,255,.07);overflow:hidden;
  transition:box-shadow .16s ease}
.group:focus-within{box-shadow:inset 0 0 0 .5px rgba(255,255,255,.07),0 0 0 1.5px color-mix(in oklab,var(--acc) 55%,transparent)}
.row{position:relative;display:flex;align-items:center;gap:10px;min-height:40px;padding:0 12px}
.row+.row::before{content:"";position:absolute;top:0;left:12px;right:0;height:1px;background:rgba(255,255,255,.055)}
.lbl{flex:0 0 92px;font-size:12px;font-weight:500;color:rgba(186,190,212,.8);white-space:nowrap}
.val{flex:1 1 auto;min-width:0;font-size:12.5px;color:var(--t1);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.val.m{font-size:11.5px}
.row input[type=text],.row input[type=email],.row input[type=password]{flex:1 1 auto;min-width:0;height:40px;padding:0;border:none;outline:none;
  background:transparent;box-shadow:none;font:inherit;font-size:12.5px;color:var(--t1);letter-spacing:-.008em}
.row input.m{font-family:var(--mono);font-size:11.5px;letter-spacing:0}
.row input::placeholder{color:rgba(160,164,184,.42)}
.row input:focus-visible{box-shadow:none}
.sel{position:relative;flex:0 0 92px;display:inline-flex;align-items:center;gap:4px;height:40px;font-size:12px;font-weight:500;color:var(--t1);cursor:pointer}
.sel svg{color:rgba(160,164,184,.6)}
.sel select{position:absolute;inset:0;width:100%;opacity:0;cursor:pointer;color-scheme:dark;font:inherit}
.icon-btn{flex:0 0 auto;width:26px;height:26px;margin-right:-6px;border:none;border-radius:7px;background:transparent;cursor:pointer;
  display:inline-flex;align-items:center;justify-content:center;color:rgba(160,164,184,.7);transition:background-color .12s,color .12s}
.icon-btn:hover{background:rgba(255,255,255,.06);color:var(--t1)}
.icon-btn[aria-pressed=true]{color:color-mix(in oklab,var(--acc) 40%,#eeeef5)}

/* switch row */
.sw{cursor:pointer}
.sw-txt{flex:1 1 auto;min-width:0;display:flex;flex-direction:column;gap:1px;padding:7px 0}
.sw-title{font-size:12.5px;font-weight:500;color:var(--t1);letter-spacing:-.008em}
.sw-hint{font-size:10.5px;color:rgba(160,164,184,.66)}
.sw input{appearance:none;-webkit-appearance:none;flex:0 0 26px;width:26px;height:15px;border-radius:999px;margin:0;cursor:pointer;position:relative;
  background:rgba(255,255,255,.1);box-shadow:inset 0 0 0 1px rgba(255,255,255,.05);transition:background-color .16s}
.sw input::after{content:"";position:absolute;top:2px;left:2px;width:11px;height:11px;border-radius:50%;background:rgba(220,222,235,.72);
  box-shadow:0 1px 2px rgba(0,0,0,.35);transition:transform .16s cubic-bezier(.22,1,.36,1),background-color .16s}
.sw input:checked{background:color-mix(in oklab,var(--acc) 82%,#1a1b2c)}
.sw input:checked::after{transform:translateX(11px);background:#fff}

/* footer of a card */
.card-foot{display:flex;align-items:center;gap:8px;padding:10px 16px 12px;border-top:1px solid rgba(255,255,255,.05)}
.foot-note{flex:1 1 auto;min-width:0;font-size:11px;color:var(--t4)}
.card-foot .btn{margin-left:auto}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:6px;height:30px;padding:0 14px;border:none;border-radius:8px;cursor:pointer;
  font:inherit;font-size:12px;font-weight:600;letter-spacing:-.005em;color:#fff;background:color-mix(in oklab,var(--acc) 88%,#15162a);
  box-shadow:inset 0 1px 0 rgba(255,255,255,.12);transition:background-color .12s,transform .08s}
.btn:hover{background:color-mix(in oklab,var(--acc) 92%,#fff)}
.btn:active{transform:scale(.97)}
.btn-ghost{display:inline-flex;align-items:center;gap:5px;height:26px;padding:0 9px;border:none;border-radius:7px;cursor:pointer;text-decoration:none;
  font:inherit;font-size:11.5px;font-weight:500;color:rgba(190,194,214,.85);background:rgba(255,255,255,.05);
  box-shadow:inset 0 0 0 1px rgba(255,255,255,.07);transition:background-color .12s,color .12s}
.btn-ghost:hover{color:var(--t1);background:rgba(255,255,255,.08)}
.btn-ghost[data-ok="1"]{color:var(--good)}

/* result */
.res{padding:16px;display:flex;flex-direction:column;gap:12px;scroll-margin-top:24px}
.res{--tone:var(--good)}
.res[data-tone=warn]{--tone:var(--warn)}
.res[data-tone=bad]{--tone:var(--bad)}
.res-hd{display:flex;align-items:center;gap:11px}
.res-dot{flex:0 0 auto;width:30px;height:30px;border-radius:9px;position:relative;
  background:color-mix(in oklab,var(--tone) 15%,transparent);box-shadow:inset 0 0 0 1px color-mix(in oklab,var(--tone) 35%,transparent)}
.res-dot::after{content:"";position:absolute;inset:0;margin:auto;width:8px;height:8px;border-radius:50%;background:var(--tone);
  box-shadow:0 0 10px color-mix(in oklab,var(--tone) 70%,transparent)}
.res-txt{flex:1 1 auto;min-width:0}
.res-txt h2{font-size:15px;font-weight:600;letter-spacing:-.015em;line-height:1.25}
.res-txt p{font-size:12px;color:var(--t3);margin-top:1px}
.badge{flex:0 0 auto;height:22px;padding:0 8px;border-radius:6px;display:inline-flex;align-items:center;font-size:10.5px;
  color:color-mix(in oklab,var(--tone) 70%,#fff);background:color-mix(in oklab,var(--tone) 12%,transparent)}
.res-note{padding:0 2px;font-size:12px;color:var(--t2)}

/* folds */
.fold{border-radius:10px;background:var(--field);box-shadow:inset 0 0 0 .5px rgba(255,255,255,.07);overflow:hidden}
.card.fold{border-radius:16px;background:rgba(12,13,24,.66);box-shadow:inset 0 1px 0 rgba(255,255,255,.06),0 24px 60px -16px rgba(0,0,0,.65),0 4px 14px rgba(0,0,0,.28)}
.card.fold>summary{min-height:44px;padding:0 14px}
.fold>summary{list-style:none;display:flex;align-items:center;gap:10px;min-height:40px;padding:0 12px;cursor:pointer;user-select:none;
  transition:background-color .12s}
.fold>summary::-webkit-details-marker{display:none}
.fold>summary:hover{background:rgba(255,255,255,.03)}
.fold>summary>span:first-child{font-size:12.5px;font-weight:500;color:var(--t1);letter-spacing:-.008em}
.fold>summary .sum{margin-left:auto;font-size:11.5px;color:rgba(160,164,184,.6);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.fold>summary>svg{flex:0 0 auto;color:rgba(160,164,184,.55);transition:transform .16s ease}
.fold[open]>summary>svg{transform:rotate(90deg)}
.fold-ico{flex:0 0 auto;width:22px;height:22px;border-radius:6px;display:inline-flex;align-items:center;justify-content:center;
  background:rgba(255,255,255,.06);color:rgba(200,203,222,.85)}
.fold>summary .fold-ico+span{font-size:12.5px;font-weight:500;color:var(--t1)}
.raw-body{border-top:1px solid rgba(255,255,255,.055)}
pre{margin:0;padding:12px;font-family:var(--mono);font-size:11px;line-height:1.65;color:#c3c6d8;overflow-x:auto;white-space:pre;
  scrollbar-width:thin;scrollbar-color:rgba(255,255,255,.12) transparent}
.raw-acts{display:flex;flex-wrap:wrap;gap:6px;padding:0 12px 12px}

/* integration */
.int{display:flex;flex-direction:column;gap:10px;padding:2px 12px 12px;border-top:1px solid rgba(255,255,255,.055)}
.int .group{background:rgba(0,0,0,.18)}
.ep{margin-top:10px}
.int>*{min-width:0}
.ep .val{font-family:var(--mono);font-size:11px;color:var(--t2)}
.tabs{display:flex;gap:2px;padding:2px;border-radius:9px;background:rgba(255,255,255,.03);box-shadow:inset 0 0 0 1px rgba(255,255,255,.06)}
.tabs button{flex:1 1 0;height:24px;border:none;border-radius:7px;background:transparent;cursor:pointer;font:inherit;font-size:11.5px;font-weight:500;
  color:rgba(160,164,184,.8);transition:background-color .14s,color .14s}
.tabs button:hover{color:var(--t1)}
.tabs button[aria-selected=true]{color:var(--t1);font-weight:600;background:color-mix(in oklab,var(--acc) 15%,transparent);
  box-shadow:inset 0 0 0 1px color-mix(in oklab,var(--acc) 34%,transparent)}
.snip{position:relative}
.snip[hidden]{display:none}
.snip .btn-ghost{position:absolute;top:8px;right:8px;background:rgba(20,21,36,.9)}
.snip pre{padding-right:78px}
.hint{padding:0 2px;font-size:11px;line-height:1.5;color:rgba(160,164,184,.62)}
.hint code{font-family:var(--mono);font-size:10.5px;color:var(--t2)}

/* status list */
.st{display:flex;flex-direction:column}
.st .row{align-items:flex-start;padding-top:9px;padding-bottom:9px;min-height:0}
.st .lbl{flex-basis:84px;font-family:var(--mono);font-size:11px;color:var(--t1);padding-top:1px}
.st .val{white-space:normal;font-size:11.5px;color:var(--t3);line-height:1.45}
.st i{font-style:normal;display:inline-block;width:6px;height:6px;border-radius:50%;margin-right:6px;vertical-align:1px;background:var(--bad)}
.st i.y{background:var(--good)}

.page-foot{padding:4px 2px 0;font-size:11px;color:var(--t4);text-align:center}
@media(max-width:480px){body{padding:20px 12px}.lbl,.sel{flex-basis:78px}.foot-note{display:none}}
@media(prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}}
CSS;

            // ── Integration snippets, built against THIS deployment ──
            $ep       = $esc($endpoint);
            $epRaw    = $endpoint;
            $keyDemo  = $apiKey !== '' ? $apiKey : 'YOUR_API_KEY';

            $snipCurl = $esc(
                "curl -s -X POST '{$epRaw}' \\\n"
              . "  -H 'Content-Type: application/json' \\\n"
              . "  -d '{\"api_key\":\"{$keyDemo}\",\"serial\":\"ABCD-1234-EFGH-5678\"}'"
            );
            $snipPhp = $esc(
                "<?php\n"
              . "function license_is_active(string \$serial): bool {\n"
              . "    \$ch = curl_init('{$epRaw}');\n"
              . "    curl_setopt_array(\$ch, [\n"
              . "        CURLOPT_POST           => true,\n"
              . "        CURLOPT_RETURNTRANSFER => true,\n"
              . "        CURLOPT_TIMEOUT        => 8,\n"
              . "        CURLOPT_HTTPHEADER     => ['Content-Type: application/json'],\n"
              . "        CURLOPT_POSTFIELDS     => json_encode([\n"
              . "            'api_key' => '{$keyDemo}',\n"
              . "            'serial'  => \$serial,\n"
              . "        ]),\n"
              . "    ]);\n"
              . "    \$out  = curl_exec(\$ch);\n"
              . "    \$code = curl_getinfo(\$ch, CURLINFO_HTTP_CODE);\n"
              . "    curl_close(\$ch);\n\n"
              . "    // Never fail open: a network error is not a valid license.\n"
              . "    if (\$code !== 200) return false;\n"
              . "    \$data = json_decode(\$out, true);\n"
              . "    return !empty(\$data['valid']);\n"
              . "}\n"
            );
            $snipJs = $esc(
                "// Server side only. Never ship the API key to a browser.\n"
              . "async function licenseIsActive(serial) {\n"
              . "  const res = await fetch('{$epRaw}', {\n"
              . "    method:  'POST',\n"
              . "    headers: { 'Content-Type': 'application/json' },\n"
              . "    body:    JSON.stringify({ api_key: process.env.LICENSE_API_KEY, serial }),\n"
              . "  });\n"
              . "  if (!res.ok) return false;\n"
              . "  const data = await res.json();\n"
              . "  return data.valid === true;\n"
              . "}\n"
            );
            $snipPy = $esc(
                "import os, requests\n\n"
              . "def license_is_active(serial: str) -> bool:\n"
              . "    try:\n"
              . "        r = requests.post(\n"
              . "            '{$epRaw}',\n"
              . "            json={'api_key': os.environ['LICENSE_API_KEY'], 'serial': serial},\n"
              . "            timeout=8,\n"
              . "        )\n"
              . "    except requests.RequestException:\n"
              . "        return False          # never fail open\n"
              . "    if r.status_code != 200:\n"
              . "        return False\n"
              . "    return bool(r.json().get('valid'))\n"
            );

            // Theme: the panel saves its colours to localStorage on this
            // same origin. Read them before first paint so the page opens in
            // the operator's own accent and background, not a stock purple.
            $themeJs = <<<'JS'
(function(){try{var root=document.documentElement,ds=root.dataset;
ds.bg='mist';ds.fxSpeed='medium';ds.vignette='1';ds.grain='1';
var snap=JSON.parse(localStorage.getItem('bc.theme.boot')||'null');
if(snap&&snap.rev===3){var k;
  if(snap.ds)for(k in snap.ds)if(Object.prototype.hasOwnProperty.call(snap.ds,k)&&/^[a-zA-Z]+$/.test(k))ds[k]=String(snap.ds[k]);
  if(snap.vars)for(k in snap.vars)if(/^--[a-z0-9-]+$/.test(k)&&snap.vars[k]&&!/[;{}<>]/.test(snap.vars[k]))root.style.setProperty(k,String(snap.vars[k]).trim());}
var i=parseFloat(getComputedStyle(root).getPropertyValue('--fx-int'))||0.48;
root.style.setProperty('--fx-int',String(Math.round(i*0.6*1000)/1000));
document.addEventListener('DOMContentLoaded',function(){var b=document.querySelector('.bg-base');if(b&&ds.bg)b.setAttribute('data-bg',ds.bg);});
}catch(e){}})();
