            $pageJs = <<<'JS'
(function(){
var $=function(s,r){return (r||document).querySelector(s)},$$=function(s,r){return Array.prototype.slice.call((r||document).querySelectorAll(s))};
var sel=$('#by'),lk=$('#lk'),selTxt=$('#byTxt');
var PH={serial:'ABCD-1234-EFGH-5678',username:'alice',email:'customer@example.com'};
var LB={serial:'Serial key',username:'Username',email:'Email'};
function syncBy(){if(!sel||!lk)return;var v=sel.value;lk.placeholder=PH[v];lk.type=v==='email'?'email':'text';
  lk.classList.toggle('m',v==='serial');if(selTxt)selTxt.textContent=LB[v];}
if(sel){sel.addEventListener('change',function(){syncBy();lk.focus();});syncBy();}
var peek=$('#peek'),kf=$('#k');
if(peek&&kf){peek.addEventListener('click',function(){var h=kf.type==='password';kf.type=h?'text':'password';peek.setAttribute('aria-pressed',h?'true':'false');});}
$$('.tabs button').forEach(function(b,i,all){b.addEventListener('click',function(){all.forEach(function(o){o.setAttribute('aria-selected','false');
  $('#'+o.getAttribute('aria-controls')).hidden=true;});b.setAttribute('aria-selected','true');$('#'+b.getAttribute('aria-controls')).hidden=false;});});
function flash(b){var s=b.querySelector('span');var t=s?s.textContent:'';if(s)s.textContent='Copied';b.setAttribute('data-ok','1');
  setTimeout(function(){if(s)s.textContent=t;b.removeAttribute('data-ok');},1400);}
function copy(txt,b){if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(txt).then(function(){flash(b)});return;}
  var a=document.createElement('textarea');a.value=txt;document.body.appendChild(a);a.select();try{document.execCommand('copy');flash(b);}catch(_){}document.body.removeChild(a);}
document.addEventListener('click',function(e){var b=e.target.closest('[data-copy]');if(!b)return;var k=b.getAttribute('data-copy'),t='';
  if(k==='snip')t=b.parentNode.querySelector('pre').textContent;
  else if(k==='json'){var j=$('#jsonout');t=j?j.textContent:'';}
  else if(k==='link'){var l=$('#jsonlink');t=l?l.textContent:'';}
  else if(k==='ep'){var p=$('#epv');t=p?p.textContent:'';}
  if(t)copy(t,b);});
})();
